// 부자되기 방법론 마인드맵 (원본 PDF의 가지와 메모를 그대로 옮김)
// n: 요점에 붙은 메모 [종류, 내용]
window.MM = [{"n":1,"t":"부자란 누구인가 — 부자의 정의와 마음가짐","c":[{"t":"Ⅰ 부자의 진짜 뜻","c":[{"t":"1. 부자를 재는 세 가지 잣대","c":[{"t":"(1) 순자산 — 내가 진짜로 가진 몫","c":[{"t":"① 순자산 = 자산 − 부채","n":[["설명","순자산이란 \"가진 것 전부(자산)\"에서 \"갚아야 할 것 전부(부채)\"를 뺀 금액입니다. 예를 들어 10억 원짜리 아파트에 살아도 대출이 7억 원이면 순자산은 3억 원입니다."]]},{"t":"② 대출 없는 집이 더 큰 몫","n":[["설명","반대로 5억 원짜리 아파트에 대출이 없으면 순자산은 5억 원입니다. 겉으로는 10억 원 아파트에 사는 사람이 더 부자처럼 보이지만, 실제로는 5억 원 아파트에 사는 사람이 더 많은 몫을 가지고 있습니다."]]},{"t":"③ 빚 뺀 금액 보는 습관","n":[["설명","그래서 부자가 되는 첫걸음은 \"얼마짜리를 가졌나\"가 아니라 \"빚을 빼고 얼마가 남나\"를 보는 습관입니다."],["쉬운 예","친구가 장난감 상자 10개를 가지고 있는데 그중 7개는 다른 친구에게 빌린 것이라면, 진짜 그 친구 것은 3개뿐입니다. 순자산은 \"빌린 것을 돌려주고 남는 내 장난감 수\"와 같습니다."]]}],"h":"순·대·빚 → 순대빚 → 순대 빚 → 자산−부채·빚 없는 집·빚 빼고 보기"},{"t":"(2) 현금흐름 — 매달 들어오는 돈의 물줄기","c":[{"t":"① 들어온 돈 − 나간 돈","n":[["설명","현금흐름은 한 달 동안 들어오는 돈과 나가는 돈의 차이입니다. 월급, 이자, 배당, 월세 수입처럼 들어오는 돈이 나가는 돈보다 많으면 \"플러스 현금흐름\"입니다."]]},{"t":"② 집 부자, 현금 가난","n":[["설명","순자산이 많아도 현금흐름이 마이너스이면 결국 자산을 팔아서 생활해야 합니다. 예를 들어 집 한 채만 가진 은퇴자는 순자산이 많아도 매달 쓸 돈이 부족해 \"집 부자, 현금 가난\"이 될 수 있습니다."]]},{"t":"③ 자산이 만드는 월수입","n":[["설명","그래서 부자들은 자산의 크기와 함께 \"이 자산이 매달 얼마를 만들어 주는가\"를 함께 따집니다."]]}],"h":"들·집·자 → 들집자 → 들어온−나간·집 부자 현금 가난·자산이 만드는 월수입"},{"t":"(3) 선택권 — 돈이 사 주는 자유","c":[{"t":"① 돈의 최대 쓸모는 선택권","n":[["설명","돈의 가장 큰 쓸모는 물건이 아니라 선택권입니다. 싫은 일을 거절할 수 있고, 아플 때 쉴 수 있고, 좋은 기회가 왔을 때 잡을 수 있는 힘입니다."]]},{"t":"② 비상금 6개월의 여유","n":[["설명","비상금 6개월치가 있는 사람은 회사가 어려워져도 서둘러 아무 일자리나 잡지 않아도 됩니다. 이것이 돈이 주는 선택권입니다."]]},{"t":"③ 부자 정의: 세 잣대 충족","n":[["설명","이 책에서는 부자를 \"순자산이 꾸준히 늘고, 플러스 현금흐름이 있으며, 그 결과로 삶의 선택권이 넓은 사람\"이라고 정의합니다."],["핵심 포인트","부자의 세 잣대 = ① 순자산(자산 − 부채) ② 현금흐름(들어오는 돈 − 나가는 돈) ③ 선택권(돈 때문에 원치 않는 선택을 하지 않아도 되는 자유). 겉으로 보이는 소비는 잣대가 아닙니다."]]}],"h":"돈·비·부 → 돈비부 → 돈은 선택권·비상금 6개월·부자는 세 잣대"}],"h":"순·현·선 → 순현선 → 순한 현선 (순자산·현금흐름·선택권)"},{"t":"2. 보이는 부와 보이지 않는 부","c":[{"t":"(1) 보이는 부의 함정","c":[{"t":"① 보이는 부는 감가·유지비","n":[["설명","새 차, 명품 가방, 넓은 집은 남에게 보이는 부입니다. 이것들은 대부분 시간이 지나면 값이 떨어지거나, 유지비가 계속 나갑니다."]]},{"t":"② 할부는 미래 월급 선지출","n":[["설명","특히 할부와 대출로 산 물건은 \"월 납입금\"이라는 형태로 미래의 월급을 미리 써 버리는 것입니다. 월급이 올라도 할부금이 함께 늘면 남는 돈은 그대로입니다."]]},{"t":"③ 인상 시 생활수준 유지","n":[["설명","첨부 영상 자료에서도 \"월급이 오르면 먼저 생활 수준을 올리지 않는 것\"을 부자의 첫 번째 선택으로 꼽았습니다. 보이는 부를 먼저 사면 보이지 않는 부가 쌓일 자리가 사라지기 때문입니다."]]}],"h":"보·할·인 → 보할인 → 보할인 → 보이는 부·할부·인상해도 그대로"},{"t":"(2) 보이지 않는 부의 힘","c":[{"t":"① 비상금·연금·주식·기술","n":[["설명","보이지 않는 부란 통장 속 비상금, 연금 계좌, 꾸준히 사 모은 주식과 채권, 그리고 나의 기술과 신용 같은 것입니다."]]},{"t":"② 위기 방어·스스로 증식","n":[["설명","이런 부는 남에게 자랑하기 어렵지만, 위기 때 나를 지켜 주고 시간이 지날수록 스스로 불어납니다."]]},{"t":"③ 「이웃집 백만장자」 교훈","n":[["설명","미국의 연구자들이 백만장자들을 조사한 유명한 책 「이웃집 백만장자」에서도, 실제 부자 상당수가 평범한 차와 집에 살며 소득보다 훨씬 적게 쓰는 사람들이었다고 소개합니다."],["실제 사례","같은 회사, 같은 연봉(세후 월 400만 원)인 A와 B가 있습니다. A는 입사 3년 차에 월 납입금 70만 원짜리 새 차를 샀고, B는 중고 경차를 타면서 그 70만 원을 매달 투자했습니다. 10년 뒤 A의 차는 중고차 시세가 처음 값의 3분의 1 정도로 떨어졌고, B는 원금 8,400만 원에 연 5% 수익을 가정하면 약 1억 900만 원의 금융자산을 갖게 됩니다. 두 사람의 연봉은 같았지만, 10년 뒤 순자산은 1억 원 가까이 벌어졌습니다."]]}],"h":"비·위·이 → 비위이 → 비상금·위기 방어·이웃집 백만장자"}]}]},{"t":"Ⅱ 부자가 되는 생각의 습관","c":[{"t":"1. 복리를 이해하는 사람","c":[{"t":"(1) 복리란 무엇인가","c":[{"t":"① 이자에 이자가 붙는 복리","n":[["설명","복리는 \"이자에도 다시 이자가 붙는 것\"입니다. 원금 100만 원에 연 10% 이자가 붙으면 1년 뒤 110만 원, 2년 뒤에는 110만 원의 10%인 11만 원이 붙어 121만 원이 됩니다."]]},{"t":"② 단리와의 격차 확대","n":[["설명","반대로 단리는 처음 원금에만 이자가 붙습니다. 같은 조건이면 2년 뒤 120만 원입니다. 첫해에는 차이가 거의 없지만, 시간이 길어질수록 차이가 눈덩이처럼 커집니다."]]},{"t":"③ 눈덩이 굴리기 비유","n":[["설명","그래서 복리는 \"눈덩이 굴리기\"에 자주 비유됩니다. 처음엔 작지만, 굴릴수록 붙는 눈의 양이 많아집니다."],["쉬운 예","언덕 위에서 작은 눈 뭉치를 굴리면 처음 몇 바퀴는 거의 커지지 않습니다. 그런데 크기가 커질수록 한 바퀴에 붙는 눈이 많아져서, 언덕 아래에 닿을 때는 사람만 한 눈덩이가 됩니다. 돈도 같습니다. 오래 굴릴수록, 언덕(시간)이 길수록 커집니다."]]}],"h":"이·단·눈 → 이단눈 → 이자에 이자·단리와 격차·눈덩이"},{"t":"(2) 72의 법칙으로 쉽게 계산하기","c":[{"t":"① 72 ÷ 수익률 = 2배 기간","n":[["설명","72의 법칙은 \"72 ÷ 연 수익률 = 돈이 두 배가 되는 데 걸리는 햇수\"라는 간단한 계산법입니다."]]},{"t":"② 6%→12년, 8%→9년","n":[["설명","연 6%면 72 ÷ 6 = 12년, 연 8%면 9년, 연 3%면 24년 만에 돈이 두 배가 됩니다."]]},{"t":"③ 빚에도 적용: 18%→4년","n":[["설명","이 법칙은 빚에도 똑같이 적용됩니다. 연 18% 카드론 이자는 72 ÷ 18 = 4년 만에 갚을 돈을 두 배로 불립니다. 복리는 내 편일 때는 친구, 남의 편일 때는 무서운 적입니다."],["따라 해 보기","지금 1,000만 원을 연 6%로 굴리면 24년 뒤에는 대략 얼마가 될까요? 72의 법칙을 써서 계산해 보세요.\n\n결과 72 ÷ 6 = 12년마다 두 배가 됩니다. 24년이면 두 번 두 배가 되므로 1,000만 원 → 2,000만 원 → 4,000만 원, 약 4,000만 원입니다(정확한 계산값은 약 4,049만 원). 세금과 수수료를 빼면 실제로는 이보다 조금 적습니다."]],"tb":[[["연 수익률(또는 이자율)","두 배가 되는 기간(72의 법칙)","예시"],["3%","약 24년","예금·채권 위주"],["6%","약 12년","주식·채권 섞은 분산 투자"],["8%","약 9년","주식 비중이 높은 장기 투자"],["18%","약 4년","카드론·현금서비스 같은 고금리 빚"]]]}],"h":"7·6·빚 → 7 6 빚 → 72÷수익률·6%면 12년·빚에도 적용"}]},{"t":"2. 시간과 꾸준함을 믿는 사람","c":[{"t":"(1) 일찍 시작하는 것의 힘","c":[{"t":"① 10년 적립 vs 30년 적립","n":[["설명","25세부터 35세까지 10년 동안만 매달 30만 원씩 모은 뒤 멈춘 사람과, 35세부터 65세까지 30년 동안 매달 30만 원씩 모은 사람을 비교해 봅시다(연 7% 가정)."]]},{"t":"② 적게 넣고 더 많이 남김","n":[["설명","앞사람은 3,600만 원만 넣었지만 65세에 약 3억 9,000만 원 안팎이 되고, 뒷사람은 1억 800만 원을 넣어 약 3억 6,000만 원 안팎이 됩니다. 덜 넣은 앞사람이 오히려 더 많아질 수 있습니다."]]},{"t":"③ 시작 시점이 금액보다 중요","n":[["설명","이것이 \"시간이 가장 큰 자산\"이라는 말의 뜻입니다. 금액보다 시작 시점이 중요할 때가 많습니다."]]}],"h":"1·적·시 → 1적시 → 10년 vs 30년·적게 넣고 많이·시작 시점"},{"t":"(2) 꾸준함이 수익률보다 중요한 이유","c":[{"t":"① 저축률·꾸준함은 통제 가능","n":[["설명","투자 수익률은 내가 정할 수 없지만, 저축률(번 돈 중 모으는 비율)과 꾸준함은 내가 정할 수 있습니다."]]},{"t":"② 초반엔 저축액이 좌우","n":[["설명","첫 몇 년 동안은 수익률보다 저축 금액이 자산을 훨씬 크게 좌우합니다. 1,000만 원에서 10% 수익은 100만 원이지만, 매달 50만 원을 더 모으면 1년에 600만 원이 늘어납니다."]]},{"t":"③ 잘 굴리기보다 꾸준히","n":[["설명","그래서 초반에는 \"얼마나 잘 굴리나\"보다 \"얼마나 꾸준히 모으나\"에 집중하는 것이 현명합니다."],["핵심 포인트","부자가 되는 공식 = (번 돈 − 쓴 돈) × 시간 × 수익률. 이 중 내가 직접 조절할 수 있는 것은 \"번 돈, 쓴 돈, 시간\"입니다. 수익률은 마지막에 신경 써도 늦지 않습니다."]]}],"h":"저·초·잘 → 저초잘 → 저축률·초반엔 저축액·잘보다 꾸준히"}]},{"t":"3. 위험을 다루는 사람","c":[{"t":"(1) 잃지 않는 것이 먼저","c":[{"t":"① −50%면 +100% 필요","n":[["설명","50% 손실을 보면 원금을 회복하려면 100% 수익이 필요합니다. 1,000만 원이 500만 원이 되면, 500만 원이 다시 1,000만 원이 되려면 두 배가 되어야 하기 때문입니다."]]},{"t":"② 최악 손실부터 계산","n":[["설명","그래서 부자들은 \"얼마를 벌까\"보다 \"최악의 경우 얼마를 잃을 수 있나\"를 먼저 계산합니다."]]},{"t":"③ 비상금·분산·레버리지 연결","n":[["설명","이 원칙은 뒤에서 다룰 비상금, 분산 투자, 레버리지(빚 투자) 경계와 모두 연결됩니다."]]}],"h":"5·최·비 → 5최비 → −50%면 +100%·최악부터·비상금 분산"},{"t":"(2) 한 바구니에 담지 않기","c":[{"t":"① 여러 바구니에 나눠 담기","n":[["설명","분산이란 돈을 여러 곳에 나누어 담는 것입니다. 달걀을 한 바구니에 담으면 바구니를 떨어뜨렸을 때 모두 깨지지만, 여러 바구니에 나누면 일부만 깨집니다."]]},{"t":"② 자산·소득 모두 분산","n":[["설명","분산은 자산(예금·주식·채권·부동산)뿐 아니라 소득(월급·부업·배당·연금)에도 필요합니다. 첨부 영상 자료가 강조하는 \"월 300만 원짜리 소득원 하나보다 월 30만 원짜리 소득원 10개\"라는 생각도 소득의 분산입니다."]]},{"t":"③ 관리 가능한 범위로 분산","n":[["설명","다만 분산이 지나치면 관리가 어려워집니다. 자신이 이해하고 관리할 수 있는 범위 안에서 나누는 것이 좋습니다."]],"tb":[[["손실률","원금 회복에 필요한 수익률","의미"],["−10%","+11.1%","비교적 쉽게 회복"],["−20%","+25%","회복에 시간 필요"],["−30%","+42.9%","몇 년이 걸릴 수 있음"],["−50%","+100%","두 배가 되어야 본전"],["−80%","+400%","사실상 회복이 매우 어려움"]]]}],"h":"여·자·관 → 여자관 → 여러 바구니·자산 소득 분산·관리 가능 범위"}]}],"h":"복·시·위 → 복시위 → 복리·시간·위험"},{"t":"Ⅲ 2026년 11월, 지금 우리가 서 있는 자리","c":[{"t":"1. 금리와 물가","c":[{"t":"(1) 기준금리 3.00%","c":[{"t":"① 기준금리 = 돈의 기본값","n":[["설명","기준금리는 한국은행이 정하는 \"돈의 기본 값\"입니다. 기준금리가 오르면 예금 이자와 대출 이자가 함께 오르는 경향이 있습니다."]]},{"t":"② 2.50→3.00% 인상 후 동결","n":[["설명","한국은행은 2026년 상반기 2.50%를 유지하다가 7월에 2.75%, 8월에 3.00%로 두 차례 올렸고, 10월 22일에는 금통위원 7명 전원 찬성으로 3.00%에서 동결했습니다. 다음 회의는 11월 26일입니다."]]},{"t":"③ 추가 인상 가능성","n":[["설명","한국은행은 \"추가 인상의 시기와 속도\"를 살펴보겠다고 밝혀, 금리가 더 오를 가능성을 열어 두었습니다. 즉, 지금은 \" 빚 부담이 커지는 시기\"라는 점을 기억해야 합니다."]]}],"h":"기·2·추 → 기2추 → 기본값·2.50→3.00·추가 인상"},{"t":"(2) 물가 상승률 2%대 후반","c":[{"t":"① 9월 CPI 2.9%, 근원 2.8%","n":[["설명","2026년 9월 소비자물가는 1년 전보다 2.9% 올랐고, 식료품·에너지를 뺀 근원물가는 2.8% 올랐습니다. 한국은행 목표치(2%)보다 높은 수준입니다."]]},{"t":"② 현금 실질가치 감소","n":[["설명","물가가 3% 가까이 오르면, 이자가 2%인 통장에 넣어 둔 돈은 실제 가치가 매년 1% 가까이 줄어드는 셈입니다."]]},{"t":"③ 현금·빚 모두 위험한 시기","n":[["설명","따라서 \"현금만 쥐고 있는 것\"도 위험이고, \"빚을 많이 지는 것\"도 위험인 시기입니다. 균형이 중요합니다."],["핵심 포인트","2026년 11월 현재: 기준금리 3.00%(10월 22일 동결, 7·8월 연속 인상 후), 9월 소비자물가 2.9%. 금리 인상기에는 변동금리 대출 부담이 커지고, 물가가 높을 때는 현금의 실질 가치가 줄어듭니다."]]}],"h":"9·현·현 → 9현현 → 9월 2.9%·현금 가치↓·현금 빚 모두 위험"}]},{"t":"2. 주식시장과 부동산","c":[{"t":"(1) 큰 변동성을 보인 주식시장","c":[{"t":"① 코스피 하루 −6.02%","n":[["설명","코스피는 2026년 들어 반도체 호황 속에 5,000선을 넘어서는 강세를 보였습니다. 그러나 11월 6일(금)에는 하루 만에 324.11포인트(−6.02%) 떨어진 5,059.69로 마감했습니다."]]},{"t":"② 서킷브레이커 발동","n":[["설명","이날 장중에는 4,911.28(−8.78%)까지 밀리며 1단계 서킷브레이커(시장 전체 매매를 20분간 멈추는 장치)가 발동됐습니다. 미국 중간선거 결과에 따른 AI 데이터센터 규제 우려와 빅테크 수익성 의구심으로 전날 필라델피아 반도체 지수가 12% 넘게 폭락한 영향이었습니다."]]},{"t":"③ 하루 6% 하락은 상존","n":[["설명","이 사건은 \"오르는 시장에서도 하루 6% 하락은 언제든 일어난다\"는 사실을 다시 보여 주었습니다. 제5절에서 이런 폭락장에서 부자들이 하지 않는 행동을 자세히 다룹니다."],["실제 사례","2026년 11월 6일 '검은 금요일': 코스피 −6.02%, 코스닥 −5.03%. 외국인은 코스피에서 약 2조 7,700억 원을 팔았고, 개인과 기관이 사들였습니다. 삼성전자는 −6.35%, SK하이닉스는 −10.44%로 마감했습니다. 하루 사이 시가총액 약 267조 원이 사라졌다는 보도도 있었습니다. 빚을 내 반도체주에 몰아 투자한 사람은 큰 타격을 받았지만, 비상금과 분산 계좌를 갖춘 사람은 오히려 차분하게 상황을 지켜볼 수 있었습니다."]]}],"h":"코·서·하 → 코서하 → 코스피 −6%·서킷브레이커·하락 상존"},{"t":"(2) 강한 규제 아래의 주택시장","c":[{"t":"① 규제지역 LTV 40%(생애 70%)","n":[["설명","서울 전역과 경기 12개 지역은 규제지역(투기과열지구 등)으로 묶여 있고, 집을 살 때 받을 수 있는 대출(LTV)은 원칙적으로 집값의 40%입니다(생애 최초 구입자는 70%)."]]},{"t":"② 주담대 한도 6억/4억/2억","n":[["설명","규제지역의 주택담보대출 한도는 집값 15억 원 이하 6억 원, 15억~25억 원 4억 원, 25억 원 초과 2억 원으로 제한되어 있습니다."]]},{"t":"③ 규제 속 집값 상승 지속","n":[["설명","그럼에도 한국은행에 따르면 서울 집값은 2026년 8월 1.0%, 9월 0.8% 오르는 등 상승세가 이어졌습니다. 규제와 상승이 함께 있는 시장에서는 \"무리하지 않는 계산\"이 더 중요합니다(제7절)."],["따라 해 보기","서울에서 14억 원짜리 아파트를 생애 처음으로 사려는 사람이 있습니다. LTV 70%와 주담대 한도 6억 원 중 어느 쪽이 실제 대출 한도가 될까요?\n\n결과 LTV 70%로 계산하면 9억 8,000만 원이지만, 15억 원 이하 주택의 한도가 6억 원이므로 더 작은 6억 원이 상한입니다. 여기에 소득에 따른 DSR(총부채원리금상환비율) 제한까지 통과해야 하므로 실제 한도는 더 낮아질 수 있습니다. 자기 돈이 최소 8억 원 이상 필요합니다."]]}],"h":"규·주·규 → 규주규 → 규제 LTV 40%·주담대 6억·규제 속 상승"}]}]}]},{"n":2,"t":"돈의 흐름을 아는 것이 시작이다 — 가계부·순자산표·고정비","c":[{"t":"Ⅰ 내 돈의 지도 그리기","c":[{"t":"1. 순자산표 만들기","c":[{"t":"(1) 자산 칸 채우기","c":[{"t":"① 자산: 가진 것 모두 적기","n":[["설명","종이 한 장을 반으로 나누어 왼쪽에 \"가진 것\", 오른쪽에 \"갚을 것\"을 적습니다. 왼쪽에는 통장 잔액, 적금, 주식·펀드 평가액, 연금 적립금, 전세보증금, 집의 시세, 자동차 중고 시세를 적습니다."]]},{"t":"② 차는 현재 매도가로","n":[["설명","자동차는 산 값이 아니라 \"지금 팔면 받을 값\"으로 적습니다. 그래야 현실을 정확히 볼 수 있습니다."]]},{"t":"③ 연금 적립금 별도 칸","n":[["설명","연금 적립금(퇴직연금, 연금저축)은 당장 쓸 수 없지만 내 몫이므로 따로 칸을 만들어 적습니다."]]}],"h":"자·차·연 → 자차연 → 자산 모두·차는 매도가·연금 별도"},{"t":"(2) 부채 칸 채우기","c":[{"t":"① 부채: 갚을 것 모두 적기","n":[["설명","오른쪽에는 주택담보대출, 전세대출, 신용대출, 마이너스통장 사용액, 카드 할부 잔액, 자동차 할부 잔액, 가족에게 빌린 돈까지 모두 적습니다."]]},{"t":"② 이자율·만기 함께 기록","n":[["설명","각 빚 옆에는 이자율과 만기(갚아야 하는 날)를 꼭 함께 적습니다. 이자율이 높은 빚부터 갚아야 하기 때문입니다."]]},{"t":"③ 합계 차로 순자산 산출","n":[["설명","마지막으로 왼쪽 합계에서 오른쪽 합계를 빼면 순자산이 나옵니다. 이 숫자를 6개월이나 1년마다 다시 적어 비교합니다."],["쉬운 예","순자산표는 우리 집 \"돈 건강검진표\"입니다. 키와 몸무게를 재야 내가 자라는지 알 수 있듯, 순자산을 정기적으로 재야 내 돈이 자라고 있는지 알 수 있습니다."]],"tb":[[["구분","항목 예시","적는 법"],["현금성 자산","입출금 통장, 파킹통장, CMA, 예금","오늘 잔액"],["투자 자산","주식, ETF, 펀드, 채권","오늘 평가액"],["연금 자산","퇴직연금(DC·IRP), 연금저축","적립금 조회 금액"],["실물 자산","집, 전세보증금, 자동차","지금 팔면 받을 값"],["부채","주담대, 신용대출, 할부 잔액","남은 원금 + 이자율 + 만기"]]]}],"h":"부·이·합 → 부이합 → 부채 모두·이자율 기록·합계 차로 순자산"}]},{"t":"2. 가계부 쓰기 — 돈이 어디로 새는지 찾기","c":[{"t":"(1) 세 달만 써 보기","c":[{"t":"① 딱 세 달만 기록","n":[["설명","처음부터 평생 가계부를 쓰려고 하면 금방 지칩니다. 딱 세 달만 모든 지출을 기록해 보는 것을 목표로 합니다."]]},{"t":"② 앱 자동분류 주1회 점검","n":[["설명","요즘은 은행·카드 앱이 지출을 자동으로 분류해 주므로, 매주 한 번 앱을 열어 \"이 돈은 꼭 필요했나?\"를 표시하기만해도 충분합니다."]]},{"t":"③ 새는 구멍 2~3곳 발견","n":[["설명","세 달이 지나면 내 돈이 새는 구멍 2~3곳이 보입니다. 배달 음식, 구독 서비스, 충동구매가 대표적입니다."]]}],"h":"딱·앱·새 → 딱앱새 → 딱 세 달·앱 점검·새는 구멍"},{"t":"(2) 지출을 세 가지로 나누기","c":[{"t":"① 고정 필수비","n":[["설명","고정 필수비: 월세·관리비, 통신비, 보험료, 대출이자처럼 매달 거의 같은 금액이 나가는 꼭 필요한 돈입니다."]]},{"t":"② 변동 필수비","n":[["설명","변동 필수비: 식비, 교통비, 생활용품처럼 꼭 필요하지만 금액이 달라지는 돈입니다."]]},{"t":"③ 선택 지출은 정한 만큼만","n":[["설명","선택 지출: 외식, 여행, 쇼핑, 취미처럼 줄이거나 미룰 수 있는 돈입니다. 부자가 되는 사람들은 이 칸을 \"안 쓴다\"가 아니라 \"미리 정한 만큼만 쓴다\"로 관리합니다."],["따라 해 보기","세후 월급 300만 원인 사회초년생 C씨의 지출이 고정 필수비 110만 원, 변동 필수비 70만 원, 선택 지출 90만 원입니다. 저축률은 몇 %이고, 선택 지출을 30% 줄이면 저축률은 몇 %가 될까요?\n\n결과 지출 합계 270만 원 → 저축 30만 원 → 저축률 10%. 선택 지출을 30%(27만 원) 줄이면 저축은 57만 원 → 저축률 19%가 됩니다. 생활의 큰 변화 없이 저축률이 거의 두 배가 됩니다."]]}],"h":"고·변·선 → 고변선 → 고정·변동·선택"}]}]},{"t":"Ⅱ 고정비가 부를 결정한다","c":[{"t":"1. 고정비가 무서운 이유","c":[{"t":"(1) 한 번 늘면 잘 줄지 않는다","c":[{"t":"① 자동 출금이라 못 느낌","n":[["설명","고정비는 한 번 정해지면 매달 자동으로 빠져나갑니다. 그래서 늘어난 것을 잘 느끼지 못하고, 줄이기도 어렵습니다."]]},{"t":"② 구독 4개 = 10년 2,400만","n":[["설명","예를 들어 월 5만 원짜리 구독 서비스 4개는 1년에 240만 원, 10년이면 2,400만 원입니다. 이 돈을 연 6%로 굴렸다면 10년 뒤 약 3,300만 원이 됩니다."]]},{"t":"③ 고정비 증가 = 노후 위험","n":[["설명","첨부 영상 자료는 \"50대가 가까워져도 고정비가 계속 증가하는 것\"을 노후 자금이 부족해지는 대표적 위험 신호로 꼽았습니다."]]}],"h":"자·구·고 → 자구고 → 자동 출금·구독·고정비 위험"},{"t":"(2) 고정비는 \"미래 월급의 예약\"이다","c":[{"t":"① 할부 = 월급 선예약","n":[["설명","자동차 할부 월 60만 원은 앞으로 5년 동안 매달 내 월급 60만 원을 미리 예약해 둔 것과 같습니다."]]},{"t":"② 예약 많을수록 취약","n":[["설명","이렇게 예약된 돈이 많아지면, 월급이 줄거나 끊겼을 때 버틸 힘이 급격히 줄어듭니다."]]},{"t":"③ 고정비 증가분부터 확인","n":[["설명","그래서 부자들은 큰 물건을 살 때 \"총 가격\"이 아니라 \"이것이 내 고정비를 얼마나 늘리나\"를 먼저 묻습니다."],["핵심 포인트","고정비 점검 3질문: ① 이 지출은 매달 자동으로 나가는가? ② 1년·10년 합치면 얼마인가? ③ 이것을 없애면 내 삶이 정말 나빠지는가? 세 번째 질문에 \"아니오\"라면 바로 줄일 대상입니다."]]}],"h":"할·예·고 → 할예고 → 할부=예약·예약 많으면 취약·고정비 증가 확인"}]},{"t":"2. 고정비 줄이기 실전","c":[{"t":"(1) 큰 고정비부터","c":[{"t":"① 3대 고정비: 주거·차·보험","n":[["설명","주거비, 자동차, 보험료가 3대 고정비입니다. 커피 한 잔을 아끼는 것보다 이 세 가지를 한 번 점검하는 것이 효과가 훨씬 큽니다."]]},{"t":"② 보험 중복 특약 정리","n":[["설명","보험은 \"많이 들수록 안전하다\"는 생각이 함정입니다. 실손의료보험처럼 꼭 필요한 보장과, 겹치거나 불필요한 특약을 구분해 정리합니다."]]},{"t":"③ 차는 월 총비용으로","n":[["설명","자동차는 \"월 납입금\"이 아니라 보험료·기름값·주차비·감가상각을 모두 합친 \"월 총비용\"으로 계산합니다. 많은 경우 월 100만 원이 넘습니다."]]}],"h":"3·보·차 → 3보차 → 3대 고정비·보험 중복·차는 총비용"},{"t":"(2) 작은 고정비 정리","c":[{"t":"① 알뜰폰으로 통신비 절감","n":[["설명","통신비는 알뜰폰 요금제로 바꾸면 월 3만~5만 원 이상 줄어드는 경우가 많습니다."]]},{"t":"② 분기별 구독 정리","n":[["설명","구독 서비스(영상, 음악, 쇼핑 멤버십)는 석 달에 한 번 목록을 보고 한 달 동안 쓰지 않은 것은 해지합니다."]]},{"t":"③ 절감액 즉시 자동이체","n":[["설명","줄인 금액은 반드시 같은 날 자동이체로 저축·투자 통장에 옮깁니다. 그렇지 않으면 아낀 돈이 다른 곳으로 새어 나갑니다."],["실제 사례","40대 맞벌이 D씨 부부는 보험 8건(월 68만 원)을 점검해 중복 특약을 정리하고 4건(월 31만 원)으로 줄였습니다. 신차 할부 대신 4년 된 중고차로 바꾸며 월 45만 원을 줄였고, 통신·구독료로 월 8만 원을 아꼈습니다. 합계 월 90 만 원, 1년이면 1,080만 원을 연금저축과 ISA 계좌로 자동이체했고, 그 덕분에 연말정산 세액공제까지 받았습니다."]],"tb":[[["고정비 항목","흔한 낭비","점검 방법"],["주거비","소득 대비 과한 월세·대출이자","소득의 30% 이하인지 확인"],["자동차","소득에 비해 비싼 신차 할부","월 총비용(보험·유류·감가) 계산"],["보험","중복 보장, 불필요한 특약","보장 내용 목록 만들어 비교"],["통신·구독","쓰지 않는 서비스 자동결제","3개월마다 결제 목록 확인"]]]}],"h":"알·분·절 → 알분절 → 알뜰폰·분기 구독 정리·절감액 자동이체"}]}]},{"t":"Ⅲ 월급이 오를 때 부자들이 하는 선택","c":[{"t":"1. 생활 수준 인플레이션 막기","c":[{"t":"(1) 생활 수준 인플레이션이란","c":[{"t":"① 소득 따라 지출도 증가","n":[["설명","생활 수준 인플레이션은 소득이 오르는 만큼 씀씀이도 함께 커지는 현상입니다. 월급이 100만 원 오르면 생활비도 90만 원 오르는 식입니다."]]},{"t":"② 저축 정체·위기 취약","n":[["설명","이렇게 되면 소득은 올라도 저축액은 거의 그대로이고, 오히려 높아진 생활비 때문에 위기에 더 약해집니다."]]},{"t":"③ 덜 올리면 연 840만 추가","n":[["설명","반대로 월급이 100만 원 올랐을 때 생활비를 30만 원만 올린 사람은 매달 70만 원, 1년에 840만 원을 추가로 모을 수 있습니다."]]}],"h":"소·저·덜 → 소저덜 → 소득 따라 지출·저축 정체·덜 올리기"},{"t":"(2) 인상분 나누기 규칙","c":[{"t":"① 인상분 절반 이상 자동저축","n":[["설명","인상분의 절반 이상은 받는 날 바로 자동이체로 저축·투자 계좌에 보냅니다. 통장에 머무르는 시간이 길수록 써 버리기 쉽습니다."]]},{"t":"② 일부는 보상으로 소비","n":[["설명","나머지 일부는 자신을 위한 보상으로 즐겁게 씁니다. 모든 것을 참기만 하면 오래 지속하기 어렵습니다."]]},{"t":"③ 일부는 자기 실력 투자","n":[["설명","인상분의 일부는 자신의 실력(자격증, 교육, 건강)에 다시 투자합니다. 소득을 만드는 능력이 가장 수익률 높은 자산 일 수 있기 때문입니다."],["쉬운 예","용돈이 1만 원에서 1만 5,000원으로 올랐을 때, 늘어난 5,000원 중 3,000원은 돼지저금통에, 1,000원은 책 사는 데, 1,000원은 좋아하는 간식에 쓰기로 미리 정해 두는 것과 같습니다."]]}],"h":"인·일·일 → 인일일 → 인상분 절반 저축·일부 보상·일부 실력 투자"}]},{"t":"2. 소비 자산보다 생산 자산","c":[{"t":"(1) 소비 자산과 생산 자산의 차이","c":[{"t":"① 소비 자산: 감가·유지비","n":[["설명","소비 자산은 쓸수록 값이 줄고 유지비가 드는 것(자동차, 전자제품, 명품)입니다."]]},{"t":"② 생산 자산: 돈을 만듦","n":[["설명","생산 자산은 시간이 지날수록 돈을 만들어 주는 것(배당주, 채권, 연금, 임대 수입, 작은 사업, 나의 기술)입니다."]]},{"t":"③ 생산 자산 비중 확대","n":[["설명","월급이 오를 때 생산 자산의 비중을 높이면, 시간이 지날수록 월급이 아닌 곳에서 들어오는 돈이 늘어납니다."]]}],"h":"소·생·생 → 소생생 → 소비 자산·생산 자산·생산 비중↑"},{"t":"(2) 보여지는 부보다 선택권","c":[{"t":"① 보여지는 부보다 선택권","n":[["설명","첨부 자료가 말하는 \"아홉 번째 선택\"은 보여지는 부보다 선택권을 늘리는 것입니다. 큰 집으로 이사하기 전에 비상금을 6개월에서 12개월로 늘리는 것이 한 예입니다."]]},{"t":"② 돈 때문에 잘못된 결정 방지","n":[["설명","선택권이 늘면 회사에서 부당한 일을 겪을 때, 새로운 일에 도전할 때, 가족이 아플 때 돈 때문에 잘못된 결정을 하지 않아도 됩니다."]]},{"t":"③ 숫자 정기 확인 습관","n":[["설명","마지막으로 가장 중요한 선택은 \"숫자를 정기적으로 확인하는 습관\"입니다. 순자산표와 가계부를 3~6개월마다 다시 보는 사람은 방향을 잃지 않습니다."],["핵심 포인트","월급이 오르면 ① 생활 수준은 천천히 올리고 ② 인상분 절반 이상을 자동이체로 분리하고 ③ 세제 혜택 계좌(ISA·연금저축·IRP)를 다시 채우고 ④ 일부는 나의 소득 능력에 재투자합니다."]],"tb":[[["월급 100만 원 인상 시","첫 번째 사람","두 번째 사람"],["생활비 증가","90만 원","30만 원"],["추가 저축·투자","10만 원","70만 원"],["1년 추가 저축","120만 원","840만 원"],["10년 뒤(연 6% 가정)","약 1,640만 원","약 1억 1,500만 원"]]]}],"h":"보·돈·숫 → 보돈숫 → 보여지는 부보다 선택권·돈 때문에 잘못된 결정 X·숫자 확인"}]}]}]},{"n":3,"t":"저축과 비상금 — 현금은 시간을 사는 돈이다","c":[{"t":"Ⅰ 저절로 모이는 저축 시스템","c":[{"t":"1. 선저축 후지출","c":[{"t":"(1) 남는 돈을 저축하면 안 되는 이유","c":[{"t":"① 쓰고 남은 돈은 안 남음","n":[["설명","대부분의 사람은 \"쓰고 남으면 저축하겠다\"고 생각합니다. 그러나 돈은 통장에 있으면 쓸 곳이 생기는 성질이 있어서, 월말에는 거의 남지 않습니다."]]},{"t":"② 월급날 먼저 떼어 저축","n":[["설명","부자가 되는 사람들은 순서를 바꿉니다. 월급날 저축할 돈을 먼저 떼어 다른 통장으로 보내고, 남은 돈으로 한 달을 삽니다. 이것을 선저축 후지출이라고 합니다."]]},{"t":"③ 자동이체로 의지력 불필요","n":[["설명","이 방법은 의지력이 필요 없습니다. 한 번 자동이체를 걸어 두면 내가 잊고 있어도 저축이 계속됩니다."]]}],"h":"쓰·월·자 → 쓰월자 → 쓰고 남은 돈 X·월급날 먼저·자동이체"},{"t":"(2) 통장 쪼개기","c":[{"t":"① 월급 통장: 즉시 분배","n":[["설명","월급 통장: 월급이 들어오는 곳. 들어오자마자 다른 통장으로 나누어 보냅니다."]]},{"t":"② 생활비 통장+체크카드","n":[["설명","생활비 통장: 한 달 생활비만 넣고 체크카드를 연결합니다. 잔액이 곧 \"이번 달 남은 용돈\"이 되어 과소비를 막아 줍니다."]]},{"t":"③ 비상금·투자 통장 분리","n":[["설명","비상금 통장과 투자 통장: 비상금은 언제든 꺼낼 수 있는 파킹통장이나 CMA에, 장기 자금은 ISA·연금저축 같은 세제 혜택 계좌에 보냅니다."],["쉬운 예","통장 쪼개기는 집 안의 서랍 정리와 같습니다. 양말, 속옷, 셔츠를 한 서랍에 섞어 넣으면 무엇이 얼마나 있는지 모르지만, 칸을 나누면 한눈에 보입니다. 돈도 칸을 나누면 \"이번 달에 얼마 쓸 수 있는지\"가 한눈에 보입니다."]]}],"h":"월·생·비 → 월생비 → 월급·생활비·비상금/투자 통장"}]},{"t":"2. 저축률 목표 정하기","c":[{"t":"(1) 소득 단계별 저축률","c":[{"t":"① 초년생 세후 20% 목표","n":[["설명","사회초년생이나 소득이 적을 때는 세후 소득의 20%를 첫 목표로 합니다. 부모님과 함께 살아 주거비가 적다면 40~50%도 가능합니다."]]},{"t":"② 맞벌이·40대 30% 이상","n":[["설명","맞벌이 가구나 소득이 안정된 40대는 30% 이상을 목표로 합니다. 이 시기의 저축률이 노후를 거의 결정합니다."]]},{"t":"③ 매년 2~3%p씩 상향","n":[["설명","처음부터 높은 목표가 어렵다면 매년 저축률을 2~3%포인트씩 올리는 방식이 현실적입니다. 월급 인상분의 절반을 저축으로 돌리면 자연스럽게 저축률이 올라갑니다."]]}],"h":"초·맞·매 → 초맞매 → 초년생 20%·맞벌이 30%·매년 2~3%p↑"},{"t":"(2) 청년층을 위한 정부 지원 적금","c":[{"t":"① 청년도약계좌→청년미래적금","n":[["설명","2026년에는 기존 청년도약계좌의 신규 가입이 끝나고, 그 후속 상품으로 청년미래적금이 설계되었습니다(2026년 6월 출시 예정으로 발표)."]]},{"t":"② 만 19~34세·월 최대 50만","n":[["설명","발표된 조건은 만 19~34세(병역 기간만큼 연장, 최대 39세), 직전 연도 총급여 7,500만 원 이하 등이며, 월 최대 50만 원을 3년 동안 넣으면 정부가 납입액의 6%(일반형) 또는 12%(우대형)를 기여금으로 보태 주는 구조입니다."]]},{"t":"③ 정부 기여금 = 확정 수익","n":[["설명","정부 기여금은 사실상 \"확정 수익\"이므로 자격이 된다면 가장 먼저 검토할 저축입니다. 다만 세부 조건과 가입 시기는 서민금융진흥원 등 공식 안내에서 반드시 다시 확인해야 합니다."],["따라 해 보기","우대형 청년미래적금에 월 50만 원씩 3년간 넣으면 정부 기여금은 모두 얼마일까요?\n\n결과 월 50만 원 × 12% = 월 6만 원, 36개월 × 6만 원 = 216만 원입니다. 은행 이자는 별도로 붙습니다. 원금 1,800만 원에 대해 기여금만 12%이므로, 일반 적금으로는 얻기 어려운 수준의 혜택입니다."]],"tb":[[["상품","대상(요약)","핵심 혜택","확인할 점"],["청년미래적금","만 19~34세, 소득 기준 충족","정부 기여금 6% 또는 12%, 3년 만기","청년도약계좌 유지자는 중복 불가"],["일반 정기적금","누구나","확정 이자","이자소득세 15.4%"],["파킹통장·CMA","누구나","수시 입출금 + 이자","금리 변동, 예금자보호 여부"]]]}],"h":"청·만·정 → 청만정 → 청년미래적금·만 19~34·정부 기여금"}]}]},{"t":"Ⅱ 비상금 — 위기를 버티는 방패","c":[{"t":"1. 비상금이 필요한 이유","c":[{"t":"(1) 갑작스러운 일은 반드시 생긴다","c":[{"t":"① 예상 못한 지출은 반드시","n":[["설명","실직, 질병, 사고, 가족의 일, 집수리처럼 예상하지 못한 지출은 누구에게나 생깁니다. 문제는 \"생기느냐\"가 아니라 \" 언제 생기느냐\"입니다."]]},{"t":"② 없으면 고금리 빚 의존","n":[["설명","비상금이 없으면 이런 일이 생길 때 카드론, 현금서비스, 마이너스통장 같은 고금리 빚을 쓰게 됩니다. 연 15~20%이자의 빚은 순식간에 불어납니다."]]},{"t":"③ 투자자산 헐값 매도 방지","n":[["설명","또는 투자한 주식을 가장 나쁜 시기에 팔아야 할 수도 있습니다. 비상금은 투자 자산을 지키는 방패이기도 합니다."]]}],"h":"예·없·투 → 예없투 → 예상 못한 지출·없으면 빚·투자 헐값 매도 방지"},{"t":"(2) 비상금은 수익이 아니라 시간을 산다","c":[{"t":"① 팔지 않아도 되는 시간","n":[["설명","첨부 영상 「부자들은 왜 경기침체 전에 현금을 늘릴까」는 현금의 첫 번째 역할을 \"수익을 내기 위해서가 아니라 팔지 않아도 되는 시간을 사기 위해서\"라고 설명합니다."]]},{"t":"② 실직해도 6개월 여유","n":[["설명","비상금 6개월치가 있으면, 실직해도 6개월 동안 서두르지 않고 다음 일을 찾을 수 있습니다. 급하게 낮은 조건의 일을 잡지 않아도 됩니다."]]},{"t":"③ 마음의 평화를 사는 돈","n":[["설명","즉 비상금의 이자가 낮다고 손해가 아닙니다. 비상금은 \"보험료\"처럼 마음의 평화와 선택권을 사는 돈입니다."],["핵심 포인트","비상금의 3대 역할: ① 고금리 빚을 쓰지 않게 막는다 ② 주식·부동산을 나쁜 시기에 팔지 않게 지킨다 ③ 실직·질병 때 서두르지 않을 시간을 준다."]]}],"h":"팔·실·마 → 팔실마 → 팔지 않아도 되는 시간·실직 6개월·마음의 평화"}]},{"t":"2. 비상금의 크기와 보관 장소","c":[{"t":"(1) 얼마나 모아야 할까","c":[{"t":"① 필수 생활비 3~6개월치","n":[["설명","기본은 월 필수 생활비의 3~6개월치입니다. 월 필수 생활비가 250만 원이면 750만~1,500만 원입니다."]]},{"t":"② 불안정 소득은 6~12개월","n":[["설명","소득이 불안정한 자영업자·프리랜서, 외벌이 가구, 부양가족이 많은 가구는 6~12개월치를 권합니다."]]},{"t":"③ 50대 이후 1~2년치","n":[["설명","은퇴가 가까운 50대 이후는 주식이 크게 떨어졌을 때 팔지 않고 버틸 수 있도록 1~2년치 생활비를 현금과 단기 채권 등 안전 자산으로 따로 두는 방법이 많이 쓰입니다."]]}],"h":"필·불·5 → 필불5 → 필수 3~6개월·불안정 6~12개월·50대 1~2년"},{"t":"(2) 어디에 둘까","c":[{"t":"① 파킹통장·CMA·단기예금","n":[["설명","비상금은 \"언제든 바로 꺼낼 수 있고, 원금이 줄지 않는 곳\"에 둡니다. 파킹통장, CMA(증권사 수시입출금 계좌), 짧은 만기의 예금이 알맞습니다."]]},{"t":"② 예금자보호 1억으로 상향","n":[["설명","2025년 9월 1일부터 예금자보호 한도가 1인당 금융회사별 5,000만 원에서 1억 원으로 올랐습니다. 은행·저축은행 등이 망해도 원금과 이자를 합쳐 1억 원까지는 보호됩니다."]]},{"t":"③ CMA·펀드 보호 여부 확인","n":[["설명","다만 증권사 CMA 중 일부 유형이나 펀드, 주식은 예금자보호 대상이 아닙니다. 상품 설명서의 \"예금자보호\" 표시를 꼭 확인합니다."],["실제 사례","프리랜서 디자이너 E씨는 월 필수 생활비 200만 원의 9개월치인 1,800만 원을 파킹통장 두 곳에 나누어 두었습니다. 2026년 여름 큰 거래처 두 곳이 동시에 계약을 끊었지만, E씨는 비상금으로 생활하면서 넉 달 동안 새 거래처를 차분히 찾았고, 그 사이 투자 계좌의 주식은 한 주도 팔지 않았습니다. 비상금이 없었다면 주식을 손해 보고 팔거나 고금리 대출을 썼을 것입니다."]],"tb":[[["비상금 보관처","장점","주의할 점"],["은행 파킹통장","수시 입출금, 예금자보호(1억 원 한도)","잔액 구간별로 금리가 다를 수 있음"],["증권사 CMA","수시 입출금, 하루만 맡겨도 이자","유형(RP·MMF 등)에 따라 예금자보호 안 될 수 있음"],["단기 정기예금","파킹통장보다 금리가 조금 높을 수 있음","중도해지하면 이자 손해"],["주식·코인","(비상금 보관처로 부적합)","필요할 때 값이 크게 떨어져 있을 수 있음"]]]}],"h":"파·예·C → 파예C → 파킹통장·예금자보호 1억·CMA 보호 확인"}]}]},{"t":"Ⅲ 부자들이 경기침체 전에 현금을 늘리는 이유","c":[{"t":"1. 강제 매도를 피하기 위해","c":[{"t":"(1) 강제 매도란","c":[{"t":"① 급해서 어쩔 수 없이 파는 것","n":[["설명","강제 매도란 팔고 싶지 않은데 돈이 급해서 어쩔 수 없이 파는 것입니다. 경기침체 때는 집값과 주가가 동시에 떨어지는 경우가 많아, 이때 팔면 큰 손해를 봅니다."]]},{"t":"② 빚투는 반대매매 위험","n":[["설명","빚을 내 투자한 사람은 담보 가치가 떨어지면 금융회사가 주식을 강제로 팔아 버리는 반대매매를 당할 수도 있습니다."]]},{"t":"③ 현금 있으면 기다릴 수 있음","n":[["설명","현금을 넉넉히 가진 사람은 이런 상황에서도 기다릴 수 있습니다. 경기침체는 대개 영원하지 않기 때문에, 기다릴 수 있는 사람이 결국 살아남습니다."]]}],"h":"급·빚·현 → 급빚현 → 급해서 파는 것·빚투 반대매매·현금 있으면 기다림"},{"t":"(2) 생활 위험과 투자 위험의 분리","c":[{"t":"① 생활 위험 vs 투자 위험","n":[["설명","첨부 자료는 \"첫 번째가 생활을 버티는 문제라면, 두 번째는 투자 자산을 지키는 문제\"라고 구분합니다."]]},{"t":"② 같은 바구니면 함께 흔들림","n":[["설명","생활비를 투자 자산과 같은 바구니에 넣어 두면, 시장이 흔들릴 때 생활까지 흔들립니다."]]},{"t":"③ 생활비·투자 바구니 분리","n":[["설명","그래서 부자들은 생활비 바구니(현금)와 투자 바구니(주식·채권)를 분명히 나누어 둡니다."],["쉬운 예","비 오는 날을 대비해 우산을 미리 사 두는 사람은 비가 와도 뛰지 않고 걸어갈 수 있습니다. 우산이 없는 사람은 비가 오면 아무 가게에나 들어가 비싼 우산을 사야 합니다. 현금은 경제의 비 오는 날을 대비한 우산입니다."]]}],"h":"생·같·생 → 생같생 → 생활 vs 투자 위험·같은 바구니면 함께 흔들·바구니 분리"}]},{"t":"2. 기회를 잡기 위해","c":[{"t":"(1) 싸게 살 수 있는 힘","c":[{"t":"① 폭락장엔 좋은 자산도 저렴","n":[["설명","경기침체나 폭락장에서는 좋은 자산도 함께 싸집니다. 이때 현금을 가진 사람만 그 기회를 잡을 수 있습니다."]]},{"t":"② 현금 보유자만 분할매수","n":[["설명","2026년 11월 6일처럼 코스피가 하루에 6% 떨어진 날, 현금이 없던 사람은 바라만 보거나 더 불안해서 팔았지만, 현금을 따로 둔 사람은 나누어 사는 계획을 세울 수 있었습니다."]]},{"t":"③ 더 싸게 산다는 보장 없음","n":[["설명","다만 \"현금을 가지면 반드시 더 싸게 산다\"는 보장은 없습니다. 첨부 자료도 \"두 번째 사람이 반드시 더 싸게 살 수 있는 것은 아니다\"라고 솔직하게 말합니다. 현금의 핵심은 기회보다 생존입니다."]]}],"h":"폭·현·더 → 폭현더 → 폭락장 저가·현금 있어야 분할매수·더 싸진다는 보장 없음"},{"t":"(2) 기회 자금과 비상금은 다르다","c":[{"t":"① 비상금 ≠ 기회 자금","n":[["설명","비상금은 생활을 지키는 돈이고, 기회 자금은 좋은 투자 기회가 왔을 때 쓰는 돈입니다. 첨부 영상 「부자들이 집보다 먼저 사는 7가지 자산」도 첫 번째 자산(현금성 안전 자산)과 마지막 일곱 번째 자산(기회 자금)을 \"비슷해 보이지만 역할은 전혀 다르다\"고 구분합니다."]]},{"t":"② 섞으면 위기에 무방비","n":[["설명","두 돈을 섞으면, 기회 자금을 쓰고 나서 위기가 오면 버틸 돈이 없어집니다. 통장을 따로 두는 것이 좋습니다."]]},{"t":"③ 금융자산 5~15% 기회자금","n":[["설명","기회 자금은 전체 금융자산의 5~15% 정도를 단기 채권, 예금, MMF(초단기 펀드) 등에 두는 경우가 많습니다. 비율은 각자의 성향과 나이에 따라 달라집니다."],["핵심 포인트","현금은 \"게으른 돈\"이 아닙니다. 현금은 ① 팔지 않아도 되는 시간 ② 반대매매·강제 매도로부터의 안전 ③ 싸게 살 수 있는 기회를 동시에 사 줍니다. 단, 물가보다 이자가 낮으면 실질 가치는 줄어들므로 필요한 만큼만 둡니다."]],"tb":[[["구분","비상금","기회 자금"],["목적","생활을 지킨다","싸게 살 기회를 잡는다"],["크기","월 필수 생활비 3~12개월","금융자산의 5~15% 정도(개인차)"],["보관","파킹통장, CMA, 단기 예금","단기 채권, 예금, MMF"],["쓰는 때","실직·질병·사고","시장 급락, 좋은 매물 등장"]]]}],"h":"비·섞·금 → 비섞금 → 비상금≠기회자금·섞으면 무방비·금융자산 5~15%"}]}]}]},{"n":4,"t":"빚과 레버리지 — 좋은 빚, 나쁜 빚, 위험한 빚","c":[{"t":"Ⅰ 빚을 구분하는 눈","c":[{"t":"1. 좋은 빚과 나쁜 빚","c":[{"t":"(1) 좋은 빚의 조건","c":[{"t":"① 이자보다 큰 가치를 만드는 빚","n":[["설명","좋은 빚은 그 빚으로 산 것이 빚의 이자보다 더 큰 가치를 만들어 주는 빚입니다. 소득을 높여 주는 교육, 감당 가능한 범위의 실거주 주택 대출, 검증된 사업의 운전자금 등이 해당할 수 있습니다."]]},{"t":"② 현금흐름으로 갚을 수 있음","n":[["설명","좋은 빚의 첫째 조건은 상환 재원이 현금흐름에서 나오는 것입니다. 즉 \"자산 가격이 올라야만 갚을 수 있는 빚\"이 아니라 \"월급이나 사업 수입으로 갚을 수 있는 빚\"이어야 합니다."]]},{"t":"③ 금리 +2%p도 감당 가능","n":[["설명","둘째 조건은 이자율과 만기를 알고, 금리가 2%포인트 올라도 감당할 수 있는 크기여야 한다는 것입니다."]]}],"h":"이·현·금 → 이현금 → 이자보다 큰 가치·현금흐름으로 상환·금리 +2%p 감당"},{"t":"(2) 나쁜 빚의 특징","c":[{"t":"① 소비 후 남는 게 없는 빚","n":[["설명","나쁜 빚은 소비를 위해 쓰고, 그 결과 아무것도 남지 않는 빚입니다. 여행, 명품, 할부로 산 신차, 현금서비스가 대표적입니다."]]},{"t":"② 빚내면 위험한 10가지","n":[["설명","첨부 영상 「고금리 시대에 빚내서 사면 위험한 10가지」는 지나치게 비싼 신차, 여행과 일회성 행사, 검증되지 않은 창업, 현금흐름이 마이너스인 수익형 부동산, 빚으로 사는 주식과 코인, 사용 빈도가 낮은 고가 취미 자산, 시세 상승 기대만으로 무리하게 갈아타는 집 등을 꼽습니다."]]},{"t":"③ 삶의 첫 질문이 대출금으로","n":[["설명","이런 빚을 지면 \"첫 번째 질문이 바뀝니다.\" 내가 이 일을 원하는가가 아니라, 다음 달 대출금을 어떻게 낼 것인가가 삶의 첫 번째 질문이 되어 버립니다."],["쉬운 예","좋은 빚은 씨앗을 사기 위해 빌린 돈과 같습니다. 씨앗이 자라 열매를 맺으면 그 열매로 빚을 갚고도 남습니다. 나쁜 빚은 사탕을 사기 위해 빌린 돈입니다. 사탕은 먹으면 없어지지만, 빌린 돈은 그대로 남습니다."]]}],"h":"소·빚·삶 → 소빚삶 → 소비 후 남는 것 없음·빚내면 위험한 10가지·삶이 대출금 중심"}]},{"t":"2. 빚을 갚는 순서","c":[{"t":"(1) 금리가 높은 빚부터","c":[{"t":"① 눈사태 방식: 고금리부터","n":[["설명","여러 빚이 있다면 이자율이 가장 높은 빚부터 갚는 것이 수학적으로 가장 유리합니다. 이것을 눈사태 방식이라고 합니다."]]},{"t":"② 눈덩이 방식: 소액부터","n":[["설명","반대로 금액이 가장 작은 빚부터 하나씩 없애 성취감을 얻는 눈덩이 방식도 있습니다. 의지가 약해지기 쉬운 사람에게 효과가 있습니다."]]},{"t":"③ 새 빚 금지·고금리 우선","n":[["설명","어느 방식이든 공통 원칙은 \"새 빚을 만들지 않는 것\"과 \"카드론·현금서비스·리볼빙 같은 고금리 빚을 가장 먼저 없애는 것\"입니다."]]}],"h":"눈·눈·새 → 눈눈새 → 눈사태(고금리부터)·눈덩이(소액부터)·새 빚 금지"},{"t":"(2) 리볼빙의 함정","c":[{"t":"① 리볼빙 = 연 10%대 후반 이자","n":[["설명","리볼빙(일부결제금액 이월약정)은 카드값의 일부만 내고 나머지를 다음 달로 미루는 서비스입니다. 편해 보이지만 미룬 돈에 연 10%대 후반의 높은 이자가 붙는 경우가 많습니다."]]},{"t":"② 이월액 누적 → 감당 불가","n":[["설명","리볼빙을 쓰기 시작하면 매달 미뤄지는 금액이 쌓여, 어느 순간 카드값을 감당할 수 없게 됩니다."]]},{"t":"③ 리볼빙 설정 확인·해지","n":[["설명","카드 앱에서 리볼빙이 설정되어 있는지 확인하고, 사용하지 않는다면 해지합니다."],["따라 해 보기","F씨는 카드론 500만 원(연 16%)과 신용대출 2,000만 원(연 5.5%)이 있고, 매달 추가로 50만 원을 갚을 수 있습니다. 어느 빚부터 갚아야 할까요?\n\n결과 이자율이 높은 카드론부터 갚습니다. 카드론 500만 원에서 1년 동안 나가는 이자는 약 80만 원이고, 같은 돈으로 신용대출을 갚으면 줄어드는 이자는 약 27만 5,000원뿐입니다. 약 10개월이면 카드론을 없앨 수 있고, 그 뒤 매달 50만 원에 카드론 원리금으로 나가던 돈까지 더해 신용대출을 갚습니다."]],"tb":[[["빚 종류","대략적인 금리 수준","우선순위"],["현금서비스·카드론·리볼빙","연 10%대 중후반 이상인 경우가 많음","가장 먼저 갚기"],["신용대출·마이너스통장","연 4~7%대(신용도에 따라 다름)","두 번째"],["주택담보대출","연 3~5%대(시기·상품에 따라 다름)","계획대로 상환"],["정책 대출(디딤돌·버팀목 등)","상대적으로 낮음","서두르지 않아도 됨"]]]}],"h":"리·이·리 → 리이리 → 리볼빙 고금리·이월 누적·리볼빙 확인 해지"}]}]},{"t":"Ⅱ 고금리 시대의 빚 관리","c":[{"t":"1. 금리 인상기에 특히 위험한 빚","c":[{"t":"(1) 변동금리 대출","c":[{"t":"① 7·8월 인상으로 부담 증가","n":[["설명","변동금리는 시장 금리에 따라 대출 이자가 바뀌는 방식입니다. 기준금리가 2026년 7월과 8월에 연속으로 오르면서 변동금리 대출자의 이자 부담이 커졌습니다."]]},{"t":"② 3억 대출 +1%p = 월 25만","n":[["설명","3억 원을 대출받았을 때 금리가 1%포인트 오르면 1년 이자가 약 300만 원, 한 달에 약 25만 원 늘어납니다."]]},{"t":"③ +1~2%p 견딜지 계산","n":[["설명","한국은행이 추가 인상 가능성을 열어 둔 만큼, 변동금리 대출이 많다면 \"금리가 1~2%포인트 더 올라도 견딜 수 있는가\"를 미리 계산해 두어야 합니다."]]}],"h":"7·3·1 → 7 3 1 → 7·8월 인상·3억에 +1%p·1~2%p 견딜지"},{"t":"(2) 만기가 은퇴와 겹치는 대출","c":[{"t":"① 대출 만기·은퇴 시점 불일치","n":[["설명","첨부 영상 「노후에 돈이 부족해지는 사람들은 40대부터 이것을 놓칩니다」는 \"대출의 만기와 은퇴 시점이 연결되어 있지 않은 것\"을 다섯 번째 위험 신호로 꼽습니다."]]},{"t":"② 45세 30년 만기 = 75세","n":[["설명","45세에 30년 만기 주택대출을 받으면 75세까지 갚아야 합니다. 그런데 월급은 대개 60세 전후에 끊깁니다. 15년 동안 연금으로 대출을 갚아야 하는 구조가 됩니다."]]},{"t":"③ 은퇴 시 잔여 대출 계산","n":[["설명","그래서 대출을 받을 때는 \"은퇴 전까지 얼마를 갚을 수 있는가\", \"은퇴할 때 남는 대출은 얼마인가\"를 함께 계산합니다."],["핵심 포인트","고금리 시대 빚 점검 3가지: ① 금리가 2%포인트 오르면 월 상환액이 얼마나 늘어나는가 ② 대출 만기가 은퇴 시점보다 늦지 않은가 ③ 상환 재원이 월급·사업 수입인가, 아니면 자산 가격 상승인가."]]}],"h":"대·4·은 → 대4은 → 대출 만기와 은퇴·45세 30년 만기·은퇴 시 잔액"}]},{"t":"2. DSR — 은행이 빚의 한도를 정하는 방법","c":[{"t":"(1) DSR이란","c":[{"t":"① 연 원리금 ÷ 연소득","n":[["설명","DSR(총부채원리금상환비율)은 1년 동안 갚아야 하는 모든 대출의 원금과 이자를 연소득으로 나눈 비율입니다."]]},{"t":"② 은행권 40% 상한","n":[["설명","은행권에서는 이 비율이 원칙적으로 40%를 넘지 않도록 대출을 제한합니다. 연소득 7,000만 원이면 모든 대출의 1 년 원리금 상환액이 2,800만 원 이하여야 합니다."]]},{"t":"③ 스트레스 DSR 3단계","n":[["설명","여기에 스트레스 DSR이 더해집니다. 앞으로 금리가 오를 수 있다고 가정해 일정한 \"스트레스 금리\"를 더해 계산하는 방식으로, 2025년 7월부터 3단계가 시행되어 대출 한도가 더 줄었습니다."]]}],"h":"연·은·스 → 연은스 → 연 원리금÷소득·은행 40%·스트레스 DSR"},{"t":"(2) DSR을 나의 기준으로 쓰기","c":[{"t":"① 40%는 최대한도일 뿐","n":[["설명","은행이 허락하는 DSR 40%는 \"최대한도\"이지 \"적정선\"이 아닙니다. 40%면 세전 소득의 거의 절반 가까이가 빚 갚는 데 나가므로, 생활과 저축이 매우 빠듯해집니다."]]},{"t":"② 세후 소득 25~30% 이내","n":[["설명","많은 재무 전문가는 주택담보대출을 포함한 원리금 상환액을 세후 소득의 25~30% 이내로 유지하라고 권합니다."]]},{"t":"③ 견딜 수 있는 만큼이 한도","n":[["설명","\"은행이 빌려주는 만큼\"이 아니라 \"내가 금리 인상과 소득 감소까지 견딜 수 있는 만큼\"이 나의 대출 한도입니다."],["실제 사례","연소득 7,000만 원인 G씨는 은행에서 \"DSR 40%까지 대출 가능\"하다는 말을 듣고 최대한도로 대출을 받으려 했습니다. 그러나 월 233만 원을 갚으면 세후 월급 약 470만 원 중 절반이 빠져나가 저축이 거의 불가능하다는 것을 계산해 보고, 대출을 월 상환 140만 원 수준으로 줄였습니다. 그 대신 더 작은 집을 선택했고, 남는 돈으로 연금저축과 비상금을 계속 채울 수 있었습니다."]],"tb":[[["연소득","DSR 40% 기준 연간 원리금 한도","월 기준","권장(세후 소득 25~30%) 참고"],["5,000만 원","2,000만 원","약 167만 원","월 약 85만~100만 원"],["7,000만 원","2,800만 원","약 233만 원","월 약 115만~140만 원"],["1억 원","4,000만 원","약 333만 원","월 약 155만~185만 원"]]]}],"h":"4·세·견 → 4세견 → 40%는 최대일 뿐·세후 25~30%·견딜 만큼"}]}]},{"t":"Ⅲ 레버리지로 빨리 부자가 되려다 가난해지는 이유","c":[{"t":"1. 레버리지가 자산을 무너뜨리는 원리","c":[{"t":"(1) 손실이 자기 자본을 빠르게 파괴한다","c":[{"t":"① −20%면 내 몫 −40%","n":[["설명","내 돈 1억 원에 빚 1억 원을 더해 2억 원을 투자했다고 해 봅시다. 자산이 20% 떨어지면 2억 원은 1억 6,000만 원이 되고, 빚 1억 원을 빼면 내 몫은 6,000만 원입니다. 시장은 20% 떨어졌는데 내 돈은 40% 사라졌습니다."]]},{"t":"② −50%면 내 몫 0원","n":[["설명","자산이 50% 떨어지면 1억 원만 남고, 빚을 갚으면 내 몫은 0원입니다. 빚이 없었다면 5,000만 원은 남았을 것입니다."]]},{"t":"③ 자본 자체를 빠르게 소멸","n":[["설명","이처럼 레버리지는 손실을 단순히 키우는 것이 아니라, 내 자본 자체를 훨씬 빠르게 없앱니다."]]}],"h":"2·5·자 → 2 5 자 → −20%면 내 몫 −40·−50%면 0원·자본 소멸"},{"t":"(2) 시간이 내 편이 아니게 된다","c":[{"t":"① 이자·만기로 못 기다림","n":[["설명","빚 없이 투자한 사람은 시장이 떨어져도 회복될 때까지 기다릴 수 있습니다. 그러나 빚을 낸 사람은 매달 이자를 내야하고, 만기가 오면 갚아야 합니다."]]},{"t":"② 신용거래 반대매매","n":[["설명","주식 신용거래의 경우 담보 비율이 떨어지면 반대매매로 가장 낮은 가격에 강제로 팔릴 수 있습니다. 회복을 기다릴 기회조차 사라집니다."]]},{"t":"③ 주가는 급락, 빚은 그대로","n":[["설명","2026년 11월 6일 폭락 때 \"삼전닉스 주가는 급락, 빚은 그대로\"라는 제목의 기사가 나온 것도 같은 이유입니다. 주가는 떨어져도 빚의 크기는 줄지 않습니다."],["쉬운 예","친구에게 1만 원을 빌려 2만 원어치 딱지를 샀는데 딱지 값이 절반으로 떨어지면, 딱지를 다 팔아도 1만 원밖에 안 됩니다. 빌린 1만 원을 갚으면 내 돈은 하나도 남지 않습니다. 빌리지 않았다면 5,000원은 남았을 겁니다."]]}],"h":"이·신·주 → 이신주 → 이자 만기·신용 반대매매·주가 급락 빚 그대로"}]},{"t":"2. 레버리지의 심리적 함정","c":[{"t":"(1) 생활 위험과 투자 위험이 연결된다","c":[{"t":"① 투자 위험이 생활 위험으로","n":[["설명","레버리지는 투자 위험을 생활 위험과 연결합니다. 투자가 잘못되면 단지 투자금만 잃는 것이 아니라 집, 가족의 생활비, 신용까지 흔들립니다."]]},{"t":"② 집중 투자로 내몰림","n":[["설명","레버리지는 또 사람을 자연스럽게 집중 투자로 밀어 넣습니다. 이자를 감당하려면 큰 수익이 필요하니, 한두 종목에 몰아 넣게 되는 것입니다."]]},{"t":"③ 집중+레버리지 = 전부 상실","n":[["설명","집중과 레버리지가 겹치면 한 번의 사건(예: 반도체 업황 충격)으로 모든 것을 잃을 수 있습니다."]]}],"h":"투·집·집 → 투집집 → 투자위험이 생활위험·집중 투자·집중+레버리지=전부"},{"t":"(2) 손실을 회복하려는 더 큰 레버리지","c":[{"t":"① 한 번만 맞히면 된다는 유혹","n":[["설명","레버리지로 큰 손실을 본 사람은 \"이번에 한 번만 제대로 맞히면 돼\"라는 생각으로 다시 더 큰 빚을 내고 싶어집니다."]]},{"t":"② 판돈 키우는 도박 심리","n":[["설명","이것은 도박에서 잃은 돈을 되찾으려 판돈을 키우는 것과 같은 심리적 함정입니다."]]},{"t":"③ 손실 한도·빚 증액 금지","n":[["설명","레버리지를 쓸 때는 미리 \"최대 얼마까지 잃으면 멈춘다\"는 규칙을 정하고, 손실이 났을 때 빚을 늘리지 않는 원칙을 지켜야 합니다."],["핵심 포인트","레버리지를 쓸 수 있는 조건: ① 상환 재원이 현금흐름(월급·임대료·사업 수입)에서 나온다 ② 자산이 30~50% 떨어져도 강제로 팔리지 않는다 ③ 금리가 올라도 이자를 낼 수 있다 ④ 한 자산에 몰지 않는다. 하나라도 아니라면 레버리지를 줄이세요."]],"tb":[[["자산 가격 변화","빚 없이(내 돈 1억)","빚 1억 + 내 돈 1억","빚 3억 + 내 돈 1억"],["+20%","1억 2,000만(+20%)","1억 4,000만(+40%)","1억 8,000만(+80%)"],["−10%","9,000만(−10%)","8,000만(−20%)","6,000만(−40%)"],["−25%","7,500만(−25%)","5,000만(−50%)","0원(−100%)"],["−50%","5,000만(−50%)","0원(−100%)","−1억(빚만 남음)"]]]}],"h":"한·판·손 → 한판손 → 한 방 심리·판돈 키우기·손실 한도"}]}]}]},{"n":5,"t":"투자의 기본 — 돈이 스스로 일하게 만들기","c":[{"t":"Ⅰ 투자 상품의 기본 성격","c":[{"t":"1. 예금·채권·주식·부동산의 차이","c":[{"t":"(1) 돈을 빌려주는 투자와 주인이 되는 투자","c":[{"t":"① 예금·채권: 빌려주고 이자","n":[["설명","예금과 채권은 내 돈을 은행이나 정부·회사에 빌려주고 약속된 이자를 받는 것입니다. 수익은 비교적 작지만 안정적입니다."]]},{"t":"② 주식: 회사의 주인","n":[["설명","주식은 회사의 주인 중 한 명이 되는 것입니다. 회사가 돈을 잘 벌면 주가가 오르고 배당을 받지만, 회사가 어려워지면 주가가 크게 떨어질 수 있습니다."]]},{"t":"③ 부동산: 임대·시세차익","n":[["설명","부동산은 땅과 건물을 소유하는 것입니다. 임대료와 가격 상승을 기대할 수 있지만, 큰돈이 들고 사고팔기가 느리며 세금과 비용이 많습니다."]]}],"h":"예·주·부 → 예주부 → 예주부 → 예금채권(빌려줌)·주식(주인)·부동산"},{"t":"(2) 위험과 수익은 짝꿍이다","c":[{"t":"① 고수익엔 고위험","n":[["설명","투자의 세계에는 \"높은 수익에는 높은 위험이 따른다\"는 원칙이 있습니다. 위험 없이 높은 수익을 약속하는 상품은 사기일 가능성이 큽니다."]]},{"t":"② 위험 = 변동성+원금손실","n":[["설명","여기서 위험은 \"값이 크게 오르내리는 정도(변동성)\"와 \"원금을 잃을 가능성\"을 말합니다."]]},{"t":"③ 원금보장 고수익은 사기","n":[["설명","\"원금 보장에 연 20% 수익\" 같은 말을 들으면 즉시 의심해야 합니다. 금융감독원은 이런 유사수신(불법 자금 모집) 행위를 꾸준히 경고하고 있습니다."],["쉬운 예","예금은 친구에게 연필을 빌려주고 사탕 한 개를 받기로 약속하는 것이고, 주식은 친구와 함께 레모네이드 가게를 차려 주인이 되는 것입니다. 가게가 잘되면 큰돈을 벌지만, 비 오는 날이 계속되면 손해를 볼 수도 있습니다."]],"tb":[[["자산","수익의 원천","변동성","현금화 속도","이런 사람에게"],["예금","이자","매우 낮음","빠름","비상금, 단기 목표 자금"],["채권","이자 + 가격 변동","낮음~중간","빠름","안정적 수입, 주식 위험 완화"],["주식·ETF","기업 이익 성장 + 배당","높음","빠름","5년 이상 장기 자금"],["부동산","임대료 + 가격 변동","중간(체감은 낮음)","느림","실거주, 큰 자금, 장기 보유"]]]}],"h":"고·위·원 → 고위원 → 고수익 고위험·위험=변동성·원금보장 고수익은 사기"}]},{"t":"2. 개별 주식보다 지수 투자","c":[{"t":"(1) ETF와 인덱스 투자","c":[{"t":"① ETF: 한 바구니 상품","n":[["설명","ETF(상장지수펀드)는 여러 주식이나 채권을 한 바구니에 담아 주식처럼 사고팔 수 있게 만든 상품입니다. 코스피 200 ETF 하나를 사면 한국 대표 기업 200곳에 조금씩 투자하는 효과가 있습니다."]]},{"t":"② 인덱스: 시장 전체 추종","n":[["설명","인덱스 투자는 특정 시장 전체(지수)를 그대로 따라가는 투자입니다. 어떤 회사가 오를지 맞히려 하지 않고, 시장 전체의 성장을 함께 누립니다."]]},{"t":"③ 저비용·분산, 직장인 적합","n":[["설명","수수료가 낮고 분산 효과가 커서, 투자 공부를 많이 할 시간이 없는 직장인에게 특히 알맞은 방법으로 널리 추천됩니다."]]}],"h":"E·인·저 → E인저 → ETF·인덱스·저비용"},{"t":"(2) 개별 주식 투자의 어려움","c":[{"t":"① 한 회사 사정에 흔들림","n":[["설명","개별 주식은 회사 한 곳의 사정에 크게 흔들립니다. 2026년 11월 6일 SK하이닉스가 하루 10% 넘게 떨어진 것처럼, 좋은 회사도 단기간에 큰 하락을 겪을 수 있습니다."]]},{"t":"② SPIVA: 액티브 대부분 열위","n":[["설명","개별 주식으로 꾸준히 시장보다 높은 수익을 내는 것은 전문가에게도 어렵습니다. 미국 S&P의 SPIVA 보고서는 장기간 동안 대부분의 액티브 펀드가 지수보다 낮은 성과를 냈다고 매년 보고합니다."]]},{"t":"③ 핵심-위성 전략(10~20%)","n":[["설명","개별 주식을 하고 싶다면 전체 투자금의 일부(예: 10~20%)만 \"공부용\"으로 쓰고, 핵심 자산은 지수에 두는 핵심-위성 전략을 쓸 수 있습니다."],["핵심 포인트","투자 초보의 기본 순서: ① 비상금 먼저 ② 세제 혜택 계좌(ISA·연금저축·IRP) 열기 ③ 넓게 분산된 지수 ETF로 시작 ④ 매달 같은 날 같은 금액을 자동으로 사기(적립식) ⑤ 개별 종목은 공부한 만큼만 작게."]]}],"h":"한·S·핵 → 한S핵 → 한 회사에 흔들·SPIVA·핵심-위성"}]}]},{"t":"Ⅱ 자산배분과 적립식 투자","c":[{"t":"1. 자산배분 — 바구니를 어떻게 나눌까","c":[{"t":"(1) 나이와 목표에 맞춘 배분","c":[{"t":"① 성과는 자산배분이 좌우","n":[["설명","자산배분은 전체 돈을 주식, 채권, 현금 등에 어떤 비율로 나눌지 정하는 것입니다. 투자 성과의 큰 부분이 개별 종목 선택보다 자산배분에서 결정된다는 연구가 많습니다."]]},{"t":"② 주식 비중 = 100 − 나이","n":[["설명","흔히 쓰는 간단한 기준으로 \"주식 비중 = 100 − 나이\" 같은 규칙이 있습니다. 30세면 주식 70%, 60세면 주식 40% 정도입니다. 절대 공식은 아니고, 출발점으로 쓰는 참고 기준입니다."]]},{"t":"③ 쓸 시기 가까우면 주식 축소","n":[["설명","돈을 쓸 시기가 가까울수록 주식 비중을 줄입니다. 3년 뒤 집을 살 돈을 주식에 몽땅 넣으면, 그때 시장이 떨어져 있을 경우 계획이 무너집니다."]]}],"h":"성·주·쓸 → 성주쓸 → 성과는 배분·주식=100−나이·쓸 때 가까우면 축소"},{"t":"(2) 리밸런싱 — 정기적으로 비율 되돌리기","c":[{"t":"① 시간 지나면 비율 흐트러짐","n":[["설명","시간이 지나면 오른 자산의 비중이 커지고, 떨어진 자산의 비중이 작아져 처음 정한 비율이 흐트러집니다."]]},{"t":"② 연 1~2회 원래 비율로","n":[["설명","리밸런싱은 1년에 한두 번 처음 비율로 되돌리는 것입니다. 많이 오른 것을 조금 팔고, 덜 오른 것을 조금 사게 되어 자연스럽게 \"비쌀 때 팔고 쌀 때 사는\" 효과가 생깁니다."]]},{"t":"③ 폭락 전 리밸런싱 효과","n":[["설명","2026년처럼 반도체주가 크게 올라 주식 비중이 처음 계획보다 많이 커졌다면, 폭락 전에 리밸런싱을 한 사람은 손실을 줄일 수 있었습니다."],["쉬운 예","리밸런싱은 화분 가지치기와 같습니다. 한쪽 가지만 너무 길게 자라면 화분이 기울어 넘어질 수 있으니, 정기적으로 다듬어 균형을 잡아 주는 것입니다."]],"tb":[[["나이대(예시)","주식","채권","현금성","비고"],["20~30대","70~80%","10~20%","비상금 별도","시간이 길어 변동성을 견딜 여유"],["40대","60~70%","20~30%","비상금 별도","자녀·주택 지출 시기 고려"],["50대","40~60%","30~45%","5~10%","은퇴 전 위험 줄이기 시작"],["60대 이후","30~40%","40~50%","1~2년 생활비","인출 시기의 폭락 대비"]]]}],"h":"시·연·폭 → 시연폭 → 시간 지나 흐트러짐·연 1~2회·폭락 전 효과"}]},{"t":"2. 적립식 투자 — 시점을 맞히려 하지 않기","c":[{"t":"(1) 적립식 투자의 원리","c":[{"t":"① 매달 정해진 금액 매수","n":[["설명","적립식 투자는 매달 정해진 날에 정해진 금액을 꾸준히 사는 방법입니다. 가격이 높을 때는 적게, 낮을 때는 많이 사게 되어 평균 매입 단가가 고르게 맞춰집니다."]]},{"t":"② 매수 시점 고민 제거","n":[["설명","이 방법의 가장 큰 장점은 \"언제 사야 하나\"라는 고민을 없애 준다는 것입니다. 시장의 바닥과 꼭대기를 맞히는 일은 전문가도 거의 하지 못합니다."]]},{"t":"③ 월급날 자동이체","n":[["설명","월급날 자동이체로 연결해 두면 감정에 휘둘리지 않고 투자를 이어 갈 수 있습니다."]]}],"h":"매·매·월 → 매매월 → 매달 정액·매수 시점 고민 제거·월급날 자동"},{"t":"(2) 큰돈이 생겼을 때는 나누어서","c":[{"t":"① 목돈은 6~12개월 분할","n":[["설명","상여금이나 퇴직금처럼 큰돈이 한꺼번에 생기면, 한 번에 다 넣기보다 6~12개월에 나누어 넣는 방법이 마음 편합니다."]]},{"t":"② 일시투자 유리 vs 후회 위험","n":[["설명","통계적으로는 한 번에 넣는 것이 평균적으로 유리하다는 연구도 있지만, 넣자마자 폭락하면 후회와 공포 때문에 투자를 그만둘 위험이 있습니다."]]},{"t":"③ 하락 감내력에 맞춰 선택","n":[["설명","자신이 하락을 얼마나 견딜 수 있는지에 따라 방법을 정하는 것이 좋습니다."],["따라 해 보기","매달 30만 원씩 ETF를 산다고 합시다. 1월 가격 1만 원, 2월 7,500원, 3월 1만 2,000원이었다면 석 달 동안 산 수량과 평균 매입 단가는 얼마일까요?\n\n결과 1월 30주, 2월 40주, 3월 25주 → 모두 95주를 90만 원에 샀으므로 평균 단가는 약 9,474원입니다. 세 달 가격의 단순 평균(9,833원)보다 낮습니다. 가격이 쌀 때 더 많이 사기 때문입니다."]]}],"h":"목·일·하 → 목일하 → 목돈 분할·일시투자 장단·하락 감내력"}]}]},{"t":"Ⅲ 주식이 폭락할 때 부자들이 절대 하지 않는 행동","c":[{"t":"1. 공포와 욕심에서 나오는 실수","c":[{"t":"(1) 겁에 질려 모두 파는 것","c":[{"t":"① 공포 매도 = 손실 확정","n":[["설명","폭락한 날 겁에 질려 모든 주식을 팔면, 손실이 \"확정\"됩니다. 그리고 시장이 회복될 때 다시 사기가 매우 어렵습니다."]]},{"t":"② 폭락 뒤 회복 사례 다수","n":[["설명","역사적으로 큰 폭락 뒤에는 회복이 따라온 경우가 많았습니다. 다만 회복까지 걸리는 시간은 몇 달에서 몇 년까지 다양했습니다."]]},{"t":"③ 생활비 부족인가 공포인가","n":[["설명","그래서 \"팔아야 하는 이유가 생활비 부족인가, 아니면 공포인가\"를 먼저 구분해야 합니다. 생활비 문제라면 비상금이 해결책이고, 공포라면 기다림이 해결책인 경우가 많습니다."]]}],"h":"공·폭·생 → 공폭생 → 공포매도=손실 확정·폭락 뒤 회복·생활비 vs 공포"},{"t":"(2) 바닥을 맞히려고 전 재산을 한 번에","c":[{"t":"① 바닥은 지나야 안다","n":[["설명","반대로 \"지금이 바닥이다\"라며 가진 돈 전부를 한 번에 넣는 것도 위험합니다. 바닥은 지나고 나서야 알 수 있습니다."]]},{"t":"② 4,911 바닥 착각 위험","n":[["설명","11월 6일 장중 4,911에서 '바닥'이라 생각하고 다 넣은 사람도, 다음 날 더 떨어진다면 버틸 힘이 없어집니다."]]},{"t":"③ 기회자금 3~4회 분할매수","n":[["설명","부자들은 하락장에서 살 때도 여러 번에 나누어 삽니다. 예를 들어 기회 자금을 3~4번으로 나누어, 지수가 일정 비율 떨어질 때마다 조금씩 삽니다."]]}],"h":"바·4·기 → 바4기 → 바닥은 지나야 앎·4,911 착각·기회자금 분할"},{"t":"(3) 빚을 내서 물타기","c":[{"t":"① 신용·대출 물타기 위험","n":[["설명","물타기는 가격이 떨어진 주식을 더 사서 평균 단가를 낮추는 것입니다. 여기에 신용과 대출까지 쓰면 매우 위험합니다."]]},{"t":"② 반대매매로 회복 기회 상실","n":[["설명","주가가 더 떨어지면 반대매매로 가장 낮은 가격에 강제 처분되어 회복의 기회조차 잃습니다."]]},{"t":"③ 하락장엔 빚 축소·현금 보호","n":[["설명","부자들은 하락장에서 빚을 늘리지 않고, 오히려 빚을 줄이고 현금을 지킵니다."],["실제 사례","11월 6일 코스피가 장중 −8.78%까지 밀렸을 때, 반도체 두 종목에 신용으로 몰아 투자했던 H씨는 담보 비율 부족 통보를 받고 오후에 일부 주식이 반대매매되었습니다. 반면 같은 직장의 I씨는 주식 60%, 채권 30%, 현금 10%로 나누어 두었기 때문에 계좌 전체 손실이 4% 남짓이었고, 미리 정해 둔 규칙에 따라 현금의 3분의 1로 지수 ETF를 조금 샀습니다. 두 사람의 차이는 종목 선택이 아니라 \"준비\"였습니다."]]}],"h":"신·반·하 → 신반하 → 신용 물타기·반대매매·하락장엔 빚 축소"}],"h":"겁·바·빚 → 겁바빚 → 겁먹고 매도·바닥 맞히기·빚내서 물타기"},{"t":"2. 하락장에서 지켜야 할 원칙","c":[{"t":"(1) 비상금은 투자하지 않는다","c":[{"t":"① 폭락장에도 비상금 투자 금지","n":[["설명","폭락장이 기회처럼 보여도 비상금까지 주식에 넣으면 안 됩니다. 하락장은 종종 경기침체와 함께 오고, 경기침체는 실직 위험을 키웁니다."]]},{"t":"② 하락·자금 필요 시기 중첩","n":[["설명","주가가 떨어지는 시기와 내가 돈이 필요한 시기가 겹치면, 가장 싼 값에 팔아야 합니다."]]},{"t":"③ 비상금은 버티게 하는 돈","n":[["설명","비상금은 하락장에서 \"쓰는 돈\"이 아니라 \"버티게 해 주는 돈\"입니다."]]}],"h":"폭·하·비 → 폭하비 → 폭락에도 비상금 X·하락과 자금 필요 겹침·버티는 돈"},{"t":"(2) 거래를 늘리지 않는다","c":[{"t":"① 잦은 매매 = 비용·오판","n":[["설명","뉴스가 자극적일수록 거래를 더 많이 하고 싶어집니다. 그러나 잦은 매매는 수수료와 세금, 그리고 잘못된 판단을 늘립니다."]]},{"t":"② 레버리지 ETF·코인 이동 금지","n":[["설명","폭락한 종목 하나에 \"싸 보인다\"며 집중하거나, 손실을 빨리 복구하려고 레버리지 ETF·코인 같은 더 위험한 상품으로 옮기는 것도 피해야 할 행동입니다."]]},{"t":"③ 앱 닫고 원칙만 실행","n":[["설명","차라리 증권 앱을 며칠 닫아 두고, 미리 정한 원칙(리밸런싱, 분할 매수)만 실행하는 것이 낫습니다."]]}],"h":"잦·레·앱 → 잦레앱 → 잦은 매매·레버리지 이탈·앱 닫기"},{"t":"(3) 은퇴가 가까우면 위험 비중을 점검한다","c":[{"t":"① 은퇴 임박 시 위험 비중 점검","n":[["설명","첨부 자료는 \"은퇴가 가까운데도 장기적으로 오를 것이라는 말만 믿고 위험 비중을 그대로 유지하는 것\"을 피해야 할 행동으로 꼽습니다."]]},{"t":"② 은퇴 직전 하락 = 계획 붕괴","n":[["설명","30세에게 20년은 기다릴 수 있는 시간이지만, 60세에게 20년은 인생의 큰 부분입니다. 은퇴 직전·직후의 큰 하락은 노후 계획 전체를 흔듭니다(이를 수익률 순서 위험이라 합니다)."]]},{"t":"③ 5~10년 전부터 주식 축소","n":[["설명","은퇴 5~10년 전부터 주식 비중을 천천히 줄이고, 1~2년치 생활비를 안전 자산으로 확보해 두는 것이 좋습니다."],["핵심 포인트","폭락장의 승자는 \"가장 잘 맞힌 사람\"이 아니라 \"가장 오래 버틴 사람\"입니다. 버틸 힘은 ① 비상금 ② 빚 없는 투자 ③ 분산 ④ 미리 정한 규칙에서 나옵니다."]],"tb":[[["폭락장에서 하지 않는 행동","대신 하는 행동"],["겁에 질려 전부 매도","팔아야 할 이유(생활비/공포)를 구분"],["바닥 맞히려 한 번에 몰빵","기회 자금을 3~4번 나누어 분할 매수"],["빚 내서 물타기","빚을 늘리지 않고 현금 유지"],["비상금까지 투자","비상금은 손대지 않음"],["뉴스 따라 잦은 매매","미리 정한 리밸런싱 규칙만 실행"],["손실 복구하려 고위험 상품 이동","원래 자산배분으로 복귀"],["은퇴 직전에도 고위험 유지","은퇴 5~10년 전부터 위험 축소"]]]}],"h":"은·은·5 → 은은5 → 은퇴 임박 점검·은퇴 직전 하락·5~10년 전부터"}],"h":"비·거·은 → 비거은 → 비상금 투자 X·거래 늘리지 않기·은퇴 전 점검"}]}]},{"n":6,"t":"세금을 아는 사람이 부자가 된다 — 절세 계좌 총정리","c":[{"t":"Ⅰ 투자 소득에 붙는 세금의 기초","c":[{"t":"1. 금융소득과 세금","c":[{"t":"(1) 이자·배당소득세 15.4%","c":[{"t":"① 이자·배당 원천징수 15.4%","n":[["설명","예금 이자나 국내 주식 배당을 받으면 보통 15.4%(소득세 14% + 지방소득세 1.4%)의 세금이 떼이고 들어옵니다. 이것을 원천징수라고 합니다."]]},{"t":"② 이자 100만 → 84.6만","n":[["설명","100만 원의 이자를 받으면 15만 4,000원이 세금으로 빠지고 84만 6,000원이 들어옵니다."]]},{"t":"③ 국내상장 해외ETF 차익 과세","n":[["설명","해외 ETF나 해외 주식의 배당에도 세금이 붙고, 국내 상장 해외 ETF의 매매 차익에도 배당소득세(15.4%)가 붙는다는 점을 기억해야 합니다."]]}],"h":"이·이·국 → 이이국 → 15.4%·100만이면 84.6만·국내상장 해외ETF"},{"t":"(2) 금융소득종합과세","c":[{"t":"① 2,000만 초과 시 종합과세","n":[["설명","1년 동안 이자와 배당을 합친 금융소득이 2,000만 원을 넘으면, 넘는 부분은 근로소득 등 다른 소득과 합쳐 누진세율(최고 45%, 지방세 포함 49.5%)로 과세됩니다. 이를 금융소득종합과세라고 합니다."]]},{"t":"② 비과세·분리과세 계좌 활용","n":[["설명","금융소득이 많은 사람일수록 세금이 크게 늘 수 있으므로, 비과세·분리과세 계좌를 활용하는 것이 중요합니다."]]},{"t":"③ 종합과세자 ISA 가입 제한","n":[["설명","또한 금융소득종합과세 대상자가 되면 ISA 가입이 제한되는 등 다른 불이익도 생길 수 있습니다."],["쉬운 예","세금은 물을 담은 컵에 난 작은 구멍과 같습니다. 구멍이 작아 보여도 오랫동안 물을 부으면 새는 양이 꽤 많아집니다. 절세 계좌는 그 구멍을 막아 주거나 작게 만들어 주는 테이프입니다."]]}],"h":"2·비·종 → 2비종 → 2,000만 초과·비과세 계좌·종합과세자 ISA"}]},{"t":"2. 2026년에 바뀐 배당 세금","c":[{"t":"(1) 고배당 기업 배당소득 분리과세","c":[{"t":"① 고배당 기업 배당 분리과세","n":[["설명","2025년 12월 국회를 통과한 세법 개정으로, 2026년 1월 1일 이후 지급되는 배당 중 고배당 상장기업의 배당은 다른 소득과 합치지 않고 따로(분리) 과세할 수 있게 되었습니다. 2028년까지 3년간 한시적으로 시행됩니다."]]},{"t":"② 세율 14·20·25·30%","n":[["설명","세율은 배당소득 2,000만 원 이하 14%, 2,000만 원 초과~3억 원 이하 20%, 3억 원 초과~50억 원 이하 25%, 50억 원 초과 30%입니다(지방소득세 별도)."]]},{"t":"③ 배당성향 40% 이상 등 요건","n":[["설명","대상이 되는 고배당 기업은 배당성향(이익 중 배당으로 나눠 주는 비율)이 40% 이상이거나, 25% 이상이면서 전년보다 배당을 10% 이상 늘린 기업 등입니다."]]}],"h":"고·세·배 → 고세배 → 고배당 분리과세·세율 단계·배당성향 40%"},{"t":"(2) 누구에게 의미가 있나","c":[{"t":"① 소액 투자자는 차이 미미","n":[["설명","배당 금액이 적어 금융소득종합과세 대상이 아닌 대부분의 개인에게는 기존 15.4%와 큰 차이가 없습니다."]]},{"t":"② 고액 투자자에 유리","n":[["설명","배당소득이 많아 종합과세 최고세율 구간에 해당하던 고액 투자자에게 특히 유리합니다."]]},{"t":"③ 해외주식·ETF 분배금 제외","n":[["설명","해외 주식 배당과 ETF 분배금은 이 제도의 대상이 아니라는 점에 주의합니다."],["핵심 포인트","고배당 기업 배당 분리과세: 2026~2028년 지급분, 세율 14·20·25·30%. 해외 주식 배당·ETF 분배금은 제외. 일반 개인은 큰 변화가 없고 고액 배당 투자자에게 의미가 큽니다."]],"tb":[[["배당소득 과세표준","분리과세 세율(지방세 별도)"],["2,000만 원 이하","14%"],["2,000만 원 초과 ~ 3억 원 이하","20%"],["3억 원 초과 ~ 50억 원 이하","25%"],["50억 원 초과","30%"]]]}],"h":"소·고·해 → 소고해 → 소액 미미·고액 유리·해외 ETF 제외"}]}]},{"t":"Ⅱ ISA — 만능 절세 통장","c":[{"t":"1. ISA의 기본 구조","c":[{"t":"(1) ISA란","c":[{"t":"① 한 계좌 통합운용·세제혜택","n":[["설명","ISA(개인종합자산관리계좌)는 예금, 펀드, ETF, 국내 주식 등을 한 계좌에 담아 운용하고, 나온 수익에 세금 혜택을 주는 계좌입니다."]]},{"t":"② 만 19세 이상 가입","n":[["설명","만 19세 이상(근로소득이 있으면 15세 이상)이면 가입할 수 있고, 직전 3개 연도 중 한 번이라도 금융소득종합과세 대상이었다면 가입할 수 없습니다."]]},{"t":"③ 의무가입 3년","n":[["설명","의무 가입 기간은 3년이며, 3년이 지나야 세금 혜택을 받고 해지할 수 있습니다."]]}],"h":"한·만·의 → 한만의 → 한 계좌·만 19세·의무 3년"},{"t":"(2) ISA의 세금 혜택","c":[{"t":"① 순이익 200만(서민 400만) 비과세","n":[["설명","계좌 안에서 생긴 이익과 손실을 합친 순이익 중 200만 원(서민형·농어민형 400만 원)까지는 세금이 없습니다."]]},{"t":"② 초과분 9.9% 분리과세","n":[["설명","그 한도를 넘는 이익은 9.9%(지방세 포함)로 분리과세되어, 일반 계좌의 15.4%보다 낮습니다."]]},{"t":"③ 연 2,000만·총 1억, 이월","n":[["설명","납입 한도는 연 2,000만 원, 총 1억 원이며, 그해 못 채운 한도는 다음 해로 넘어갑니다(이월)."]]}],"h":"순·초·연 → 순초연 → 200만 비과세·초과 9.9%·연 2,000만"},{"t":"(3) 만기 후 연금계좌로 옮기기","c":[{"t":"① 60일 내 연금계좌 이전","n":[["설명","ISA 만기 자금을 60일 이내에 연금저축이나 IRP로 옮기면, 옮긴 금액의 10%(최대 300만 원)를 추가로 세액공제 대상 금액에 넣어 줍니다."]]},{"t":"② 3년마다 이전·재가입 반복","n":[["설명","그래서 많은 사람이 \"ISA 3년 → 만기 자금을 연금계좌로 이전 → 새 ISA 가입\"을 반복하는 전략을 씁니다."]]},{"t":"③ 절세+노후 동시 준비","n":[["설명","이 방법은 절세와 노후 준비를 동시에 할 수 있는 대표적인 방법입니다."],["따라 해 보기","ISA 일반형에서 3년 동안 순이익 500만 원이 났습니다. 일반 계좌였다면 세금은 얼마이고, ISA에서는 얼마일까요?\n\n결과 일반 계좌: 500만 원 × 15.4% = 77만 원. ISA: 200만 원까지 비과세, 나머지 300만 원 × 9.9% = 29만 7,000 원. 약 47만 원을 아낍니다. 게다가 ISA 안에서는 손실과 이익을 합산하므로 실제 절세 효과는 더 클 수 있습니다."]]}],"h":"6·3·절 → 6 3 절 → 60일 내 이전·3년마다·절세+노후"}],"h":"I·I·만 → I I 만 → ISA란·혜택·만기 후 연금 이전"},{"t":"2. 정부가 추진 중인 생산적금융 ISA","c":[{"t":"(1) 2026년 세제개편안의 내용","c":[{"t":"① 국내주식형 생산적금융 ISA","n":[["설명","정부는 2026년 8월 발표한 세제개편안에서 국내 주식·국내 주식형 펀드·국민성장펀드 등에 투자하는 생산적금융 ISA를 새로 만들겠다고 밝혔습니다."]]},{"t":"② 이자·배당 전액 비과세","n":[["설명","발표된 안에 따르면 계좌 안의 이자·배당소득이 전액 비과세이고, 연 2,000만 원, 총 2억 원까지 넣을 수 있으며, 만 34세 이하 등 청년형 가입자는 납입액의 10% 소득공제도 받을 수 있습니다."]]},{"t":"③ 일반 ISA 이월 폐지 제안","n":[["설명","기존 일반 ISA도 계약 기간을 3년(최대 5년까지 연장)으로 하고, 납입 한도 이월을 없애는 등의 변화가 함께 제안되었습니다."]]}],"h":"국·이·일 → 국이일 → 국내주식형 ISA·이자배당 비과세·일반 이월 폐지"},{"t":"(2) 아직 확정이 아니다","c":[{"t":"① 국회 심의 중, 2027년 시행","n":[["설명","이 내용은 2026년 11월 현재 국회 심의 중인 정부안이며, 법이 통과되면 2027년 1월 1일 이후 가입분부터 적용될 예정으로 알려져 있습니다."]]},{"t":"② 한도·대상 변경 가능","n":[["설명","국회 심의 과정에서 한도, 대상, 시행 시기가 바뀔 수 있습니다."]]},{"t":"③ 기존 ISA 활용 후 검토","n":[["설명","따라서 지금은 기존 ISA를 활용하면서, 연말 국회 통과 여부를 확인한 뒤 새 계좌를 검토하는 것이 안전합니다."],["실제 사례","2024~2025년에도 정부는 ISA 비과세 한도를 크게 올리겠다는 계획을 여러 번 발표했지만, 국회 논의 과정에서 내용이 바뀌거나 미뤄진 적이 있습니다. 그래서 \"발표\"와 \"시행\"을 구분하는 습관이 중요합니다. 뉴스에서 '신설', '확대'라는 말을 보면, 반드시 \"국회를 통과했는지, 언제부터인지\"를 확인하세요."]],"tb":[[["구분","현행 일반 ISA(2026.11)","생산적금융 ISA(정부안, 미확정)"],["투자 대상","예금·펀드·ETF·국내주식 등","국내 주식·국내 주식형 펀드·국민성장펀드 등"],["납입 한도","연 2,000만 원, 총 1억 원(이월 가능)","연 2,000만 원, 총 2억 원(이월 불가)"],["비과세","200만 원(서민형 400만 원), 초과분 9.9%","이자·배당소득 전액 비과세"],["추가 혜택","만기 시 연금 이전 10% 추가 공제","청년형 납입액 10% 소득공제 등"],["시행","시행 중","국회 통과 시 2027년 1월 이후 가입분"]]]}],"h":"국·한·기 → 국한기 → 국회 심의 중·한도 변경 가능·기존 ISA 먼저"}]}]},{"t":"Ⅲ 연금저축과 IRP — 노후와 절세를 한 번에","c":[{"t":"1. 세액공제의 원리","c":[{"t":"(1) 연말정산에서 돌려받는 돈","c":[{"t":"① 납입액 일부 세액공제","n":[["설명","연금저축과 IRP(개인형 퇴직연금)에 돈을 넣으면, 넣은 금액의 일정 비율을 연말정산 때 세금에서 빼 줍니다. 이것을 세액공제라고 합니다."]]},{"t":"② 연금저축 600·합산 900만","n":[["설명","세액공제 한도는 연금저축 연 600만 원, 연금저축과 IRP를 합쳐 연 900만 원입니다."]]},{"t":"③ 공제율 16.5% / 13.2%","n":[["설명","공제율은 총급여 5,500만 원 이하(종합소득 4,500만 원 이하)이면 16.5%, 그보다 많으면 13.2%입니다(지방세 포함)."]]}],"h":"납·연·공 → 납연공 → 납입액 공제·600/900·16.5%/13.2%"},{"t":"(2) 얼마나 돌려받나","c":[{"t":"① 총급여 5천: 148.5만 환급","n":[["설명","총급여 5,000만 원인 사람이 900만 원을 채우면 900만 원 × 16.5% = 148만 5,000원을 돌려받습니다."]]},{"t":"② 총급여 8천: 118.8만 환급","n":[["설명","총급여 8,000만 원인 사람이 900만 원을 채우면 900만 원 × 13.2% = 118만 8,000원을 돌려받습니다."]]},{"t":"③ 확정 수익 13.2~16.5% 효과","n":[["설명","이것은 투자하기도 전에 13.2~16.5%의 수익을 확정적으로 얻는 것과 비슷한 효과입니다. 다만 결정세액(낸 세금) 보다 많이 돌려받을 수는 없습니다."],["쉬운 예","문구점에서 공책을 사면 \"연말에 값의 16.5%를 돌려줄게\"라고 약속하는 것과 같습니다. 대신 그 공책은 할머니·할아버지가 될 때까지 아껴서 써야 한다는 조건이 붙어 있습니다."]],"tb":[[["총급여(종합소득)","공제율","900만 원 납입 시 환급액"],["5,500만 원 이하(4,500만 원 이하)","16.5%","148만 5,000원"],["5,500만 원 초과(4,500만 원 초과)","13.2%","118만 8,000원"]]]}],"h":"총·총·확 → 총총확 → 5천 이하 148.5만·8천 118.8만·확정 수익"}]},{"t":"2. 연금저축과 IRP의 차이와 활용 순서","c":[{"t":"(1) 두 계좌의 차이","c":[{"t":"① 연금저축: 자유 운용·인출","n":[["설명","연금저축은 펀드·ETF 등을 비교적 자유롭게 고를 수 있고, 일부 금액을 중간에 꺼내기(중도인출)도 상대적으로 쉽습니다(다만 세액공제받은 돈을 꺼내면 기타소득세 16.5%가 붙습니다)."]]},{"t":"② IRP: 위험자산 70% 한도","n":[["설명","IRP는 퇴직금을 받는 계좌이기도 하며, 위험 자산(주식형) 투자 한도가 70%로 제한되고, 중도인출은 무주택자 주택 구입, 6개월 이상 요양 등 법이 정한 사유가 있을 때만 가능합니다."]]},{"t":"③ 합산 납입 연 1,800만","n":[["설명","두 계좌를 합친 납입 한도는 연 1,800만 원(ISA 만기 이전분은 별도)이며, 세액공제는 그중 900만 원까지입니다."]]}],"h":"연·I·합 → 연I합 → 연금저축 자유·IRP 70%·합산 1,800"},{"t":"(2) 연금으로 받을 때의 세금","c":[{"t":"① 55세 이후 저율 연금소득세","n":[["설명","55세 이후, 가입 후 5년이 지나면 연금으로 받을 수 있습니다. 연금으로 받으면 나이에 따라 낮은 연금소득세가 붙습니다. 70세 미만 5.5%, 70~79세 4.4%, 80세 이상 3.3%입니다."]]},{"t":"② 사적연금 1,500만 초과 선택","n":[["설명","사적연금(연금저축·IRP의 세액공제분과 운용수익)으로 받는 금액이 연 1,500만 원을 넘으면, 종합과세와 16.5% 분리과세 중 하나를 고를 수 있습니다."]]},{"t":"③ 일시 수령 시 16.5% 과세","n":[["설명","연금이 아닌 한꺼번에 찾으면(연금 외 수령) 16.5%의 기타소득세가 붙어, 받은 세액공제 혜택이 대부분 사라집니다."]]}],"h":"5·사·일 → 5사일 → 55세 이후 저율·1,500만 초과·일시 16.5%"},{"t":"(3) 계좌를 채우는 추천 순서","c":[{"t":"① 비상금 먼저 마련","n":[["설명","첫째, 비상금을 먼저 마련합니다. 연금 계좌는 오래 묶이는 돈이므로 비상금으로 쓰면 안 됩니다."]]},{"t":"② 연금저축 600 + IRP 300","n":[["설명","둘째, 연금저축 600만 원 → IRP 300만 원으로 세액공제 한도 900만 원을 채우는 것을 검토합니다. 여유가 적으면 연금저축부터 시작합니다."]]},{"t":"③ 단기는 ISA, 노후는 연금","n":[["설명","셋째, 3~5년 안에 쓸 수도 있는 돈은 ISA에, 노후용 장기 자금은 연금 계좌에 넣습니다. 소득이 늘면 둘 다 채웁니다."],["핵심 포인트","직장인 절세 3종 세트: ① 연금저축(600만 원) ② IRP(300만 원 추가, 합산 900만 원) → 연말정산 최대 148만 5,000원 환급 ③ ISA(연 2,000만 원) → 비과세 + 만기 시 연금계좌 이전으로 추가 공제. 모두 \"오래 유지할 때\" 혜택이 커집니다."],["실제 사례","총급여 5,200만 원인 30대 J씨는 매달 연금저축 50만 원, IRP 25만 원을 자동이체해 연 900만 원을 채웠습니다. 연말정산에서 148만 5,000원을 돌려받았고, 이 환급금을 다시 ISA에 넣었습니다. 연금 계좌 안에서는 미국·한국 지수 ETF를 적립식으로 사고, ISA에서는 배당 ETF와 채권 ETF를 섞어 운용했습니다. 같은 돈을 일반 적금에 넣었을 때보다 세금에서만 매년 150만 원 가까이 차이가 납니다."]],"tb":[[["구분","연금저축","IRP","ISA(일반형)"],["핵심 혜택","세액공제(600만 원 한도)","세액공제(합산 900만 원 한도)","200만~400만 원 비과세 + 9.9% 분리과세"],["연간 납입 한도","연금저축+IRP 합산 1,800만 원","(왼쪽과 합산)","2,000만 원"],["중도 인출","가능(공제분은 16.5% 과세)","법정 사유만 가능","납입 원금 내 인출 가능"],["위험 자산 한도","제한 거의 없음(레버리지 등 일부 제외)","70%","제한 거의 없음"],["알맞은 돈","노후 자금","노후 자금 + 퇴직금","3~5년 중기 자금, 연금 이전용"]]]}],"h":"비·연·단 → 비연단 → 비상금 먼저·연금저축 600+IRP·단기는 ISA"}],"h":"두·연·계 → 두연계 → 두 계좌 차이·연금 세금·채우는 순서"}]}]},{"n":7,"t":"내 집 마련과 부동산 — 집값보다 총비용을 계산하라","c":[{"t":"Ⅰ 집을 사기 전에 계산해야 할 비용","c":[{"t":"1. 살 때 드는 비용","c":[{"t":"(1) 취득세","c":[{"t":"① 6억 이하 1%, 최대 3%","n":[["설명","집을 살 때 내는 첫 번째 세금이 취득세입니다. 1주택 기준으로 6억 원 이하는 1%, 6억 원 초과~9억 원 이하는 1~3%(금액에 따라 점점 올라감), 9억 원 초과는 3%입니다. 여기에 지방교육세 등이 더해지고, 전용면적 85㎡ 초과 주택은 농어촌특별세도 붙습니다."]]},{"t":"② 10억 아파트 ≈ 3,300만","n":[["설명","예를 들어 10억 원 아파트(85㎡ 이하)를 1주택자로 사면 취득세와 지방교육세를 합쳐 약 3,300만 원이 듭니다."]]},{"t":"③ 규제지역 2주택 8%·3주택 12%","n":[["설명","규제지역에서 두 번째 집을 사면 취득세율이 8%, 세 번째 이상은 12%까지 올라가므로 다주택 취득은 비용이 매우 큽니다."]]}],"h":"6·1·규 → 6 1 규 → 6억 이하 1%·10억 3,300만·규제지역 중과"},{"t":"(2) 중개수수료·등기비·대출 부대비용","c":[{"t":"① 중개수수료 0.5% 이내","n":[["설명","중개수수료는 거래 금액에 따라 상한 요율이 정해져 있으며, 9억 원 이상~12억 원 미만 주택 매매는 0.5% 이내입니다. 10억 원이면 최대 500만 원(부가세 별도)입니다."]]},{"t":"② 등기·채권·인지세 수백만","n":[["설명","법무사 등기 비용, 국민주택채권 매입 후 할인 비용, 대출 관련 인지세 등 수백만 원이 더 듭니다."]]},{"t":"③ 부대비용 집값의 4~5%","n":[["설명","그래서 집값 외에 취득 부대비용으로 집값의 4~5% 정도를 따로 준비하는 것이 안전합니다."],["따라 해 보기","10억 원 아파트(85㎡ 이하, 1주택)를 살 때 취득세·지방교육세 약 3,300만 원, 중개수수료 500만 원, 기타 비용 300만 원이 든다면 집값의 몇 %가 추가로 필요할까요?\n\n결과 3,300만 + 500만 + 300만 = 4,100만 원 → 집값의 약 4.1%입니다. 여기에 이사비와 인테리어 비용까지 더하면 5~7%까지 늘어날 수 있습니다."]]}],"h":"중·등·부 → 중등부 → 중개수수료·등기비·부대비용 4~5%"}]},{"t":"2. 사는 동안과 팔 때 드는 비용","c":[{"t":"(1) 보이지 않는 비용 — 기회비용","c":[{"t":"① 자기자본의 기회비용","n":[["설명","자기 돈 5억 원을 집에 넣으면, 그 돈을 다른 곳에 투자했을 때 얻었을 수익을 포기하게 됩니다. 이것을 기회비용이라고 합니다."]]},{"t":"② 5억 예금이면 연 1,500만","n":[["설명","5억 원을 연 3% 예금에만 넣어도 1년에 1,500만 원(세전)의 이자를 받을 수 있습니다. 집값이 그 이상 오르지 않으면 집을 산 것이 꼭 이득이라고 할 수 없습니다."]]},{"t":"③ 다섯 번째 비용, 흔히 누락","n":[["설명","첨부 자료는 이 기회비용을 \"다섯 번째 비용\"으로 꼽으며, 많은 사람이 이 비용을 아예 계산하지 않는다고 지적합니다."]]}],"h":"자·5·다 → 자5다 → 자기자본 기회비용·5억 예금 연 1,500·다섯 번째 비용"},{"t":"(2) 유지비와 세금","c":[{"t":"① 인테리어·관리비·보유세","n":[["설명","인테리어·입주 비용, 관리비와 반복 유지비, 재산세(매년 7월·9월), 공시가격이 높으면 종합부동산세가 듭니다."]]},{"t":"② 대출 이자·금리 위험","n":[["설명","대출이 있다면 매달 이자가 나가고, 금리가 오르면 부담이 커집니다."]]},{"t":"③ 양도세(12억 비과세)·이사비","n":[["설명","언젠가 팔 때는 양도소득세(1세대 1주택은 일정 요건을 갖추면 12억 원까지 비과세), 중개수수료, 이사비가 다시 듭니다."],["핵심 포인트","집의 진짜 가격 = 집값 + 취득 부대비용(4~5%) + 입주 비용 + 보유 기간의 이자·세금·관리비 + 자기 자본의 기회비용 + 팔 때의 비용. \"얼마짜리 집을 살 수 있나\"가 아니라 \"집을 사고도 비상금과 노후 저축을 계속할 수 있나\"를 물어야 합니다."]],"tb":[[["시점","비용 항목","메모"],["살 때","취득세·지방교육세, 중개수수료, 등기비, 대출 부대비용","집값의 4~5% 준비"],["입주할 때","인테리어, 이사비, 가전·가구","수천만 원이 되기도 함"],["사는 동안","대출이자, 관리비, 재산세·종부세, 수리비","매달·매년 반복"],["보이지 않는 비용","자기 자본의 기회비용","예금 금리만큼은 계산"],["팔 때","양도세(비과세 요건 확인), 중개수수료, 이사비","미리 계획"]]]}],"h":"인·대·양 → 인대양 → 인테리어 관리비·대출 이자·양도세"}]}]},{"t":"Ⅱ 자가 vs 월세 vs 투자 — 15년 뒤 누가 더 많이 남길까","c":[{"t":"1. 세 사람의 이야기","c":[{"t":"(1) 기본 설정","c":[{"t":"① 자가·월세·투자 세 사람 비교","n":[["설명","첨부 영상 「자가 vs 월세 vs 투자」는 같은 돈을 가진 세 사람을 비교합니다. 자가형은 대출을 받아 집을 사고, 월세형은 월세를 살며 남는 돈을 저축하고, 투자형은 월세를 살며 남는 돈을 꾸준히 주식 등에 투자합니다."]]},{"t":"② 정답은 하나가 아님","n":[["설명","결론은 \"정답은 하나가 아니다\"입니다. 결과를 바꾸는 변수가 여러 개이기 때문입니다."]]},{"t":"③ 변수를 알면 맞춤 선택","n":[["설명","다만 어떤 변수가 결과를 바꾸는지를 알면, 자기 상황에 맞는 선택을 할 수 있습니다."]]}],"h":"자·정·변 → 자정변 → 자가·월세·투자 세 사람·정답 없음·변수"},{"t":"(2) 결과를 바꾸는 네 가지 변수","c":[{"t":"① 월세 상승률","n":[["설명","월세 상승률: 월세가 빠르게 오르면 월세형과 투자형이 불리해집니다. 반대로 자가형이 고정금리 대출을 좋은 조건으로 받았다면 매달 나가는 돈을 예측하기 쉽습니다."]]},{"t":"② 투자 수익률(연 6~7%)","n":[["설명","투자 수익률: 투자형이 연 6~7% 이상을 꾸준히 낸다면 자가형을 앞설 수 있지만, 수익률이 낮거나 중간에 투자를 멈추면 뒤처집니다."]]},{"t":"③ 레버리지 방향","n":[["설명","레버리지: 자가형은 대출로 큰 자산을 갖기 때문에 집값이 오르면 크게 이기고, 떨어지면 크게 집니다."]]},{"t":"④ 집의 위치","n":[["설명","집의 위치: 같은 15년이라도 수요가 꾸준한 지역과 인구가 줄어드는 지역의 집값 흐름은 크게 다를 수 있습니다."],["쉬운 예","세 친구가 같은 용돈으로 각각 자전거를 할부로 사고, 자전거를 빌려 타고, 빌려 타면서 남은 돈을 저금했다고 생각해 보세요. 자전거 중고 값이 오르면 산 친구가 이기고, 저금 이자가 높으면 저금한 친구가 이깁니다. 누가 이길지는 자전거 값과 이자에 달려 있습니다."]]}],"h":"월·투·레·집 → 월투레집 → 월세 상승·투자 수익률·레버리지·집 위치"}]},{"t":"2. 각 선택의 숨은 위험","c":[{"t":"(1) 자가형의 위험","c":[{"t":"① 집값 하락·금리 상승 부담","n":[["설명","집값이 오르면 레버리지 덕분에 자기 자본 대비 수익이 커지지만, 집값이 떨어지거나 금리가 크게 오르면 부담이 커집니다."]]},{"t":"② 상환 부담에 저축 소홀","n":[["설명","대출을 갚느라 소비를 줄이면 생활 만족도가 떨어지고, 노후 저축을 놓칠 수도 있습니다. 첨부 자료의 \"네 번째 상황\" 이 이 경우입니다."]]},{"t":"③ 집 부자, 현금 가난","n":[["설명","자산 대부분이 집 한 채에 몰려 있으면 은퇴 후 \"집 부자, 현금 가난\"이 될 위험이 있습니다."]]}],"h":"집·상·집 → 집상집 → 집값 하락·상환 부담·집 부자 현금 가난"},{"t":"(2) 월세·투자형의 위험","c":[{"t":"① 월세형: 이사·월세 상승","n":[["설명","월세형은 이사가 잦고 월세 상승을 그대로 떠안습니다. 남는 돈을 저축하지 않고 써 버리면 15년 뒤 가장 적게 남을 수 있습니다."]]},{"t":"② 투자형: 꾸준함 가정 붕괴","n":[["설명","투자형은 \"꾸준히 투자한다\"는 가정이 깨지기 쉽습니다. 폭락장에서 팔거나, 중간에 돈을 다른 곳에 써 버리면 계획이 무너집니다."]]},{"t":"③ 높은 저축률·습관 필요","n":[["설명","즉, 투자형이 이기려면 높은 저축률과 흔들리지 않는 습관이 필요합니다."],["실제 사례","같은 해에 결혼한 K씨 부부와 L씨 부부가 있습니다. K씨 부부는 수도권 아파트를 대출 60%로 샀고, L씨 부부는 전세로 살며 매달 150만 원을 연금계좌와 ISA에 투자했습니다. 집값이 많이 오른 지역이라면 K씨가 앞서고, 그렇지 않은 지역이라면 L씨가 앞설 수 있습니다. 두 부부 모두 성공하는 길은 공통적이었습니다. 무리하지 않는 부채, 꾸준한 저축, 그리고 15년 동안 원칙을 바꾸지 않는 인내였습니다."]],"tb":[[["유형","유리한 상황","불리한 상황","꼭 필요한 습관"],["자가형","집값 상승, 고정금리 확보, 오래 거주","집값 하락, 금리 급등, 잦은 이사","대출 상환 계획, 비상금 유지"],["월세형","집값 정체·하락, 이동이 잦은 직업","월세 급등","남는 돈을 반드시 저축"],["투자형","투자 수익률이 꾸준히 높음","폭락장에서 매도, 투자 중단","자동이체 적립식, 분산"]]]}],"h":"월·투·높 → 월투높 → 월세형 이사·투자형 꾸준함·높은 저축률"}]}]},{"t":"Ⅲ 집값이 흔들릴 때와 2026년 대출 규제","c":[{"t":"1. 집값이 떨어질 때 현명한 사람들이 서두르지 않는 이유","c":[{"t":"(1) 가격보다 월 상환액과 실거래","c":[{"t":"① 집값보다 월 상환액","n":[["설명","첨부 영상 「집값이 떨어질 때 현명한 사람들은 무엇을 할까」는 첫 번째 이유로 \"집값보다 월 상환액을 먼저 보기 때문\" 을 꼽습니다. 집값이 10% 떨어져도 금리가 2%포인트 오르면 월 상환액은 오히려 늘 수 있습니다."]]},{"t":"② 호가 아닌 실거래가","n":[["설명","두 번째로 \"호가(집주인이 부르는 값)가 아니라 실제 거래 가격\"을 봅니다. 국토교통부 실거래가 공개시스템에서 실제 거래 가격을 확인할 수 있습니다."]]},{"t":"③ 기다리며 재무구조 강화","n":[["설명","하락기에 1년 더 기다리며 자기 자본을 늘리고 기존 빚을 줄인 가족은, 더 낮은 가격과 더 튼튼한 재무 구조를 동시에 가질 수도 있습니다."]]}],"h":"집·호·기 → 집호기 → 월 상환액·실거래가·기다리며 준비"},{"t":"(2) 내 집 마련과 투자를 분리한다","c":[{"t":"① 살 집 ≠ 오를 집","n":[["설명","현명한 사람들은 \"살 집\"과 \"가격이 오를 것 같은 집\"을 분리해서 생각합니다. 실거주 목적이라면 출퇴근, 학교, 생활환경이 먼저입니다."]]},{"t":"② 총비용으로 판단","n":[["설명","매입 가격만이 아니라 앞에서 본 총비용을 계산합니다."]]},{"t":"③ 산 뒤에도 비상금 유지","n":[["설명","마지막으로 가장 중요한 이유는 \"집을 사고도 비상금과 생활을 지킬 수 있는가\"입니다. 무리해서 산 집은 작은 충격에도 팔아야 하는 집이 됩니다."],["핵심 포인트","집 살 때 3가지 계산: ① 금리가 2%포인트 올라도 월 상환액을 감당할 수 있나 ② 실거래가 기준으로 적정한가 ③ 집을 사고도 비상금(최소 6개월치)과 노후 저축을 유지할 수 있나."]]}],"h":"살·총·산 → 살총산 → 살 집≠오를 집·총비용·산 뒤 비상금"}]},{"t":"2. 2026년 11월 현재 주택담보대출 규제","c":[{"t":"(1) 규제지역과 LTV","c":[{"t":"① 서울 전역·경기 12곳 규제","n":[["설명","서울 25개 구 전체와 경기도 12개 지역(과천, 광명, 수원 영통·장안·팔달, 성남 분당·수정·중원, 안양 동안, 용인 수지, 의왕, 하남)이 투기과열지구 등 규제지역으로 지정되어 있습니다(2025년 10·15 대책)."]]},{"t":"② LTV 40%, 생애최초 70%","n":[["설명","LTV(주택담보인정비율)는 집값 대비 대출 가능한 비율입니다. 규제지역에서 주택 구입 시 원칙은 40%이며, 생애 최초 구입자는 70%까지 가능합니다."]]},{"t":"③ 수도권 주담대 최대 6억","n":[["설명","수도권에서는 주택 구입 목적의 주택담보대출을 최대 6억 원으로 제한하는 규제(2025년 6·27 대책)도 시행 중입니다."]]}],"h":"서·L·수 → 서L수 → 서울 전역 규제·LTV 40%·수도권 6억"},{"t":"(2) 집값에 따른 대출 한도","c":[{"t":"① 15억↓ 6억·25억↓ 4억·초과 2억","n":[["설명","규제지역에서는 주택 가격에 따라 주택담보대출 한도가 따로 정해져 있습니다. 15억 원 이하 6억 원, 15억 원 초과~25억 원 이하 4억 원, 25억 원 초과 2억 원입니다."]]},{"t":"② DSR 40%·스트레스 DSR","n":[["설명","여기에 DSR 40%와 스트레스 DSR이 함께 적용되므로, 소득이 낮으면 이 한도까지도 받지 못할 수 있습니다."]]},{"t":"③ 대출 전 최신 규제 확인","n":[["설명","규제는 자주 바뀌므로 실제 대출 전에는 금융위원회 발표와 은행 상담으로 꼭 다시 확인해야 합니다."],["따라 해 보기","연소득 6,000만 원인 무주택자 M씨가 서울에서 9억 원 아파트를 생애 처음으로 사려 합니다. LTV 70%면 얼마, 한도 규제를 적용하면 얼마일까요? 대출금리 4.5%, 30년 원리금균등 상환이라면 월 상환액은 대략 얼마일까요?\n\n결과 LTV 70% = 6억 3,000만 원이지만 한도 6억 원이 상한입니다. 6억 원을 연 4.5%, 30년으로 빌리면 월 상환액은 약 304만 원, 1년이면 약 3,650만 원입니다. 이는 연소득의 약 61%로 DSR 40%(연 2,400만 원)를 크게 넘습니다. DSR 기준으로는 대출 가능액이 약 3억 9,000만 원 안팎으로 줄어들고(스트레스 금리를 더하면 더 줄어듦), 자기 돈이 5 억 원 이상 필요합니다."]],"tb":[[["규제지역 주택 가격","주택담보대출 최대 한도"],["15억 원 이하","6억 원"],["15억 원 초과 ~ 25억 원 이하","4억 원"],["25억 원 초과","2억 원"]]]}],"h":"1·D·대 → 1 D 대 → 15억↓ 6억·DSR 40%·대출 전 확인"}]}]}]},{"n":8,"t":"소득을 키우는 법 — 본업, 시간, 그리고 부업","c":[{"t":"Ⅰ 본업 소득을 키우는 전략","c":[{"t":"1. 나라는 자산에 투자하기","c":[{"t":"(1) 인적 자본이란","c":[{"t":"① 인적 자본 = 벌어올 능력","n":[["설명","인적 자본은 나의 지식, 기술, 경험, 건강, 인맥처럼 앞으로 돈을 벌어 올 능력을 말합니다. 젊은 사람에게는 이것이 가장 큰 자산입니다."]]},{"t":"② 연봉 10% = 1억 예금 효과","n":[["설명","연봉 4,000만 원을 받는 사람의 연봉이 10% 오르면 매년 400만 원이 늘어납니다. 이것은 연 4% 이자를 주는 1억 원짜리 예금을 하나 더 가진 것과 비슷한 효과입니다."]]},{"t":"③ 인상분 일부 자기 재투자","n":[["설명","그래서 첨부 자료는 월급이 오를 때 \"집과 차부터 업그레이드하지 않고, 자신의 소득 생산 능력에 일부를 다시 투자하라\"고 권합니다."]]}],"h":"인·연·인 → 인연인 → 벌어올 능력·연봉 10%=1억 예금·인상분 재투자"},{"t":"(2) 몸값을 높이는 방법","c":[{"t":"① 핵심 업무·성과 수치화","n":[["설명","회사가 꼭 필요로 하는 일(매출, 비용 절감, 위험 관리와 직결되는 일)을 맡아 성과를 숫자로 기록해 둡니다."]]},{"t":"② 이전 가능한 기술 습득","n":[["설명","업무와 관련된 자격증, 데이터 분석·AI 도구 활용 능력처럼 다른 회사에서도 인정받는 기술을 익힙니다."]]},{"t":"③ 2~3년마다 시장 연봉 확인","n":[["쉬운 예","사과나무를 키우는 농부가 사과를 더 많이 얻으려면 나무를 하나 더 사는 방법도 있지만, 지금 있는 나무에 거름을 주고 가지를 잘 다듬는 방법도 있습니다. 나 자신에게 하는 투자가 바로 거름입니다."],["설명","2~3년마다 같은 직무의 시장 연봉을 확인하고, 필요하면 이직이나 연봉 협상을 시도합니다. 한 회사에 오래 있는 것만으로는 연봉이 시장 수준을 따라가지 못하는 경우가 많습니다."]]}],"h":"핵·이·2 → 핵이2 → 핵심 업무 수치화·이전 가능 기술·2~3년마다 연봉 확인"}]},{"t":"2. 2026년 일자리 환경","c":[{"t":"(1) 최저임금과 소득의 바닥","c":[{"t":"① 2026 10,320원·2027 10,700원","n":[["설명","2026년 최저임금은 시간당 10,320원이고, 2027년 최저임금은 시간당 10,700원으로 결정되었습니다(고용노동부 고시)."]]},{"t":"② 2027 최저 월급 ≈ 223.6만","n":[["설명","주 40시간 근무(주휴 포함 월 209시간) 기준으로 2027년 최저임금 월급은 약 223만 6,000원입니다."]]},{"t":"③ 인건비 부담 → 무인 사업","n":[["설명","최저임금이 오르면 소상공인의 인건비 부담이 커지므로, 뒤에서 다룰 \"직원 없이 굴러가는 사업\"과 \"무인 사업\"에 대한 관심이 커지는 배경이 됩니다."]]}],"h":"2·2·인 → 2 2 인 → 2026 10,320원·2027 월급·인건비→무인화"},{"t":"(2) AI 시대에 귀해지는 일","c":[{"t":"① AI 활용자·대체 불가 일 가치↑","n":[["설명","AI가 문서 작성, 번역, 간단한 디자인 같은 일을 빠르게 대신하면서, \"AI를 잘 쓰는 사람\"과 \"AI가 대신하기 어려운 일을 하는 사람\"의 가치가 함께 올라가고 있습니다."]]},{"t":"② AI가 대신 못 하는 현장 사업","n":[["설명","첨부 영상 「AI가 대신하기 어려운 소자본 사업 15가지」는 배관·배수구 관리, 생활가전 청소, 고령자 주택 안전 개선, 병원 동행, 수선과 보관처럼 \"마지막 1m는 사람이 움직여야 하는 일\"을 예로 듭니다."]]},{"t":"③ 사무직 AI 활용·현장직 신뢰","n":[["핵심 포인트","20~30대에게 가장 수익률 높은 투자는 대개 \"나 자신\"입니다. 연봉 10% 상승은 1억 원짜리 예금 하나와 맞먹는 효과를 냅니다. 단, 자기계발 비용도 \"소득이 늘어날 것\"으로 연결되는지 따져 보고 씁니다."],["설명","사무직이라면 AI 도구를 업무에 적극적으로 활용해 생산성을 높이고, 현장직이라면 신뢰와 기술을 쌓아 단골을 만드는 것이 몸값을 지키는 방법입니다."]],"tb":[[["구분","2026년","2027년"],["최저임금(시간당)","10,320원","10,700원"],["월 환산(209시간)","약 215만 7,000원","약 223만 6,000원"]]]}],"h":"A·A·사 → A A 사 → AI 활용자·AI가 못 하는 현장·사무직은 AI 활용"}]}]},{"t":"Ⅱ 부자들은 왜 새 차보다 시간을 살까","c":[{"t":"1. 시간을 사는 소비","c":[{"t":"(1) 싫은 일이 아니라 가치 낮은 일을 맡긴다","c":[{"t":"① 가치 낮은 일을 돈으로","n":[["설명","첨부 영상 「부자들은 왜 새 차보다 시간을 사려고 할까」는 부자들이 \"가장 싫어하는 일을 무조건 돈으로 해결하지 않는다\"고 말합니다. 대신 \"내 시간의 가치보다 싸게 맡길 수 있는 일\"을 맡깁니다."]]},{"t":"② 시간당 가치보다 싸면 위임","n":[["설명","예를 들어 시간당 5만 원을 벌 수 있는 사람이 3시간 걸리는 대청소를 6만 원에 맡기고, 그 시간에 공부나 부업을 하면 이득입니다."]]},{"t":"③ 아낀 시간 낭비면 소비일 뿐","n":[["설명","반대로 그렇게 아낀 시간을 그냥 흘려보낸다면, 시간을 산 것이 아니라 돈을 쓴 것일 뿐입니다."]]}],"h":"가·시·아 → 가시아 → 가치 낮은 일 위임·시간가치보다 싸면·아낀 시간 낭비 X"},{"t":"(2) 출퇴근 시간과 전문가의 시간","c":[{"t":"① 출퇴근 1시간 = 연 240시간","n":[["설명","출퇴근이 하루 왕복 2시간인 사람이 직장 근처로 이사해 1시간을 줄이면, 1년에 약 240시간을 되찾습니다. 하루 8시간 근무로 치면 한 달치 근무시간에 해당합니다."]]},{"t":"② 전문가의 시간 구매","n":[["설명","부자들은 세무사, 변호사, 재무설계사 같은 전문가의 시간도 삽니다. 혼자 몇 주 걸릴 일을 몇 시간에 해결하고, 큰 실수를 막을 수 있기 때문입니다."]]},{"t":"③ 운동·수면·검진에 투자","n":[["쉬운 예","숙제를 하는 데 1시간이 걸리는데, 엄마가 빨래 개기를 대신 해 주면 그 시간에 숙제를 끝내고 좋아하는 책을 읽을 수 있습니다. 부자들이 돈을 내고 시간을 사는 것도 이와 같습니다. 중요한 것은 \"되찾은 시간에 무엇을 하느냐\"입니다."],["설명","건강을 위해 시간을 사는 것도 같은 맥락입니다. 운동, 수면, 건강검진에 쓰는 돈과 시간은 앞으로 일할 수 있는 기간을 늘려 줍니다."]]}],"h":"출·전·운 → 출전운 → 출퇴근 1시간·전문가 시간 구매·운동 수면"}]},{"t":"2. 시간의 값을 계산하기","c":[{"t":"(1) 내 시간당 가치","c":[{"t":"① 세후 소득 ÷ 근무시간","n":[["설명","세후 연 소득을 1년 근무 시간으로 나누면 대략적인 시간당 가치가 나옵니다. 세후 4,800만 원, 연 2,000시간 근무라면 시간당 2만 4,000원입니다."]]},{"t":"② 위임 비용 < 시간가치면 고려","n":[["설명","어떤 일을 맡기는 비용이 이 금액보다 싸고, 되찾은 시간을 더 가치 있게 쓸 수 있다면 맡기는 것을 고려합니다."]]},{"t":"③ 초년생은 저축 먼저","n":[["설명","다만 사회초년생은 시간당 가치보다 저축이 더 급할 수 있으므로, 비상금과 기본 저축을 먼저 채운 뒤에 시간을 사는 소비를 늘립니다."]]}],"h":"세·위·초 → 세위초 → 세후소득÷시간·위임 비용 비교·초년생은 저축 먼저"},{"t":"(2) 좋은 시간의 보호","c":[{"t":"① 집중 시간엔 중요한 일","n":[["설명","첨부 자료는 다섯 번째 차이로 \"좋은 시간의 보호\"를 듭니다. 가장 집중이 잘 되는 시간에는 중요한 일을 하고, 잡무는 다른 시간이나 다른 사람에게 맡깁니다."]]},{"t":"② 가족·휴식도 좋은 시간","n":[["설명","가족과 보내는 시간, 휴식 시간도 \"좋은 시간\"입니다. 이 시간을 지키는 것이 장기적으로 일의 성과와 건강을 지킵니다."]]},{"t":"③ 보이는 것보다 시간·건강·배움","n":[["따라 해 보기","세후 연 소득 6,000만 원, 연 2,000시간 근무하는 N씨가 매주 4시간 걸리는 집안일을 회당 6만 원에 맡기려 합니다. 시간당 가치 기준으로 이득일까요?\n\n결과 N씨의 시간당 가치는 6,000만 ÷ 2,000 = 3만 원입니다. 4시간의 가치는 12만 원인데 6만 원에 맡기므로 계산상 이득입니다. 단, 되찾은 4시간을 공부·부업·건강·가족 등 가치 있는 일에 써야 실제 이득이 됩니다."],["설명","결국 부자들의 소비 순서는 \"남에게 보이는 것\"보다 \"시간·건강·배움\"을 먼저 사는 쪽으로 기울어 있습니다."]]}],"h":"집·가·보 → 집가보 → 집중 시간·가족 휴식·보이는 것보다 건강"}]}]},{"t":"Ⅲ 퇴근 후 하루 2시간 부업","c":[{"t":"1. 좋은 부업의 조건","c":[{"t":"(1) 다섯 가지 기준","c":[{"t":"① 시작·종료 시간 분명한 일","n":[["설명","첨부 영상 「퇴근 후 하루 2시간으로 시작하는 현실적인 부업 15가지」는 좋은 부업의 조건으로 시작과 종료 시간이 분명할 것, 반복할수록 시간이 줄어들 것, 본업과 충돌하지 않을 것 등을 듭니다."]]},{"t":"② 반복할수록 시간 단축","n":[["설명","열 번째에도 정확히 두 시간이 걸리는 구조는 성장하기 어렵습니다. 같은 일을 반복할수록 템플릿과 요령이 생겨 시간이 줄어드는 부업이 좋습니다."]]},{"t":"③ 두 번째 현금흐름의 씨앗","n":[["설명","첫 목표는 회사를 당장 그만두는 것이 아니라 \"두 번째 현금흐름의 씨앗 하나\"를 만드는 것입니다."]]}],"h":"시·반·두 → 시반두 → 시간 분명·반복할수록 단축·두 번째 현금흐름"},{"t":"(2) 시작 전 확인할 것","c":[{"t":"① 겸업 금지 조항 확인","n":[["설명","회사 취업규칙에 겸업 금지 조항이 있는지 확인합니다. 공무원·공공기관 직원은 겸직 허가가 필요한 경우가 많습니다."]]},{"t":"② 부업 소득 종합소득세 신고","n":[["설명","부업 소득도 세금 신고 대상입니다. 사업소득이나 기타소득이 생기면 다음 해 5월 종합소득세 신고를 해야 할 수 있습니다."]]},{"t":"③ 초기 큰 지출 금지","n":[["핵심 포인트","좋은 부업 = ① 시작과 끝이 분명 ② 반복할수록 빨라짐 ③ 본업과 충돌 없음 ④ 초기 비용이 작음 ⑤ 단골·반복 고객이 생길 수 있음. \"얼마 버나\"보다 \"두 번째 고객이 오나\"가 먼저입니다."],["설명","처음부터 장비나 광고에 큰돈을 쓰지 않습니다. 첫 고객이 3만 원이라도 실제로 돈을 내는 문제를 찾는 것이 더 중요합니다."]]}],"h":"겸·부·초 → 겸부초 → 겸업 금지 확인·종합소득세·초기 큰 지출 X"}]},{"t":"2. 현실적인 부업 예시","c":[{"t":"(1) 디지털 기반 부업","c":[{"t":"① 동네 사업자 온라인 관리","n":[["설명","동네 사업자 온라인 관리: 네이버 플레이스, 지도 앱 정보, 리뷰 답변, 사진 업데이트를 대신 관리해 주고 매달 관리비를 받습니다."]]},{"t":"② 제품 촬영·짧은 영상","n":[["설명","소형 제품 촬영과 짧은 영상 제작: 작은 가게나 온라인 판매자의 제품 사진과 짧은 홍보 영상을 만들어 줍니다. 같은 구조를 반복하면 첫 영상에 두 시간 걸리던 일이 점점 짧아집니다."]]},{"t":"③ 디지털 템플릿 판매","n":[["설명","디지털 템플릿 판매: 특정 직업군(학원 강사, 소규모 사업자, 프리랜서)이 쓰는 문서·엑셀 양식을 만들어 온라인에서 판매합니다. 한 번 만들면 반복 판매가 가능합니다."]]}],"h":"동·제·디 → 동제디 → 동네 사업자 관리·제품 촬영·디지털 템플릿"},{"t":"(2) 현장 기반 부업","c":[{"t":"① 반려동물 산책·방문 돌봄","n":[["설명","반려동물 저녁 산책과 방문 돌봄: 퇴근 후 시간과 맞고, 같은 동네에서 고객을 모으면 이동 시간이 줄어듭니다. 첨부 자료는 \"첫 번째 적은 경쟁자가 아니라 이동 시간\"이라고 강조합니다."]]},{"t":"② 시니어 스마트폰 지원","n":[["설명","시니어 스마트폰 생활 지원: 부모님 세대의 스마트폰 설정, 은행 앱, 병원 예약, 사기 문자 구별 등을 도와주는 일입니다."]]},{"t":"③ 중고물품 판매 대행","n":[["실제 사례","회사원 O씨는 퇴근 후 동네 미용실 세 곳의 플레이스 정보와 사진, 리뷰 답변을 월 10만 원씩 관리해 주는 일로 부업을 시작했습니다. 첫 달에는 가게 하나에 6시간이 걸렸지만, 체크리스트를 만들자 석 달 뒤에는 2시간으로 줄었습니다. 1년 뒤 고객이 12곳으로 늘어 월 120만 원의 반복 수입이 생겼고, O씨는 이 돈 전부를 ISA에 자동이체했습니다. 부업 소득은 다음 해 5월 종합소득세로 신고했습니다."],["설명","중고물품 판매 대행: 바빠서 중고 거래를 못 하는 사람들의 물건을 대신 촬영·등록·판매하고 수수료를 받습니다."]],"tb":[[["부업","초기 비용","반복 수익 가능성","주의할 점"],["사업자 온라인 관리","매우 낮음","높음(월 관리비)","성과를 숫자로 보여 줘야 함"],["제품 촬영·짧은 영상","낮음(스마트폰·조명)","중간","포트폴리오 먼저"],["디지털 템플릿","매우 낮음","중간~높음","저작권, 차별화"],["반려동물 돌봄","낮음","높음(매주 반복)","안전·보험, 신뢰"],["시니어 스마트폰 지원","매우 낮음","중간","개인정보 보호"],["중고물품 판매 대행","낮음","중간","거래 분쟁 대비"]]]}],"h":"반·시·중 → 반시중 → 반려동물·시니어 폰·중고 대행"}]}]}]},{"n":9,"t":"작은 현금흐름을 여러 개 — 반복 수익 사업의 원리","c":[{"t":"Ⅰ 월 300만 원 하나보다 월 30만 원 열 개","c":[{"t":"1. 분산된 현금흐름의 힘","c":[{"t":"(1) 한 번의 실패가 전부를 0으로 만들지 않는다","c":[{"t":"① 300만 고객 하나 이탈 = 0","n":[["설명","첨부 영상 「월 300만 원보다 월 30만 원을 10개 만드는 사람이 부자가 되는 이유」는 첫 번째 이유로 이것을 꼽습니다. 월 300만 원을 주던 유일한 소득원이 사라지면 수입은 곧바로 0이 됩니다."]]},{"t":"② 30만×10은 270만으로 감소","n":[["설명","반면 월 30만 원짜리 고객이 10명인 사람은 고객 한 명이 떠나도 300만 원이 270만 원으로 줄어들 뿐입니다."]]},{"t":"③ 소득에 적용한 분산","n":[["설명","이것은 투자에서 배운 \"분산\"을 소득에 적용한 것입니다."]]}],"h":"3·3·소 → 3 3 소 → 300만 하나 이탈·30만×10·소득 분산"},{"t":"(2) 작은 현금흐름은 복제할 수 있다","c":[{"t":"① 작은 현금흐름은 복제 가능","n":[["설명","좋은 작은 현금흐름은 복제가 가능합니다. 한 고객에게 통한 방법을 두 번째, 세 번째 고객에게 그대로 적용할 수 있습니다."]]},{"t":"② 증거 → 복제 → 시스템","n":[["설명","첨부 자료는 \"첫 번째 30만 원은 돈이 아니라 증거이고, 두 번째 30만 원은 복제 가능성이며, 세 번째부터 시스템이 시작된다\"고 표현합니다."]]},{"t":"③ 두 번째 고객이 더 쉬운가","n":[["쉬운 예","큰 물통 하나에 물을 받는 것보다 작은 물통 열 개에 나누어 받으면, 물통 하나가 깨져도 나머지 아홉 개의 물은 그대로 남습니다. 게다가 작은 물통은 하나를 만들어 보면 똑같이 여러 개를 만들기 쉽습니다."],["설명","그래서 중요한 질문은 \"얼마나 많이 버나\"가 아니라 \"두 번째 고객을 만들 때 처음보다 얼마나 쉬워지는가\"입니다."]]}],"h":"작·증·두 → 작증두 → 작은 흐름 복제·증거→복제→시스템·두 번째 고객"}]},{"t":"2. 작은 현금흐름이 자산이 되는 과정","c":[{"t":"(1) 예측 가능성과 실험","c":[{"t":"① 다음 달 수입 예측 가능","n":[["설명","매달 반복되는 작은 수입이 여러 개 있으면 다음 달 수입을 예측하기 쉬워집니다. 예측이 쉬우면 저축과 투자 계획도 세우기 쉽습니다."]]},{"t":"② 작은 실험의 반복","n":[["설명","실패 비용을 작게 유지하면서 새로운 수익원을 시험할 수 있습니다. 사업이 \"모든 것을 걸고 맞혀야 하는 선택\"에서 \" 작은 실험을 반복하는 과정\"으로 바뀝니다."]]},{"t":"③ 수입원 성격 다변화","n":[["설명","수입의 성격을 다르게 만들 수도 있습니다. 예를 들어 개인 고객 수입, 사업자 고객 수입, 디지털 판매 수입처럼 서로 다른 곳에서 들어오면 한 분야의 불황이 전체에 미치는 영향이 줄어듭니다."]]}],"h":"다·작·수 → 다작수 → 다음 달 예측·작은 실험·수입원 다변화"},{"t":"(2) 현금흐름을 자산으로 바꾸기","c":[{"t":"① 남는 돈으로 금융자산 매수","n":[["설명","작은 현금흐름에서 남는 돈을 배당 ETF, 채권, 연금 계좌 같은 금융 자산을 사는 데 쓰면, 그 자산이 다시 배당과 이자라는 현금흐름을 만듭니다."]]},{"t":"② 노동 → 자산 → 자산소득","n":[["설명","이렇게 \"일해서 번 돈 → 자산 → 자산이 버는 돈\"으로 이어지는 고리가 생기면, 시간이 지날수록 일하지 않아도 들어오는 돈의 비중이 커집니다."]]},{"t":"③ 수익원 많을수록 선택권","n":[["핵심 포인트","반복 수익의 3단계: ① 첫 고객 = 이 문제에 돈을 내는 사람이 있다는 \"증거\" ② 두 번째 고객 = 같은 방법이 또 통한다는 \"복제 가능성\" ③ 세 번째부터 = 체크리스트·템플릿으로 만드는 \"시스템\". 단, 소득원이 많아질수록 관리 부담도 커지므로 시스템화가 필수입니다."],["설명","마지막으로 수익원이 여러 개 있으면 선택권이 늘어납니다. 본업에서 원치 않는 일이 생겨도 다른 길을 선택할 수 있습니다."]],"tb":[[["구조","월 300만 원 소득원 1개","월 30만 원 소득원 10개"],["하나가 사라지면","수입 0원","수입 270만 원"],["확장 방법","몸값을 크게 올려야 함","같은 방식을 복제"],["실험 비용","큼(바꾸기 어려움)","작음(하나씩 시험)"],["관리 부담","낮음","높음(시스템화 필요)"]]]}],"h":"남·노·수 → 남노수 → 남는 돈 자산 매수·노동→자산·수익원↑ 선택권↑"}]}]},{"t":"Ⅱ 사람들이 매달 다시 돈을 내는 사업","c":[{"t":"1. 반복 결제가 생기는 세 가지 이유","c":[{"t":"(1) 소모, 재발, 생활의 반복","c":[{"t":"① 소모되는 것","n":[["설명","첨부 영상 「매달 다시 돈을 내는 고객이 생기는 12가지 사업」은 반복 결제가 생기는 이유를 세 가지로 정리합니다. 첫째, 소모된다(휴지·포장재처럼 쓰면 없어진다)."]]},{"t":"② 다시 더러워지는 것","n":[["설명","둘째, 다시 더러워지거나 다시 문제가 생긴다(에어컨 필터, 배수구, 자동차 실내)."]]},{"t":"③ 반복되는 생활","n":[["설명","셋째, 생활이 반복된다(매주 먹는 반찬, 매일 하는 반려동물 산책, 매달 하는 장보기)."]]}],"h":"소·다·반 → 소다반 → 소모·다시 더러워짐·반복 생활"},{"t":"(2) 귀찮음이 반복 수익이 된다","c":[{"t":"① 불편함 = 반복 수익 구조","n":[["설명","첨부 영상 「사람들이 귀찮아서 계속 돈을 내는 사업 12가지」는 \"불편함이 반복 수익이 되는 구조\"를 설명합니다. 사람들은 귀찮은 일을 한 번 맡기기 시작하면 계속 맡기는 경향이 있습니다."]]},{"t":"② 산책·반찬·정리·운영대행","n":[["설명","반려동물 산책과 방문 돌봄, 정기 반찬, 이사 전후 정리 수납, 소상공인 온라인 운영 대행 등이 대표적입니다."]]},{"t":"③ 재구매가 성패 결정","n":[["쉬운 예","우유 배달을 생각해 보세요. 우유는 마시면 없어지고(소모), 매일 아침 또 마시고 싶어지며(생활의 반복), 직접 사러 가기는 귀찮습니다. 그래서 한 번 배달을 시작한 집은 몇 년씩 계속 받습니다."],["설명","이런 사업은 \"두 번째로 돈을 내는가, 세 번째에도 내는가\"가 성패를 가릅니다."]]}],"h":"불·산·재 → 불산재 → 불편함=수익·산책 반찬 정리·재구매"}]},{"t":"2. 반복 수익 사업 예시","c":[{"t":"(1) 개인 고객 대상","c":[{"t":"① 생활가전 주기 관리","n":[["설명","생활가전 주기적 관리: 에어컨·세탁기·건조기 청소를 해 주고, 마지막 청소일을 기록해 다음 시즌 전에 예약 안내를 보내면 기존 고객이 다시 돌아옵니다."]]},{"t":"② 정기 반찬·소량 식사","n":[["설명","정기 반찬·생활형 식사: 1인 가구와 고령 가구가 늘면서 소량·정기 식사 수요가 커지고 있습니다. 식품 위생 관련 신고·허가가 필요합니다."]]},{"t":"③ 반려동물 정기 돌봄","n":[["설명","반려동물 정기 돌봄과 산책: 매주 반복되는 수요이며, 같은 동네에 고객을 모을수록 효율이 높아집니다."]]}],"h":"생·정·반 → 생정반 → 생활가전·정기 반찬·반려동물"},{"t":"(2) 사업자 고객 대상(B2B)","c":[{"t":"① 소상공인 온라인 정보 관리","n":[["설명","소규모 사업자 온라인 정보 정기 관리: 지도 앱 정보, 리뷰, 사진, 소식 업데이트를 매달 관리합니다."]]},{"t":"② B2B 소모품 정기 공급","n":[["설명","B2B 소모품 정기 공급: 작은 식당·사무실·학원에 위생용품, 포장재, 사무용품을 정기적으로 공급합니다. 첨부 자료가 \"불황에도 손님이 끊기지 않는 사업\"의 마지막 열두 번째로 꼽은 사업입니다."]]},{"t":"③ 사업장 방역·위생 관리","n":[["실제 사례","에어컨 청소 기사 P씨는 첫해에 고객 200명의 주소, 모델명, 청소일을 엑셀로 기록했습니다. 다음 해 5월 초에 \"작년 이맘때 청소한 에어컨, 올해도 점검하실 때가 되었어요\"라는 문자를 보내자 140명이 다시 예약했습니다. 광고비 없이 첫해 매출의 70%가 확보된 것입니다. P씨는 여기에 세탁기·건조기 청소를 묶은 \"연 2회 정기 관리 회원\"을 만들어 매출을 계절에 덜 흔들리게 했습니다."],["설명","사업장 방역·위생 관리: 음식점 등은 위생 관리가 필수이므로 경기와 관계없이 수요가 이어집니다. 관련 업종 신고 요건을 확인해야 합니다."]],"tb":[[["반복 이유","사업 예시","고객","매출 주기"],["소모","B2B 소모품 정기 공급, 정기 반찬","사업자, 가정","매주~매달"],["재발","생활가전 청소, 배수구·배관 관리, 방역","가정, 사업자","계절·분기"],["생활의 반복","반려동물 산책, 장보기 대행","가정","매일~매주"],["귀찮음","온라인 운영 대행, 정리 수납","소상공인, 가정","매달"]]]}],"h":"소·B·사 → 소B사 → 소상공인 관리·B2B 소모품·사업장 방역"}]}]},{"t":"Ⅲ 가게 없이, 직원 없이, 기계로 시작하는 사업","c":[{"t":"1. 고정비를 낮추는 창업","c":[{"t":"(1) 가게 없이 시작하는 생활밀착형 사업","c":[{"t":"① 출장형 생활밀착 사업","n":[["설명","첨부 영상 「가게 없이도 시작할 수 있는 15가지 생활밀착형 사업」은 출장형 소형 집수리·가구 조립, 생활가전 청소, 정리 수납, 병원 동행과 비의료 생활 지원, 중고 물품 판매 대행, 출장형 차량 실내 관리 등을 소개합니다."]]},{"t":"② 지역 밀도가 핵심","n":[["설명","이런 사업의 핵심은 지역 밀도입니다. 출장형 사업에서 가장 비싼 비용은 이동 시간이므로, 좁은 지역에 고객을 촘촘하게 모아야 합니다."]]},{"t":"③ 차량·장비 등 고정비 잔존","n":[["설명","가게를 없앴다고 안심하면 안 됩니다. 차량 유지비, 장비 할부, 앱 수수료, 보험료 같은 고정비가 여전히 남아 있습니다."]]}],"h":"출·지·차 → 출지차 → 출장형·지역 밀도·차량 고정비"},{"t":"(2) 직원 없이 굴러가는 1인 사업","c":[{"t":"① 직원 없는 1인 사업 유형","n":[["설명","첨부 영상 「직원 없이도 굴러가는 현실적인 1인 사업 12가지」는 소규모 사업자 온라인 운영 지원, 출장형 소형 수리, 범위를 좁힌 생활가전 방문 관리, 특정 직업군용 디지털 문서·템플릿 판매, 제품 촬영, 반려동물 방문 돌봄, 시니어 디지털 생활 지원, 니치형 멤버십 정보 서비스 등을 꼽습니다."]]},{"t":"② 저고정비 vs 쉬면 매출 0","n":[["설명","1인 사업의 장점은 인건비가 없어 고정비가 낮다는 것이고, 단점은 내가 아프거나 쉬면 매출도 멈춘다는 것입니다."]]},{"t":"③ 나 없이 도는 시스템 확대","n":[["핵심 포인트","소자본 창업의 3대 원칙: ① 큰 매장·큰 장비를 먼저 계약하지 않는다(고정비 최소화) ② 좁은 지역에 고객을 모은다(이동 시간 최소화) ③ 두 번째 매출이 어디서 오는지 처음부터 설계한다(반복 수요)."],["설명","그래서 1인 사업일수록 체크리스트, 예약 시스템, 자동 결제처럼 \"내가 없어도 돌아가는 부분\"을 조금씩 늘려야 합니다."]]}],"h":"직·저·나 → 직저나 → 직원 없이·저고정비·나 없이 도는 시스템"}]},{"t":"2. 작은 공간과 무인 기계","c":[{"t":"(1) 작은 공간 하나로 시작하는 사업","c":[{"t":"① 작업실형 소공간 사업","n":[["설명","첨부 영상 「작은 공간 하나로 시작해 현금흐름을 만드는 사업 10가지」는 니치형 온라인 판매 작업실, 주문형 스티커·라벨 소형 인쇄 작업실, 소형 제품 촬영실, 중고 제품 검수·촬영·리셀 작업실, 소형 장비 대여, 예약형 마이크로 스튜디오, B2B 샘플 키트 조립·소량 포장 작업실 등을 예로 듭니다."]]},{"t":"② 공간 회전율이 수익 좌우","n":[["설명","이런 사업은 공간의 회전율(같은 공간을 하루에 몇 번 돈이 되게 쓰는가)이 수익을 좌우합니다."]]},{"t":"③ 재구매 여부가 핵심","n":[["설명","핵심 질문은 역시 \"두 번째, 세 번째로 다시 돈을 내는가\"입니다."]]}],"h":"작·공·재 → 작공재 → 작업실·공간 회전율·재구매"},{"t":"(2) 한 번 설치하면 반복 수익이 생기는 기계","c":[{"t":"① 자판기·무인 출력 기계","n":[["설명","첨부 영상 「한 번 설치하면 반복 수익이 생기는 작은 기계 사업 10가지」는 캡슐토이·소형 굿즈 자판기, 음료·간식·생활용품 소형 자판기, 무인 출력·복사·스캔 키오스크, 증명사진 포토키오스크, 보조배터리 대여 스테이션, 스마트 보관함, 소형 디지털 사이니지, 사업장용 정수기·제빙기 렌털 관리, 전기차 완속 충전기 등을 소개합니다."]]},{"t":"② 장소 계약·관리·고장 대응","n":[["설명","기계 사업에서 꼭 따질 것은 장소 계약(매출이 낮아도 월세가 똑같이 나가면 위험), 관리 시간(일주일에 한 번 방문으로 충분한가), 고장 대응(고객은 고장 난 기계를 기다려 주지 않음)입니다."]]},{"t":"③ 무인 = 무노동이란 오해","n":[["따라 해 보기","소형 자판기 1대를 400만 원에 사서, 월 매출 120만 원, 원가 60만 원, 장소 사용료 20만 원, 전기·관리비 10만 원이 든다고 합시다. 월 순이익과 투자금 회수 기간은 얼마일까요?\n\n결과 월 순이익 = 120만 − 60만 − 20만 − 10만 = 30만 원. 400만 ÷ 30만 ≈ 13.3개월이면 기계값을 회수합니다. 단, 내 관리 시간(월 몇 시간)과 고장 수리비, 세금은 아직 빠져 있으므로 실제 회수 기간은 더 길어질 수 있습니다. 매출이 80 만 원으로 줄면 순이익은 월 0원 안팎이 됩니다."],["설명","첨부 자료가 바로잡는 가장 큰 오해는 \"무인 사업은 일하지 않아도 돈이 들어온다\"는 생각입니다. 실제로는 보충, 청소, 정산, 고장 처리, 장소 관리가 계속 필요합니다."]],"tb":[[["사업 형태","초기 비용","고정비","핵심 성공 요인","대표 위험"],["출장형 생활 서비스","낮음","차량·장비","지역 밀도, 단골","이동 시간, 몸 상태"],["1인 온라인 대행","매우 낮음","매우 낮음","성과 증명, 시스템화","고객 이탈"],["작은 작업실","중간","월세","공간 회전율","월세 부담"],["무인 기계","중간~높음","장소 임대료","장소 선정, 관리","고장, 낮은 유동인구"]]]}],"h":"자·장·무 → 자장무 → 자판기·장소 계약 관리·무인≠무노동"}]},{"t":"3. 불황에도 사라지지 않는 지루한 사업","c":[{"t":"(1) 동네에서 계속 필요한 일","c":[{"t":"① 배관·수선 등 동네 사업","n":[["설명","첨부 영상 「한국에서 사라지지 않을 동네 사업 15가지」와 「불황에도 손님이 끊기지 않는 12가지 '지루한' 사업」은 공통적으로 생활 배관·배수구 관리, 출장형 소형 집수리, 자동차 경정비와 소모품 관리, 정기 청소와 정리, 반찬·도시락, 스마트폰·디지털 기기 수리, 열쇠·도어락·출입 보안 관리, 신발·가방·가구 수선, 이사 전후 청소와 폐기물 정리 등을 꼽습니다."]]},{"t":"② 고장·오염은 경기 무관","n":[["설명","이 사업들은 화려하지 않지만, 경기가 나빠도 \"고장 나면 고쳐야 하고, 더러워지면 치워야 하는\" 생활의 필요에서 나옵니다."]]},{"t":"③ 불황엔 수리 수요 증가","n":[["설명","불황기에는 사람들이 새 물건을 사는 대신 고쳐 쓰기 때문에, 수선·수리 수요가 오히려 늘 수 있습니다."]]}],"h":"배·고·불 → 배고불 → 배관 수선·고장 오염 경기 무관·불황 수리↑"},{"t":"(2) 지루한 사업의 성공 조건","c":[{"t":"① 기술과 신뢰가 경쟁력","n":[["설명","기술과 신뢰가 가장 큰 경쟁력입니다. 한 번 믿을 만한 기사를 찾은 고객은 쉽게 바꾸지 않습니다."]]},{"t":"② 자격증·등록·배상보험","n":[["설명","관련 자격증, 사업자 등록, 배상책임보험 등 기본 요건을 갖추어 신뢰를 높입니다."]]},{"t":"③ 리뷰·입소문 마케팅","n":[["설명","지역 커뮤니티, 지도 앱 리뷰, 아파트 단지 게시판 등을 통해 입소문을 쌓는 것이 광고보다 효과적인 경우가 많습니다."]]}],"h":"기·자·리 → 기자리 → 기술 신뢰·자격 보험·리뷰"},{"t":"(3) 창업 전 체크리스트","c":[{"t":"① 경쟁자 가격·리뷰 조사","n":[["설명","같은 지역에서 이미 이 일을 하는 사람이 있는지, 그들의 가격과 리뷰는 어떤지 조사합니다."]]},{"t":"② 6개월 생활비 확보","n":[["설명","처음 6개월 동안 매출이 거의 없어도 생활할 수 있는 자금(비상금)이 있는지 확인합니다. 창업 자금을 빚으로만 마련하면 앞서 본 \"검증되지 않은 창업에 빚을 지는 위험\"에 빠집니다."]]},{"t":"③ 소상공인 지원사업 활용","n":[["핵심 포인트","지루한 사업이 강한 이유: \"고장 나면 고쳐야 하고, 더러워지면 치워야 하고, 배고프면 먹어야 한다.\" 유행이 아니라 생활의 필요에서 나오는 수요는 불황에도 잘 사라지지 않습니다."],["설명","정부·지자체의 소상공인 창업 교육과 지원 사업(소상공인시장진흥공단 등)을 확인하면 비용과 시행착오를 줄일 수 있습니다."]]}],"h":"경·6·소 → 경6소 → 경쟁자 조사·6개월 생활비·소상공인 지원"}],"h":"동·지·창 → 동지창 → 동네 일·지루한 사업 조건·창업 체크"}],"h":"고·작·불 → 고작불 → 고정비 낮게·작은 공간 기계·불황에도"}]},{"n":10,"t":"인구가 바뀌면 돈의 길도 바뀐다 — 고령화와 새로운 기회","c":[{"t":"Ⅰ 인구 변화가 만드는 세 가지 흐름","c":[{"t":"1. 고령화와 가족 구조의 변화","c":[{"t":"(1) 더 많은 노인, 더 적은 자녀","c":[{"t":"① 베이비붐 세대 65세 진입","n":[["설명","고령 인구는 일시적인 유행이 아니라 앞으로 수십 년 동안 꾸준히 늘어납니다. 베이비붐 세대(1955~1974년생 전후) 가 차례로 65세를 넘기 때문입니다."]]},{"t":"② 자녀 몫 일을 외부에 위탁","n":[["설명","과거에는 부모님 근처에 사는 자녀가 자연스럽게 처리했던 일(전구 교체, 병원 동행, 장보기, 스마트폰 설정)을, 앞으로는 돈을 내고 외부 서비스에 맡기는 경우가 늘어날 수 있습니다."]]},{"t":"③ 고령 1인 가구 급증","n":[["설명","고령자 1인 가구도 빠르게 늘고 있어, 혼자 사는 노인의 안전과 생활을 돕는 서비스 수요가 커집니다."]]}],"h":"베·자·고 → 베자고 → 베이비붐 65세·자녀 몫 외주·고령 1인 가구"},{"t":"(2) 지역 인구 감소와 빈집","c":[{"t":"① 지방 인구 감소·빈집 증가","n":[["설명","수도권과 대도시로 인구가 몰리면서 지방 중소도시와 농어촌은 인구가 줄고, 빈집이 늘고 있습니다."]]},{"t":"② 빈집 관리·지역 컨시어지","n":[["설명","첨부 영상 「사람이 줄어들수록 더 필요해지는 10가지 사업」은 빈집 점검과 유지 관리, 인구 감소 지역의 생활 서비스를 묶는 지역 컨시어지 같은 사업을 소개합니다."]]},{"t":"③ 사라진 동네 서비스 대체","n":[["쉬운 예","학교 운동장에 아이들이 줄어들면 축구공을 파는 가게는 장사가 어려워지지만, 운동장 벤치를 고치고 그늘막을 설치해 주는 일은 오히려 늘어날 수 있습니다. 인구가 바뀌면 필요한 것도 바뀝니다."],["설명","인구가 줄면 동네 가게와 서비스가 하나씩 사라지는데, 그 빈자리를 채우는 사업이 새로운 기회가 될 수 있습니다."]]}],"h":"지·빈·사 → 지빈사 → 지방 인구↓·빈집 관리·사라진 서비스 대체"}]},{"t":"2. 일손 부족과 외국인 근로자","c":[{"t":"(1) 줄어드는 일하는 사람","c":[{"t":"① 생산연령인구 감소","n":[["설명","생산연령인구(15~64세)가 줄면서 많은 업종에서 일손이 부족해지고 있습니다. 고령화 사업은 수요가 커지는 동시에 서비스를 제공할 젊은 인력이 줄어드는 문제를 함께 안고 있습니다."]]},{"t":"② 인력 절감 자동화·운영대행","n":[["설명","그래서 소상공인을 위한 인력 절감 자동화(키오스크, 예약·결제 자동화)와 운영 대행 수요가 늘어납니다."]]},{"t":"③ 50~60대 은퇴 후 일자리","n":[["설명","50~60대가 은퇴 후 이 분야에서 일하는 것도 현실적인 선택지가 됩니다. 사람이 해야 하는 일의 가치가 높아지기 때문입니다."]]}],"h":"생·인·5 → 생인5 → 생산인구↓·인력 절감·50~60대 은퇴 후 일"},{"t":"(2) 외국인 근로자 생활 정착 지원","c":[{"t":"① 외국인 근로자 정착 지원","n":[["설명","첨부 영상 「앞으로 5년, 한국에서 돈이 몰릴 가능성이 높은 10가지 '평범한' 사업」은 외국인 근로자 생활 정착 지원을 아홉 번째 기회로 꼽습니다."]]},{"t":"② 주거·통신·계좌·병원 안내","n":[["설명","주거 구하기, 휴대폰 개통, 은행 계좌, 병원 이용, 생활 정보 안내 등 정착 과정에서 도움이 필요한 일이 많습니다."]]},{"t":"③ 출입국·고용 법령 준수","n":[["핵심 포인트","인구 변화 사업을 볼 때 확인할 숫자: ① 고객 밀도(근처에 고객이 충분한가) ② 누가 실제로 돈을 내는가(노부모인가, 자녀인가, 지자체인가) ③ 반복 수요가 있는가 ④ 신뢰를 얻는 데 드는 비용 ⑤ 일할 사람을 구할 수 있는가."],["설명","다만 출입국·고용 관련 법령을 반드시 지켜야 하고, 행정사 등 자격이 필요한 업무는 전문가와 협력해야 합니다."]],"tb":[[["인구 변화","생기는 문제","사업 기회 예시"],["고령 인구 증가","집안일·이동·디지털이 어려움","주택 안전 개선, 병원 동행, 디지털 생활 지원"],["고령 1인 가구 증가","안전·식사·외로움","안부 확인, 소량 식사, 생활 코디네이터"],["지방 인구 감소","빈집, 서비스 공백","빈집 관리, 지역 컨시어지"],["일손 부족","소상공인 인력난","자동화·운영 대행, 외국인 정착 지원"]]]}],"h":"외·주·출 → 외주출 → 외국인 정착·주거 통신 계좌·출입국 법령"}]}]},{"t":"Ⅱ 고령화 시대의 유망 사업","c":[{"t":"1. 집과 몸의 안전","c":[{"t":"(1) 고령자 주택 안전 개선","c":[{"t":"① 손잡이·미끄럼 방지·문턱 제거","n":[["설명","첨부 영상 여러 편이 공통으로 첫 번째 기회로 꼽은 것이 고령자 주택 안전 개선입니다. 화장실 안전 손잡이, 미끄럼 방지 시공, 문턱 제거, 밝은 조명, 높이 조절 가구 등이 해당합니다."]]},{"t":"② 낙상 예방에 자녀가 지출","n":[["설명","노인의 낙상 사고는 큰 부상과 의료비로 이어지므로, 자녀 세대가 부모님 집을 위해 돈을 쓰는 경우가 많습니다."]]},{"t":"③ 지자체 주거개선 연계","n":[["설명","지자체의 주거 개선 지원 사업과 연계하면 고객을 찾기 쉬워질 수 있습니다."]]}],"h":"손·낙·지 → 손낙지 → 손잡이 문턱·낙상 예방·지자체 연계"},{"t":"(2) 운동과 낙상 예방","c":[{"t":"① 중장년 근력·낙상 예방","n":[["설명","중장년층의 근력 운동, 신체 기능 유지, 낙상 예방 프로그램 수요가 커지고 있습니다."]]},{"t":"② 60대 증가 유망 시장","n":[["설명","첨부 영상 「앞으로 10년, 60대가 늘어날수록 돈이 몰리는 12가지 시장」은 이를 세 번째 시장으로 꼽습니다."]]},{"t":"③ 노인스포츠지도사 등 자격","n":[["실제 사례","은퇴한 전기기사 Q씨(62세)는 자신의 기술을 살려 \"부모님 집 안전 점검 패키지\"를 만들었습니다. 2시간 방문으로 콘센트·조명·화장실 손잡이·문턱을 점검하고 필요한 시공을 해 주는 서비스입니다. 주 고객은 멀리 사는 자녀들이었고, 점검 결과를 사진과 함께 자녀에게 보내 주는 것이 신뢰를 높였습니다. 1년에 한 번 재점검 예약을 받아 반복 매출도 생겼습니다."],["설명","관련 자격(생활스포츠지도사, 노인스포츠지도사 등)을 갖추면 신뢰를 얻기 쉽습니다."]]}],"h":"중·6·노 → 중6노 → 중장년 근력·60대 시장·노인스포츠지도사"}]},{"t":"2. 일상과 디지털 지원","c":[{"t":"(1) 병원 동행과 생활 동행","c":[{"t":"① 접수·진료·약 수령 동행","n":[["설명","병원 동행 서비스는 혼자 병원에 가기 어려운 노인을 모시고 접수, 진료 동행, 약 수령, 귀가까지 돕는 서비스입니다. 의료 행위가 아닌 생활 지원입니다."]]},{"t":"② 자녀 휴가 부담 대체","n":[["설명","자녀가 직장 때문에 매번 휴가를 낼 수 없는 경우가 많아, 앞으로 수요가 커질 것으로 보는 시각이 많습니다."]]},{"t":"③ 신원확인·보험·기록 공유","n":[["설명","신뢰가 가장 중요하므로 신원 확인, 배상책임보험, 동행 기록 공유 같은 장치를 갖추어야 합니다."]]}],"h":"접·자·신 → 접자신 → 접수 진료 약 동행·자녀 휴가 대체·신원 보험 기록"},{"t":"(2) 시니어 디지털 생활 지원","c":[{"t":"① 앱·예약·키오스크 장벽","n":[["설명","은행 앱, 병원 예약, 키오스크 주문, 사기 문자 구별 같은 디지털 생활이 노인에게는 큰 벽입니다."]]},{"t":"② 배우려는 노인은 많음","n":[["설명","첨부 자료는 \"고령자는 디지털을 못 한다\"는 생각을 착각으로 꼽습니다. 배우고 싶어 하는 노인이 많고, 친절하게 반복해서 가르쳐 줄 사람이 부족할 뿐입니다."]]},{"t":"③ 방문·강의·원격 지원","n":[["설명","일대일 방문 교육, 복지관 강의, 가족이 신청하는 원격 지원 등 다양한 형태가 가능합니다."]]}],"h":"앱·배·방 → 앱배방 → 앱 키오스크 장벽·배우려는 노인·방문 원격 지원"},{"t":"(3) 식사, 장보기, 이동","c":[{"t":"① 소량 맞춤 식사·정기 반찬","n":[["설명","고령 가구를 위한 소량 맞춤 식사, 정기 반찬 배달은 매주 반복되는 수요입니다."]]},{"t":"② 장보기·심부름·이동 지원","n":[["설명","장보기와 생활 심부름을 묶은 근거리 서비스, 고령자 이동 지원 서비스도 함께 성장할 수 있습니다."]]},{"t":"③ 위생·운송 법령 확인","n":[["따라 해 보기","병원 동행 서비스를 1회 4시간 6만 원에 제공한다고 합시다. 한 달에 고객 15명이 각각 2회씩 이용하면 월 매출과 시간당 매출은 얼마일까요? 이동 시간이 회당 1시간 더 든다면 어떻게 될까요?\n\n결과 월 30회 × 6만 원 = 180만 원, 서비스 시간 120시간 → 시간당 1만 5,000원. 이동 시간 30시간을 더하면 150시간 → 시간당 1만 2,000원으로 줄어듭니다. 이동 시간을 줄이려면 고객을 한 지역에 모으고, 같은 병원에 가는 고객의 일정을 묶는 것이 중요합니다."],["설명","식품은 위생 관련 신고·허가, 이동 지원은 운송 관련 법령을 반드시 확인해야 합니다."]],"tb":[[["서비스","실제로 돈을 내는 사람","반복성","필요한 신뢰 장치"],["주택 안전 개선","자녀, 본인, 지자체","연 1회 점검","시공 보증, 자격"],["병원 동행","자녀","월 1~4회","신원 확인, 보험, 기록 공유"],["디지털 생활 지원","본인, 자녀, 복지관","수시","개인정보 보호"],["소량 식사·반찬","본인, 자녀","매주","위생 허가, 영양 정보"],["안부 확인","자녀, 지자체","매일~매주","비상 연락 체계"]]]}],"h":"소·장·위 → 소장위 → 소량 식사·장보기 심부름·위생 운송 법령"}],"h":"병·시·식 → 병시식 → 병원 동행·디지털 지원·식사 장보기 이동"}]},{"t":"Ⅲ 고령화 시장의 함정과 연결 사업","c":[{"t":"1. 고령화 사업의 세 가지 착각","c":[{"t":"(1) 착각을 피하는 법","c":[{"t":"① 시장 크기보다 고객 밀도","n":[["설명","첫 번째 착각은 \"시장이 커지면 누구나 돈을 번다\"는 생각입니다. 시장 규모보다 중요한 것은 우리 동네의 고객 밀도입니다."]]},{"t":"② 고령자 디지털 불가는 착각","n":[["설명","두 번째 착각은 \"고령자는 디지털을 못 한다\"는 생각입니다. 많은 60대는 이미 스마트폰으로 송금하고 영상을 봅니다. 서비스 설계를 단순하고 친절하게 하면 됩니다."]]},{"t":"③ 요양만이 고령화 산업 아님","n":[["설명","세 번째 착각은 \"요양 산업만이 고령화 산업\"이라는 생각입니다. 실제로는 식사, 집수리, 운동, 취미, 평생교육, 자산 관리, 주거 전환까지 생활 전반이 고령화 시장입니다."]]}],"h":"시·고·요 → 시고요 → 시장보다 밀도·디지털 불가는 착각·요양만이 아님"},{"t":"(2) 은퇴 이후의 새로운 소비","c":[{"t":"① 취미·자산관리·주거 전환","n":[["설명","첨부 자료는 은퇴 이후의 취미와 평생교육, 은퇴 후 자산 관리와 생활비 설계 지원, 집을 줄이고 생활을 정리하는 주거 전환 지원, 고령 반려동물 보호자를 위한 생활 지원 등을 성장 시장으로 꼽습니다."]]},{"t":"② 다운사이징 연계 서비스","n":[["설명","특히 다운사이징(큰 집에서 작은 집으로 옮기며 물건을 정리하고 처분하는 일)은 정리 수납, 중고 판매, 이사, 유품 정리까지 여러 서비스가 연결됩니다."]]},{"t":"③ 존중하는 태도가 핵심","n":[["쉬운 예","할머니가 큰 집에서 작은 아파트로 이사할 때는 물건 정리, 버릴 것 처리, 쓸 만한 물건 팔기, 이사, 새 집 안전 점검까지 할 일이 줄줄이 생깁니다. 이 모든 일을 하나씩 다른 사람에게 맡기기는 힘들기 때문에, 한 번에 연결해 주는 사람이 필요합니다."],["설명","이런 서비스는 감정적으로 민감한 일이 많으므로, 존중하는 태도와 꼼꼼한 설명이 기술만큼 중요합니다."]]}],"h":"취·다·존 → 취다존 → 취미 자산관리·다운사이징·존중하는 태도"}]},{"t":"2. 모든 서비스를 잇는 생활 코디네이터","c":[{"t":"(1) 연결 사업의 가치","c":[{"t":"① 고령자 문제는 한꺼번에","n":[["설명","첨부 영상 대부분은 마지막(열 번째 또는 열두 번째) 기회로 여러 서비스를 하나로 묶어 연결하는 사업을 꼽습니다. 고령자의 문제는 하나씩 생기지 않고 한꺼번에 생기기 때문입니다."]]},{"t":"② 코디네이터·지역 컨시어지","n":[["설명","고령자 생활 코디네이터, 지역 생활 컨시어지는 수리·청소·식사·동행·디지털 지원 등을 직접 다 하지 않아도, 믿을 만한 업체를 연결하고 일정을 관리해 수수료나 월 회비를 받는 구조입니다."]]},{"t":"③ 핵심 자산은 신뢰·네트워크","n":[["설명","이 사업의 핵심 자산은 장비가 아니라 신뢰와 네트워크입니다."]]}],"h":"고·코·핵 → 고코핵 → 문제는 한꺼번에·코디네이터·신뢰 네트워크"},{"t":"(2) 은퇴자에게 맞는 일자리","c":[{"t":"① 고령화 시대 은퇴자 일자리","n":[["설명","첨부 영상 「50대라면 퇴직 전에 알아두세요! 고령화 시대 유망한 10가지 현실적인 일자리」는 방문 생활 관리, 시니어 생활 정리·주거 전환 지원, 시니어 운동 지도, 고령 반려동물 보호자 지원, 안부 확인·생활 안전 지원, 고령 친화 생활 서비스 코디네이터 등을 소개합니다."]]},{"t":"② 동세대 공감이 강점","n":[["설명","50~60대는 같은 세대의 마음을 잘 이해한다는 강점이 있어, 고령 고객의 신뢰를 얻기 쉽습니다."]]},{"t":"③ 퇴직 전 자격·작은 시험","n":[["핵심 포인트","고령화 시대의 기회는 \"거대한 산업\"이 아니라 \"매일 반복되는 작은 불편\"에 있습니다. 성공 조건은 ① 고객 밀도 ② 실제 지불자 파악 ③ 반복 수요 ④ 신뢰 장치(보험·자격·기록) ⑤ 일할 사람 확보입니다."],["설명","퇴직 전에 관련 자격을 따고, 주말에 작게 시험해 보며 경험을 쌓으면 퇴직 후 소득 공백을 줄일 수 있습니다."]],"tb":[[["고령화 사업 준비 단계","할 일"],["퇴직 5년 전","관심 분야 정하기, 관련 자격증 공부"],["퇴직 3년 전","주말에 봉사·아르바이트로 현장 경험"],["퇴직 1년 전","작은 고객 몇 명으로 유료 서비스 시험"],["퇴직 직후","사업자 등록, 보험, 지역 네트워크 구축"]]]}],"h":"고·동·퇴 → 고동퇴 → 은퇴자 일자리·동세대 공감·퇴직 전 시험"}]}]}]},{"n":11,"t":"노후 현금흐름 설계 — 월급이 끊긴 뒤에도 돈이 들어오게","c":[{"t":"Ⅰ 노후 현금흐름의 층 쌓기","c":[{"t":"1. 3층 연금 + 추가 층","c":[{"t":"(1) 바닥층 — 국민연금","c":[{"t":"① 물가연동 평생 현금흐름","n":[["설명","국민연금의 핵심은 높은 수익률이 아니라 평생 동안 물가에 맞춰 오르는 현금흐름의 바닥을 만들어 준다는 것입니다."]]},{"t":"② 매년 물가만큼 인상","n":[["설명","국민연금은 매년 전년도 물가 상승률만큼 연금액을 올려 주므로, 오래 살수록 가치가 커집니다."]]},{"t":"③ 65세 수령, 조기 −6%/년","n":[["설명","1969년생 이후는 만 65세부터 받을 수 있으며, 최대 5년 앞당겨 받으면 1년에 6%씩 깎이고, 최대 5년 늦춰 받으면"]]}],"h":"물·매·6 → 물매6 → 물가연동 평생·매년 인상·65세, 조기 감액"},{"t":"(2) 2층과 3층 — 퇴직연금과 개인연금","c":[{"t":"① 퇴직연금 DB·DC·IRP","n":[["설명","퇴직연금은 회사가 쌓아 주는 연금입니다. 확정급여형(DB)은 받을 금액이 정해져 있고, 확정기여형(DC)과 IRP는 내"]]},{"t":"② 개인연금 + 세액공제","n":[["설명","개인연금(연금저축, IRP 추가 납입)은 제6절에서 본 세액공제 혜택과 함께 스스로 쌓는 연금입니다."]]},{"t":"③ 막연한 믿음은 위험 신호","n":[["설명","첨부 자료는 \"국민연금과 퇴직연금을 막연하게 믿는 것\"을 50대 이후 돈이 새는 사람의 특징으로 꼽습니다. 두 연금"]]}],"h":"퇴·개·막 → 퇴개막 → 퇴직연금·개인연금·막연한 믿음 위험"},{"t":"(3) 추가 층 — 금융 자산, 주택연금, 작은 사업","c":[{"t":"① 예금·채권: 생활비 안정","n":[["설명","예금과 채권형 자산은 돈을 크게 불리기보다 생활비를 안정시키고, 주식 같은 위험 자산이 회복할 시간을 벌어 줍니"]]},{"t":"② 배당주: 현금흐름+성장","n":[["설명","분산된 배당 주식은 배당이라는 현금흐름과 함께 물가 상승을 이길 성장 가능성을 줍니다."]]},{"t":"③ 주택연금·작은 사업","n":[["쉬운 예","노후 현금흐름은 여러 층으로 쌓은 케이크와 같습니다. 맨 아래 국민연금은 케이크의 받침 빵이고, 퇴직연금과 개인연금은 크림 층, 금융 자산과 주택연금은 과일 층입니다. 한 층만 있으면 금방 무너지지만, 여러 층이 있으면 튼튼하고 맛있습니다."],["설명","주택연금은 이미 가진 집을 현금흐름으로 바꿉니다. 여기에 반복 매출이 있는 작은 사업, 저작권·디지털 콘텐츠 같은"]],"tb":[[["층","자산","역할","특징"],["1층","국민연금","평생 바닥 소득","물가 연동, 종신 지급"],["2층","퇴직연금(DB·DC·IRP)","직장 생활의 결실","운용 방식 확인 필수"],["3층","개인연금(연금저축·IRP)","부족분 보충","세액공제, 낮은 연금소득세"],["4층","예금·채권·배당주","생활비 안정 + 성장","인출 순서 설계"],["5층","주택연금","집을 현금흐름으로","평생 거주 + 종신 지급"],["6층","작은 사업·지식 자산","일하는 즐거움 + 소득","건강·시간 필요"]]]}],"h":"예·배·주 → 예배주 → 예금채권·배당주·주택연금"}],"h":"바·2·추 → 바2추 → 바닥 국민연금·2·3층 퇴직·개인·추가 층"},{"t":"2. 노후에 필요한 돈 계산하기","c":[{"t":"(1) 얼마가 필요할까","c":[{"t":"① 현재 생활비 70% 기준","n":[["설명","노후 생활비는 사람마다 크게 다르지만, 먼저 \"지금 생활비의 70% 정도\"를 출발점으로 계산해 보는 방법이 많이 쓰입니다. 자녀 교육비와 대출 상환이 끝나면 지출이 줄어들기 때문입니다."]]},{"t":"② 의료·여가비는 증가","n":[["설명","다만 의료비와 여가비는 오히려 늘 수 있으므로, 건강보험·실손보험 상태와 원하는 생활 수준을 함께 따져야 합니다."]]},{"t":"③ 내 연금 조회 후 부족분","n":[["설명","부부의 예상 국민연금과 퇴직연금을 국민연금공단 \"내 연금 알아보기\"와 금융감독원 \"통합연금포털\"에서 확인한 뒤, 부족한 금액을 계산합니다."]]}],"h":"현·의·내 → 현의내 → 현재 생활비 70%·의료 여가↑·내 연금 조회"},{"t":"(2) 부족분을 자산으로 바꾸어 보기","c":[{"t":"① 예: 월 300 − 연금 210 = 90","n":[["설명","예를 들어 부부 노후 생활비가 월 300만 원이고, 국민연금 부부 합산 160만 원, 퇴직연금에서 월 50만 원을 받는다면 부족분은 월 90만 원입니다."]]},{"t":"② 4% 인출 시 약 2.7억","n":[["설명","월 90만 원(연 1,080만 원)을 금융 자산에서 꺼내 쓰려면, 흔히 쓰는 \"연 4% 인출\" 가정에서 약 2억 7,000만 원이 필요합니다(1,080만 ÷ 0.04)."]]},{"t":"③ 3~3.5%로 보수적 계산","n":[["따라 해 보기","은퇴 후 월 생활비 280만 원, 예상 국민연금(부부 합산) 150만 원, 퇴직연금 월 40만 원인 R씨 부부가 있습니다. 부족분과, 연 3.5% 인출 기준으로 필요한 금융 자산은 얼마일까요?\n\n결과 부족분 = 280만 − 150만 − 40만 = 월 90만 원(연 1,080만 원). 필요한 금융 자산 = 1,080만 ÷ 0.035 ≈ 3억 860만 원. 주택연금이나 작은 사업 소득으로 월 30만 원만 보태도 필요한 금융 자산은 약 2억 원대로 크게 줄어듭니다."],["설명","이 \"4% 규칙\"은 미국 자료를 바탕으로 한 참고 기준일 뿐, 수익률·물가·수명에 따라 결과가 달라지므로 3~3.5%처럼 보수적으로 잡는 사람도 많습니다."]]}],"h":"예·4·3 → 예 4 3 → 월 300 예시·4% 인출·3~3.5% 보수적"}]}]},{"t":"Ⅱ 2026년부터 달라진 국민연금과 연금 활용","c":[{"t":"1. 국민연금 개혁의 내용","c":[{"t":"(1) 더 내고 조금 더 받는다","c":[{"t":"① 보험료 9→13%, 대체율 43%","n":[["설명","2025년 3월 국회는 국민연금 보험료율을 9%에서 13%로 올리고, 소득대체율을 43%로 정하는 개혁안에 합의했습니다. 보험료율은 2026년 9.5%를 시작으로 해마다 0.5%포인트씩 올라 2033년 13%가 됩니다."]]},{"t":"② 대체율 = 평균소득 대비 연금","n":[["설명","소득대체율은 \"평균 소득 대비 연금으로 받는 비율\"입니다. 2026년부터 43%가 적용되어, 개혁 전보다 앞으로 쌓이는 가입 기간에 대해 조금 더 받게 됩니다."]]},{"t":"③ 직장인 본인 4.75%(2026)","n":[["설명","직장인은 보험료의 절반을 회사가 내므로, 2026년 근로자 본인 부담은 소득의 4.75%입니다."]]}],"h":"보·대·직 → 보대직 → 보험료 9→13%·대체율·직장인 4.75%"},{"t":"(2) 크레딧과 지급 보장","c":[{"t":"① 출산·군복무 크레딧 확대","n":[["설명","출산 크레딧이 첫째 아이부터 12개월 인정되고(셋째 이상은 18개월), 군복무 크레딧은 최대 12개월로 늘었습니다. 크레딧은 보험료를 내지 않았어도 가입 기간으로 인정해 주는 제도입니다."]]},{"t":"② 저소득 지역가입자 지원","n":[["설명","저소득 지역가입자의 보험료 지원이 확대되었습니다."]]},{"t":"③ 국가 지급보장 명문화","n":[["핵심 포인트","2026년 국민연금: 보험료율 9.5%(2033년 13%까지 매년 0.5%p↑), 소득대체율 43%, 출산 크레딧 첫째부터, 군복무 크레딧 최대 12개월, 국가 지급 보장 명시. 가입 기간이 길수록 유리하므로 공백 기간에는 추후납부·임의 가입을 검토합니다."],["설명","국가가 연금 지급을 보장한다는 내용이 법에 명시되었습니다. \"국민연금이 고갈되면 못 받는다\"는 걱정에 대해, 국가의 지급 책임을 법으로 분명히 한 것입니다."]],"tb":[[["연도","국민연금 보험료율","직장인 본인 부담"],["2025","9.0%","4.5%"],["2026","9.5%","4.75%"],["2027","10.0%","5.0%"],["2028","10.5%","5.25%"],["2029~2032","매년 0.5%p 인상","—"],["2033","13.0%","6.5%"]]]}],"h":"출·저·국 → 출저국 → 출산 군복무 크레딧·저소득 지원·국가 지급보장"}]},{"t":"2. 국민연금 더 받는 방법","c":[{"t":"(1) 가입 기간 늘리기","c":[{"t":"① 추후납부로 기간 채우기","n":[["설명","국민연금은 가입 기간이 길수록 받는 돈이 많아집니다. 실직·육아 등으로 보험료를 못 낸 기간이 있다면 추후납부로 나중에 채울 수 있습니다."]]},{"t":"② 전업주부 임의가입","n":[["설명","소득이 없는 전업주부도 임의가입으로 가입 기간을 쌓을 수 있습니다."]]},{"t":"③ 60세 이후 임의계속가입","n":[["설명","60세 이후에도 임의계속가입으로 65세 전까지 가입 기간을 늘릴 수 있습니다."]]}],"h":"추·전·6 → 추전6 → 추후납부·전업주부 임의가입·60세 이후 계속가입"},{"t":"(2) 받는 시기 정하기","c":[{"t":"① 연기연금 연 7.2% 증액","n":[["설명","건강하고 다른 소득이 있다면 연기연금(최대 5년, 1년당 7.2% 증액)을 고려할 수 있습니다."]]},{"t":"② 조기수령은 평생 감액","n":[["설명","반대로 건강이 좋지 않거나 당장 생활비가 부족하다면 조기 수령이 나을 수도 있지만, 평생 감액된 금액을 받는다는 점을 기억해야 합니다."]]},{"t":"③ 소득 많으면 감액 규정","n":[["실제 사례","1970년생 S씨는 30대에 3년간 실직하며 국민연금을 내지 못했습니다. 55세에 추후납부 제도를 알고 그 기간의 보험료를 나누어 냈더니, 예상 연금액이 매달 수만 원 늘었습니다. 65세부터 30년을 받는다고 가정하면, 늘어난 연금 총액이 낸 보험료보다 훨씬 많아질 수 있었습니다. 국민연금은 물가에 연동되므로 실제 가치는 더 큽니다."],["설명","다른 소득이 많으면 연금이 감액될 수 있는 규정도 있으므로, 국민연금공단 상담을 통해 자신에게 맞는 시기를 정합니다."]]}],"h":"연·조·소 → 연조소 → 연기 7.2%↑·조기 평생 감액·소득 많으면 감액"}]},{"t":"3. 퇴직연금과 주택연금","c":[{"t":"(1) 퇴직연금 운용 점검","c":[{"t":"① 운용 방식 모르면 위험 신호","n":[["설명","첨부 자료는 \"퇴직연금이 얼마 있는지는 알지만 어떻게 운용되고 있는지는 모르는 것\"을 여덟 번째 위험 신호로 꼽습니다."]]},{"t":"② 원리금보장만이면 물가 열위","n":[["설명","DC형·IRP 적립금이 수년째 원리금보장 상품(예금 등)에만 있다면, 물가를 이기지 못할 수 있습니다. 나이와 성향에 맞게 TDF(은퇴 시점에 맞춰 자산 비중을 자동 조절하는 펀드)나 지수 ETF를 섞는 것을 검토합니다."]]},{"t":"③ 디폴트옵션 설정","n":[["설명","2023년 7월부터 시행된 디폴트옵션(사전지정운용제도)을 설정해 두면, 만기 후 방치되는 적립금이 미리 정한 상품으로 자동 운용됩니다."]]}],"h":"운·원·디 → 운원디 → 운용 방식 확인·원리금보장만이면 손해·디폴트옵션"},{"t":"(2) 주택연금","c":[{"t":"① 집에 살며 평생 연금","n":[["설명","주택연금은 집을 담보로 맡기고 그 집에 계속 살면서 평생 매달 연금을 받는 제도입니다(한국주택금융공사 운영)."]]},{"t":"② 55세 이상·공시 12억 이하","n":[["설명","부부 중 한 명이 만 55세 이상이고, 공시가격 12억 원 이하 주택(다주택자는 합산 기준)을 가진 경우 가입할 수 있습니다."]]},{"t":"③ 사망 후 정산, 부족분 미청구","n":[["핵심 포인트","노후 점검 3가지: ① 국민연금 예상액(내 연금 알아보기) ② 퇴직연금 운용 상태(통합연금포털, 디폴트옵션) ③ 집을 현금흐름으로 바꿀 계획(주택연금 또는 다운사이징)."],["설명","부부가 모두 사망하면 집을 처분해 정산하고, 집값이 연금 총액보다 많으면 남은 돈은 상속인에게 돌아가고, 부족해도 상속인에게 청구하지 않습니다."]],"tb":[[["구분","퇴직연금(DC·IRP)","주택연금"],["운영","금융회사(내가 운용 지시)","한국주택금융공사"],["핵심 점검","운용 상품, 수익률, 디폴트옵션","가입 나이·주택 가격·월 지급액"],["장점","세금 혜택, 연금 수령 시 저율 과세","평생 거주 + 종신 지급"],["주의","방치 시 물가에 뒤처짐","가입 시점 집값·나이에 따라 금액 결정"]]]}],"h":"집·5·사 → 집5사 → 집에 살며 연금·55세 12억·사망 후 정산"}]}],"h":"국·국·퇴 → 국국퇴 → 개혁 내용·더 받는 법·퇴직·주택연금"},{"t":"Ⅲ 노후 위험 신호와 돈이 모이는 사람의 습관","c":[{"t":"1. 40대부터 보이는 위험 신호","c":[{"t":"(1) 저축과 금융 자산의 신호","c":[{"t":"① 월급 올라도 저축 정체","n":[["설명","첨부 영상 「노후에 돈이 부족해지는 사람들은 40대부터 이것을 놓칩니다」의 첫 번째 신호는 \"월급은 올랐는데 저축액이 거의 늘지 않는 것\"입니다."]]},{"t":"② 노후 준비를 뒤로 미룸","n":[["설명","두 번째 신호는 \"노후 자금을 큰일이 끝난 다음에 모으겠다고 미루는 것\"입니다. \"아이 대학 보내고 시작하자\"라고 미루면 노후 준비는 늘 마지막 순서가 됩니다. 40세에 시작한 사람과 50세에 시작한 사람은 10년의 적립과 운용 기간 차이가 납니다."]]},{"t":"③ 순자산↑·금융자산 정체","n":[["설명","네 번째 신호는 \"순자산은 늘어나는데 쓸 수 있는 금융 자산은 거의 늘지 않는 것\"입니다. 집값만 오르고 현금흐름 자산이 없으면 노후에 생활비가 부족해집니다."]]}],"h":"월·노·순 → 월노순 → 월급↑ 저축 정체·노후 미룸·금융자산 정체"},{"t":"(2) 지출과 계획의 신호","c":[{"t":"① 자녀 지원 무한·노후는 한도","n":[["설명","여섯 번째 신호는 \"자녀에게 지원할 돈에는 한도가 없는데, 자신의 노후 자금에는 한도가 있는 것\"입니다. 자녀 학원비·결혼 비용 때문에 부모의 노후 자금이 바닥나면, 결국 자녀에게 부담이 돌아갈 수 있습니다."]]},{"t":"② 고정비 증가·65세 근로 맹신","n":[["설명","일곱 번째 신호는 \"50대가 가까워져도 고정비가 계속 늘어나는 것\"이고, 아홉 번째 신호는 \"65세까지 일할 것을 계획이 아니라 사실처럼 믿는 것\"입니다."]]},{"t":"③ 조기 퇴직을 전제로 계획","n":[["쉬운 예","여름 내내 노래만 부르던 베짱이는 겨울이 되어서야 먹을 것이 없다는 것을 알았습니다. 개미가 여름에 일한 것은 여름이 길어서가 아니라, 겨울이 반드시 온다는 것을 알았기 때문입니다. 40대는 노후라는 겨울을 준비하는 늦여름입니다."],["설명","실제로는 건강, 회사 사정, 업종 변화 때문에 예상보다 일찍 일을 그만두는 경우가 적지 않습니다. 계획은 \"더 일찍 그만둘 수도 있다\"를 전제로 세웁니다."]]}],"h":"자·고·조 → 자고조 → 자녀 무한 지원·고정비 증가·조기 퇴직 전제"}]},{"t":"2. 50대 이후 돈이 모이는 사람의 습관","c":[{"t":"(1) 숫자를 보는 습관","c":[{"t":"① 자신의 숫자를 정기 확인","n":[["설명","첨부 영상 「50대 이후 돈이 모이는 사람과 계속 새는 사람의 12가지 차이」는 마지막 열두 번째 차이로 \"돈을 많이 아는가가 아니라 자신의 숫자를 정기적으로 확인하는가\"를 꼽습니다."]]},{"t":"② 쓸 수 있는 자산·현금흐름","n":[["설명","자산의 총액만 보지 않고, 그중 쓸 수 있는 금융 자산은 얼마인지, 매달 들어오는 현금흐름은 얼마인지를 함께 봅니다."]]},{"t":"③ 수수료 1% = 20년 18%","n":[["설명","수수료와 세금을 사소하게 보지 않습니다. 연 1% 수수료 차이도 20년이면 자산의 약 18%를 갉아먹을 수 있습니다."]]}],"h":"자·쓸·수 → 자쓸수 → 숫자 확인·쓸 수 있는 자산·수수료 1%"},{"t":"(2) 큰 지출을 다루는 습관","c":[{"t":"① 큰 소비는 총비용으로","n":[["설명","자동차와 큰 소비를 \"월 납입금\"이 아니라 \"총비용\"으로 봅니다."]]},{"t":"② 자녀 지원 한도 설정","n":[["설명","자녀 지원에 미리 한도를 정합니다. 예를 들어 \"대학 등록금까지만\", \"결혼 자금은 ○○만 원까지\"처럼 기준을 정하고 가족과 공유합니다."]]},{"t":"③ 보험 정리 → 노후자금","n":[["핵심 포인트","노후 준비의 가장 큰 적은 \"아직 괜찮다\"는 생각입니다. 40대에는 미루지 않기, 50대에는 숫자 확인과 위험 축소, 60대에는 인출 순서와 현금흐름 관리가 핵심입니다."],["설명","보험을 많이 가지고 있으면 안전하다고 생각하지 않고, 필요한 보장만 남기고 보험료를 줄여 노후 자금으로 돌립니다."]],"tb":[[["돈이 새는 사람","돈이 모이는 사람"],["자산 총액만 본다","쓸 수 있는 금융 자산과 현금흐름을 본다"],["연금을 막연히 믿는다","예상 연금액을 조회하고 부족분을 계산한다"],["차를 월 납입금으로 본다","차를 총비용으로 본다"],["자녀 지원에 한도가 없다","자녀 지원 한도를 정해 공유한다"],["보험이 많을수록 안전하다고 믿는다","필요한 보장만 남긴다"],["수수료·세금을 사소하게 본다","수수료·세금을 줄이는 계좌를 쓴다"],["가끔 생각날 때만 확인한다","정기적으로 숫자를 확인한다"]]]}],"h":"큰·자·보 → 큰자보 → 큰 소비 총비용·자녀 지원 한도·보험 정리"}]}]}]},{"n":12,"t":"돈을 지키는 기술 — 자산을 사는 순서, 보험, 금융사기 방어","c":[{"t":"Ⅰ 부자들이 집보다 먼저 사는 7가지 자산","c":[{"t":"1. 순서가 재산을 바꾼다","c":[{"t":"(1) 같은 1억 원, 다른 두 선택","c":[{"t":"① 1억 전부 집 vs 분산","n":[["설명","첨부 자료는 1억 원을 가진 두 사람을 비교합니다. 첫 번째 사람은 1억 원을 모두 주택에 넣고 가능한 최대한의 대출을 받습니다. 두 번째 사람은 주거 필요를 고려하되, 일부를 현금과 장기 금융자산, 연금, 자신의 소득 능력을 키우는 데 남깁니다."]]},{"t":"② 집값 따라 결과 달라짐","n":[["설명","집값이 크게 오르면 첫 번째 사람이 더 좋은 결과를 얻을 수 있습니다. 반대로 두 번째 사람의 금융 자산도 기대만큼 늘지 않을 수 있습니다."]]},{"t":"③ 집중위험 vs 다양한 자산","n":[["설명","그러나 첫 번째 사람은 큰 자산 하나를 빠르게 얻는 대신 집중 위험과 부채를 함께 가집니다. 두 번째 사람은 큰 집을 얻는 속도는 느리지만 여러 종류의 자산과 유동성(필요할 때 바로 현금으로 바꿀 수 있는 힘)을 유지합니다."]]}],"h":"1·집·집 → 1집집 → 1억 집 vs 분산·집값 따라·집중위험"},{"t":"(2) 순서가 중요한 이유","c":[{"t":"① 자산마다 다른 역할","n":[["설명","자산마다 역할이 다릅니다. 방패 역할을 하는 자산, 소득을 키우는 자산, 시간이 지나며 불어나는 자산, 기회를 잡는 자산이 있습니다."]]},{"t":"② 방패 없으면 강제 매도","n":[["설명","방패 없이 공격용 자산부터 사면, 작은 충격에도 공격용 자산을 팔아야 하는 상황이 옵니다."]]},{"t":"③ 무엇부터 살까가 중요","n":[["쉬운 예","집을 지을 때 지붕부터 올릴 수는 없습니다. 먼저 땅을 다지고(현금), 기둥을 세우고(소득 능력과 연금), 벽을 쌓은 뒤(주식·채권), 마지막에 멋진 지붕(큰 집)을 올립니다. 순서를 바꾸면 집이 무너집니다."],["설명","그래서 부자들은 \"무엇을 살까\"만큼 \"무엇부터 살까\"를 중요하게 생각합니다."]]}],"h":"자·방·무 → 자방무 → 자산마다 역할·방패 없으면 강제매도·무엇부터"}]},{"t":"2. 7가지 자산의 순서와 역할","c":[{"t":"(1) 방패와 기둥 — 1~3번째 자산","c":[{"t":"① 첫째: 현금성 안전 자산","n":[["설명","첫 번째, 현금성 안전 자산: 제3절에서 본 비상금입니다. 모든 자산의 방패입니다."]]},{"t":"② 둘째: 소득을 만드는 능력","n":[["설명","두 번째, 소득을 만드는 능력: 자격, 기술, 경력, 건강입니다. 두 번째 사람의 연소득이 몇 년 동안 의미 있게 올라간다면, 이후 저축할 수 있는 금액 자체가 달라집니다."]]},{"t":"③ 셋째: 노후 금융 기반","n":[["설명","세 번째, 노후 금융 기반: 노후에 집을 팔지 않아도 생활비 일부를 책임질 수 있는 연금 자산입니다. 일찍 시작할수록 복리 효과가 큽니다."]]}],"h":"첫·둘·셋 → 첫둘셋 → 현금성·소득 능력·노후 금융"},{"t":"(2) 일하는 돈 — 4~6번째 자산","c":[{"t":"① 넷째: 분산 주식(지수 ETF)","n":[["설명","네 번째, 분산된 주식 자산: 여기서부터 돈 자체가 일을 하기 시작합니다. 한두 종목이 아니라 넓게 분산된 지수 ETF가 중심입니다."]]},{"t":"② 다섯째: 채권·단기 금융","n":[["설명","다섯 번째, 채권과 단기 금융 자산: 주식과 역할이 다른 자산으로, 변동성을 조절하고 하락기에 버틸 힘을 줍니다."]]},{"t":"③ 여섯째: 작은 사업 자산","n":[["설명","여섯 번째, 현금흐름을 만드는 작은 사업 자산: 큰 사업체가 아니라 제9절의 \"월 30만 원짜리 반복 수익\"처럼 작은 현금흐름을 만드는 자산입니다."]]}],"h":"넷·다·여 → 넷다여 → 분산 주식·채권 단기금융·작은 사업"},{"t":"(3) 기회 — 7번째 자산","c":[{"t":"① 일곱째: 기회 자금","n":[["설명","일곱 번째, 기회 자금: 좋은 매물이나 시장 급락처럼 기회가 왔을 때 쓰는 돈입니다."]]},{"t":"② 비상금과 역할 구분","n":[["설명","첫 번째 현금성 안전 자산과 비슷해 보이지만, 비상금은 생활을 지키고 기회 자금은 기회를 잡는다는 점에서 역할이"]]},{"t":"③ 갖춘 뒤 산 집은 오래 감","n":[["설명","이 일곱 가지를 어느 정도 갖춘 뒤에 사는 집은, 작은 충격에 팔아야 하는 집이 아니라 오래 지킬 수 있는 집이 됩니다."]],"tb":[[["순서","자산","역할","관련 절"],["1","현금성 안전 자산(비상금)","방패","제3절"],["2","소득을 만드는 능력","엔진","제8절"],["3","노후 금융 기반(연금)","기둥","제6·11절"],["4","분산된 주식 자산","성장","제5절"],["5","채권·단기 금융 자산","균형","제5절"],["6","작은 사업 자산","추가 현금흐름","제9절"],["7","기회 자금","기회 포착","제3절"]]]}],"h":"일·비·갖 → 일비갖 → 기회 자금·비상금과 구분·갖춘 뒤 집"}],"h":"방·일·기 → 방일기 → 방패와 기둥(1~3)·일하는 돈(4~6)·기회(7)"}]},{"t":"Ⅱ 보험 — 큰 위험만 크게 막는다","c":[{"t":"1. 보험의 원칙","c":[{"t":"(1) 보험은 저축이 아니다","c":[{"t":"① 큰 손실을 나누는 장치","n":[["설명","보험은 \"혼자 감당할 수 없는 큰 손실\"을 여러 사람이 나누어 지는 장치입니다. 돈을 불리는 도구가 아니라 돈을 지키"]]},{"t":"② 드물지만 큰 손실 대비","n":[["설명","그래서 보험은 \"자주 생기지만 작은 손실\"보다 \"드물지만 큰 손실\"을 막는 데 써야 효율적입니다."]]},{"t":"③ 저축성 보험 사업비 주의","n":[["설명","저축 기능을 섞은 보험(저축성 보험, 변액보험 등)은 사업비와 해지 시 손실이 클 수 있으므로, 가입 전에 해지환급금"]]}],"h":"큰·드·저 → 큰드저 → 큰 손실 나누기·드물지만 큰 손실·저축성 보험 주의"},{"t":"(2) 꼭 필요한 보장부터","c":[{"t":"① 실손의료보험","n":[["설명","실손의료보험: 실제로 쓴 의료비를 보장해 주는 보험으로, 많은 재무 전문가가 기본으로 권합니다."]]},{"t":"② 사망 보장(정기보험)","n":[["설명","사망 보장(정기보험): 내가 갑자기 세상을 떠났을 때 가족의 생활이 무너지는 경우에 필요합니다. 자녀가 어리고 외벌"]]},{"t":"③ 일상 배상책임보험","n":[["쉬운 예","우산은 가랑비보다 소나기를 막으려고 쓰는 것입니다. 가랑비 정도는 조금 맞아도 괜찮습니다. 보험도 작은 병원비 몇만 원보다 수천만 원짜리 큰 위험을 막으려고 드는 것입니다."],["설명","배상책임보험: 일상생활에서 남에게 손해를 입혔을 때를 대비하는 보험입니다. 특약 형태로 저렴하게 가입할 수 있는"]]}],"h":"실·사·일 → 실사일 → 실손·사망(정기)·일상배상"}]},{"t":"2. 보험 점검 방법","c":[{"t":"(1) 내 보험 한눈에 보기","c":[{"t":"① 파인 '내 보험 찾기'","n":[["설명","금융감독원 \"파인\"의 \"내 보험 찾기\"나 보험사 앱에서 가입한 보험 목록을 모두 확인합니다."]]},{"t":"② 보장·보험료 표로 정리","n":[["설명","각 보험의 보장 내용, 보험료, 납입 기간, 만기를 표로 정리합니다. 같은 보장이 여러 보험에 겹쳐 있는지 확인합니다."]]},{"t":"③ 실손 중복 가입은 낭비","n":[["설명","실손의료보험은 여러 개 가입해도 실제 쓴 의료비 이상으로 받을 수 없으므로, 중복 가입은 보험료 낭비입니다."]]}],"h":"파·보·실 → 파보실 → 파인 내 보험 찾기·표로 정리·실손 중복 낭비"},{"t":"(2) 정리할 때 주의할 점","c":[{"t":"① 오래된 보험 무조건 해지 금지","n":[["설명","오래된 보험을 무조건 해지하면 안 됩니다. 나이가 들거나 병력이 생기면 새 보험 가입이 어렵거나 보험료가 크게 오를 수 있습니다."]]},{"t":"② 감액·감액완납 활용","n":[["설명","필요 없는 특약만 줄이는 \"감액\"이나, 보험료 납입을 멈추고 보장을 줄이는 \"감액완납\" 같은 방법도 있습니다."]]},{"t":"③ 독립 상담으로 대안 확인","n":[["따라 해 보기","월 보험료가 소득의 15%인 X씨(세후 월 400만 원, 보험료 60만 원)가 보험료를 소득의 7~8% 수준으로 줄이면, 1년에 얼마를 아끼고 10년 동안 연 5%로 굴리면 얼마가 될까요?\n\n결과 목표 보험료는 월 28만~32만 원입니다. 30만 원으로 줄이면 월 30만 원, 1년에 360만 원을 아낍니다. 이 돈을 10 년 동안 매달 연 5%로 굴리면 약 4,660만 원이 됩니다. 단, 꼭 필요한 보장(실손, 사망, 배상책임)은 남겨 두고 줄여야 합니다."],["설명","보험 설계사의 말만 듣기보다, 독립적인 재무 상담이나 보험사 고객센터에서 해지환급금과 대안을 함께 확인합니다."]],"tb":[[["보험 종류","막는 위험","우선순위","점검 포인트"],["실손의료보험","큰 의료비","매우 높음","중복 가입 여부"],["정기 사망보험","가장의 사망으로 인한 생활 붕괴","부양가족이 있으면 높음","보장 기간을 자녀 독립 시점까지"],["배상책임보험","남에게 입힌 손해","높음(저렴)","특약 가입 여부"],["저축성·변액보험","(저축·투자 기능)","낮음","사업비, 해지환급금"]]]}],"h":"오·감·독 → 오감독 → 오래된 보험 해지 주의·감액완납·독립 상담"}]}]},{"t":"Ⅲ 금융사기와 유혹 막기","c":[{"t":"1. 갈수록 교묘해지는 금융사기","c":[{"t":"(1) 대표적인 사기 유형","c":[{"t":"① 보이스피싱·스미싱·AI 음성","n":[["설명","보이스피싱·문자 사기(스미싱): 검찰·금융감독원·은행·택배·가족을 사칭해 돈을 보내게 하거나 앱 설치를 유도합니다. 최근에는 AI로 가족의 목소리를 흉내 내는 경우도 보고되고 있습니다."]]},{"t":"② 투자 리딩방 사기","n":[["설명","투자 리딩방 사기: 단체 대화방에서 \"전문가\"가 고수익 종목을 알려 준다며 가짜 투자 앱으로 돈을 넣게 합니다. 처음에는 수익이 나는 것처럼 보여 주다가 큰돈을 넣으면 출금을 막습니다."]]},{"t":"③ 유사수신(원금보장 고수익)","n":[["설명","유사수신: \"원금 보장, 월 몇 %의 확정 수익\"을 약속하며 돈을 모읍니다. 정식 금융회사가 아닌 곳이 원금과 고수익을 약속하는 것은 법으로 금지되어 있습니다."]]}],"h":"보·투·유 → 보투유 → 보이스피싱·리딩방·유사수신"},{"t":"(2) 사기의 공통 신호","c":[{"t":"① 급하게 만든다","n":[["설명","급하게 만든다: \"오늘까지만\", \"지금 바로 송금하지 않으면\"처럼 생각할 시간을 빼앗습니다."]]},{"t":"② 비밀로 하게 한다","n":[["설명","비밀로 하게 한다: \"가족에게 말하면 안 된다\", \"수사 중이라 비밀이다\"라고 합니다. 진짜 기관은 이렇게 말하지 않습니다."]]},{"t":"③ 원금보장+고수익 약속","n":[["쉬운 예","모르는 사람이 \"이 사탕을 사면 내일 사탕 두 개를 돌려줄게, 대신 엄마한테는 말하지 마\"라고 한다면 이상하지요? 빨리 하라고 재촉하고, 비밀로 하라고 하고, 너무 좋은 것을 약속하면 사기를 의심해야 합니다."],["설명","원금 보장과 고수익을 함께 약속한다: 정상적인 금융에서는 이 둘이 함께 갈 수 없습니다."]]}],"h":"급·비·원 → 급비원 → 급하게·비밀로·원금보장 고수익"}]},{"t":"2. 사기를 막는 생활 수칙","c":[{"t":"(1) 미리 할 일","c":[{"t":"① 지급정지·명의도용 방지","n":[["설명","금융감독원 파인 등에서 본인 계좌 일괄 지급 정지, 명의도용 방지 서비스 같은 보호 장치를 확인해 둡니다."]]},{"t":"② 가족 간 확인 규칙","n":[["설명","가족끼리 \"급하게 돈을 보내 달라는 연락이 오면 반드시 영상통화나 미리 정한 질문으로 확인한다\"는 규칙을 정합니다."]]},{"t":"③ 출처 불명 링크 금지","n":[["설명","출처를 알 수 없는 링크는 누르지 않고, 앱은 공식 앱 마켓에서만 설치합니다."]]}],"h":"지·가·출 → 지가출 → 지급정지 서비스·가족 확인 규칙·출처 불명 링크 X"},{"t":"(2) 당했을 때 할 일","c":[{"t":"① 즉시 112·금융사 지급정지","n":[["설명","돈을 보냈다면 즉시 112(경찰)나 송금한 금융회사 고객센터에 전화해 지급 정지를 요청합니다. 빠를수록 돌려받을 가능성이 높아집니다."]]},{"t":"② 금감원 1332 상담","n":[["설명","금융감독원(국번 없이 1332)에 상담하고, 개인정보가 유출되었다면 노출 사실을 등록합니다."]]},{"t":"③ 숨기지 말고 바로 알림","n":[["핵심 포인트","사기의 3대 신호 = 급하게, 비밀로, 너무 좋은 조건. 셋 중 하나라도 보이면 멈추고, 끊고, 직접 확인하세요. 돈을 보냈다면 1분이라도 빨리 112와 금융회사에 지급 정지를 요청합니다."],["실제 사례","60대 Y씨는 \"엄마, 휴대폰이 고장 나서 친구 폰으로 연락해\"라는 문자를 받고, 휴대폰 보험 처리에 필요하다며 신분증 사진과 계좌 비밀번호를 보내 달라는 요청을 받았습니다. Y씨는 가족과 미리 정해 둔 규칙대로 딸의 원래 번호로 전화를 걸었고, 딸은 회사에서 정상적으로 일하고 있었습니다. Y씨는 문자를 신고하고 지웠습니다. 미리 정한 작은 규칙 하나가 노후 자금을 지켰습니다."],["설명","부끄러워서 숨기면 피해가 커집니다. 누구나 당할 수 있다는 것을 기억하고 바로 주변에 알립니다."]],"tb":[[["상황","의심 신호","해야 할 행동"],["기관 사칭 전화","송금·앱 설치 요구, 비밀 유지 요구","전화 끊고 기관 대표번호로 직접 확인"],["가족 사칭 문자","새 번호, 급한 송금 요청","원래 번호로 전화·영상통화 확인"],["투자 리딩방","확정 고수익, 낯선 투자 앱","금감원 제도권 금융회사 조회"],["유사수신","원금 보장 + 고수익","즉시 거절, 1332 상담"],["이미 송금함","—","112·금융회사에 지급 정지 요청"]]]}],"h":"즉·금·숨 → 즉금숨 → 즉시 112·금감원 1332·숨기지 말기"}]}]}]},{"n":13,"t":"생애주기별 실행 로드맵 — 오늘부터 5년","c":[{"t":"Ⅰ 나이대별 핵심 과제","c":[{"t":"1. 20~30대 — 기초 체력 만들기","c":[{"t":"(1) 20대","c":[{"t":"① 통장 쪼개기·선저축 시작","n":[["설명","첫 월급부터 통장 쪼개기와 선저축 후지출을 시작합니다. 저축률 20~30% 이상을 목표로 하되, 부모님과 함께 산다면 50%도 도전해 볼 만합니다."]]},{"t":"② 비상금 3개월·청년미래적금","n":[["설명","비상금 3개월치를 먼저 만들고, 청년미래적금 같은 정부 지원 상품의 자격을 확인합니다."]]},{"t":"③ 연금저축 ETF 적립·자기계발","n":[["설명","연금저축 계좌를 열어 소액이라도 매달 지수 ETF를 적립합니다. 이 시기의 가장 큰 자산은 시간과 나 자신이므로, 기술과 자격에도 투자합니다."]]}],"h":"통·비·연 → 통비연 → 통장 쪼개기·비상금 3개월·연금저축 ETF"},{"t":"(2) 30대","c":[{"t":"① 큰 결정마다 고정비 계산","n":[["설명","결혼, 출산, 내 집 마련 같은 큰 결정이 몰리는 시기입니다. 큰 결정마다 \"고정비가 얼마나 늘어나나\"를 먼저 계산합니다."]]},{"t":"② 세액공제 900만·ISA 개설","n":[["설명","연금저축과 IRP로 세액공제 한도(900만 원)를 채우는 것을 목표로 하고, ISA를 열어 3~5년 목표 자금을 모읍니다."]]},{"t":"③ 집 산 뒤에도 저축 유지","n":[["쉬운 예","20~30대는 마라톤의 처음 10km입니다. 이때 너무 빨리 달리면(무리한 빚, 과소비) 후반에 지치고, 너무 천천히 걸으면(저축을 미룸) 결승선에 늦게 도착합니다. 일정한 속도로 꾸준히 달리는 것이 가장 좋습니다."],["설명","집을 살 때는 제7절의 총비용 계산과 대출 감당 능력 계산을 반드시 하고, 집을 산 뒤에도 비상금과 연금 저축을 멈추지 않습니다."]]}],"h":"큰·세·집 → 큰세집 → 큰 결정 고정비·세액공제 ISA·집 산 뒤 저축"}]},{"t":"2. 40대 이후 — 지키면서 키우기","c":[{"t":"(1) 40대","c":[{"t":"① 저축률 30% 이상 사수","n":[["설명","소득이 가장 많을 수 있는 시기이자, 자녀 교육비와 대출 상환이 겹치는 시기입니다. 저축률 30% 이상을 지키는 것이 중요합니다."]]},{"t":"② 노후 자금 미루지 않기","n":[["설명","노후 자금을 \"자녀 일이 끝난 뒤로\" 미루지 않고, 지금 바로 부족분을 계산해 매달 자동으로 채웁니다."]]},{"t":"③ 퇴직연금·대출 만기 점검","n":[["설명","퇴직연금 운용 상태를 확인하고, 대출 만기가 은퇴 시점과 맞는지 점검합니다."]]}],"h":"저·노·퇴 → 저노퇴 → 저축률 30%·노후 미루지 않기·퇴직연금 대출 점검"},{"t":"(2) 50대","c":[{"t":"① 주식 축소·1~2년치 현금","n":[["설명","은퇴 5~10년 전부터 주식 비중을 천천히 줄이고, 은퇴 후 1~2년치 생활비를 안전 자산으로 준비합니다."]]},{"t":"② 노후 현금흐름 표 작성","n":[["설명","국민연금 예상액, 퇴직연금, 개인연금, 주택연금 가능성을 모두 조회해 노후 현금흐름 표를 만듭니다."]]},{"t":"③ 퇴직 후 일 미리 시험","n":[["설명","퇴직 후 할 일을 미리 준비합니다. 제10절의 고령화 일자리처럼 경험과 신뢰를 살릴 수 있는 일을 주말에 시험해 봅니다."]]}],"h":"주·노·퇴 → 주노퇴 → 주식 축소·노후 현금흐름 표·퇴직 후 일 시험"},{"t":"(3) 60대 이후","c":[{"t":"① 연금·인출 순서 정하기","n":[["설명","연금을 받는 순서와 금융 자산 인출 순서를 정합니다. 흔히 세금이 낮은 연금소득부터, 그리고 주식이 크게 떨어진 해에는 현금·채권에서 먼저 꺼내 쓰는 방식을 씁니다."]]},{"t":"② 고수익 유혹 거절·1332 확인","n":[["설명","사기와 고수익 유혹을 경계합니다. \"원금 보장, 고수익\"을 약속하는 투자 권유는 일단 거절하고 가족이나 금융감독원 (국번 없이 1332)에 확인합니다."]]},{"t":"③ 상속·증여 계획 수립","n":[["핵심 포인트","나이대별 한 줄 요약: 20대는 \"습관\", 30대는 \"구조\", 40대는 \"속도\", 50대는 \"방어\", 60대는 \"흐름\". 어느 나이든 오늘 시작하는 것이 내일 시작하는 것보다 낫습니다."],["설명","상속과 증여 계획을 미리 세웁니다. 증여세는 10년 동안 배우자 6억 원, 성인 자녀 5,000만 원, 미성년 자녀 2,000 만 원까지 공제되며, 자녀의 혼인·출산 시 1억 원을 추가로 공제받을 수 있습니다."]],"tb":[[["나이대","저축률 목표","핵심 과제","주의할 함정"],["20대","20~50%","통장 쪼개기, 비상금, 연금저축 시작, 자기 투자","할부 신차, 고금리 소비 빚"],["30대","20~30%","세액공제 한도 채우기, ISA, 내 집 총비용 계산","최대한도 대출, 생활 수준 인플레이션"],["40대","30% 이상","노후 부족분 계산, 퇴직연금 운용, 대출 만기 점검","노후 준비 미루기, 자녀 지원 무한대"],["50대","30% 이상","위험 축소, 노후 현금흐름 표, 퇴직 후 일 준비","은퇴 직전 고위험 유지"],["60대 이후","—","인출 순서, 사기 경계, 상속·증여 계획","고수익 유혹, 수익률 순서 위험"]]]}],"h":"연·고·상 → 연고상 → 연금 인출 순서·고수익 유혹 거절·상속 증여 계획"}],"h":"4·5·6 → 4 5 6 → 40대·50대·60대 이후"}]},{"t":"Ⅱ 5년 실행 계획","c":[{"t":"1. 1년 차 — 기초 공사","c":[{"t":"(1) 첫 3개월","c":[{"t":"① 순자산표·3개월 지출 기록","n":[["설명","순자산표를 만들고, 세 달 동안 지출을 기록해 새는 돈 2~3곳을 찾습니다."]]},{"t":"② 통장 쪼개기·자동이체","n":[["설명","통장을 쪼개고, 월급날 저축·투자 자동이체를 설정합니다."]]},{"t":"③ 고금리 빚 해지·상환계획","n":[["설명","리볼빙·카드론·현금서비스가 있다면 해지하고 상환 계획을 세웁니다."]]}],"h":"순·통·고 → 순통고 → 순자산표·통장 쪼개기·고금리 빚 상환"},{"t":"(2) 나머지 9개월","c":[{"t":"① 비상금 3개월치 완성","n":[["설명","비상금 3개월치를 완성합니다."]]},{"t":"② 연금저축·ISA로 ETF 적립","n":[["설명","연금저축과 ISA 계좌를 열고, 넓게 분산된 지수 ETF 적립식 투자를 시작합니다."]]},{"t":"③ 고정비 정리 → 저축","n":[["따라 해 보기","세후 월 380만 원을 버는 T씨가 1년 차에 고정비를 월 40만 원 줄이고, 기존 저축 50만 원을 더해 월 90 만 원을 모으기로 했습니다. 월 필수 생활비가 230만 원이라면 비상금 3개월치를 모으는 데 몇 달이 걸리고, 그 뒤 연말까지 연금저축에 얼마를 넣을 수 있을까요?\n\n결과 비상금 3개월치 = 690만 원 → 690만 ÷ 90만 ≈ 7.7개월, 약 8개월 걸립니다. 남은 4개월 × 90만 원 = 360만 원을 연금저축에 넣으면, 총급여가 5,500만 원 이하라면 연말정산에서 약 59만 4,000원(16.5%)을 돌려받습니다."],["설명","보험·통신·구독 등 고정비를 정리해 줄인 금액을 바로 저축으로 돌립니다."]]}],"h":"비·연·고 → 비연고 → 비상금 3개월·연금저축 ISA·고정비 정리"}]},{"t":"2. 2~5년 차 — 늘리고 굴리기","c":[{"t":"(1) 2~3년 차","c":[{"t":"① 비상금 6개월·공제 900만","n":[["설명","비상금을 6개월치로 늘리고, 연금저축·IRP 세액공제 한도(900만 원)를 채우는 것을 목표로 합니다."]]},{"t":"② 자격·기술 투자 하나","n":[["설명","본업 몸값을 높이기 위한 자격·기술 투자를 하나 정해 실행합니다."]]},{"t":"③ 부업으로 두 번째 고객","n":[["설명","부업이나 작은 현금흐름 하나를 시험합니다. 목표는 큰돈이 아니라 \"두 번째 고객\"입니다."]]}],"h":"비·자·부 → 비자부 → 비상금 6개월·자격 기술 투자·부업"},{"t":"(2) 4~5년 차","c":[{"t":"① ISA 만기 → 연금 이전","n":[["설명","ISA 3년 만기가 되면 일부를 연금계좌로 옮겨 추가 세액공제를 받고, 새 ISA를 엽니다."]]},{"t":"② 연 1회 리밸런싱","n":[["설명","1년에 한 번 자산배분을 점검하고 리밸런싱합니다."]]},{"t":"③ 5년 성과 비교·다음 계획","n":[["실제 사례","32세 직장인 U씨는 5년 계획을 세우고 매년 1월 1일 순자산표를 업데이트했습니다. 1년 차 순자산 2,400만 원, 3년 차 6,800만 원, 5년 차 1억 3,500만 원이 되었습니다. 비결은 특별한 투자 종목이 아니라, 월급 인상분의 절반 자동이체, 연금저축·IRP 900만 원 채우기, ISA 적립, 그리고 3년 차에 시작한 디지털 템플릿 부업(월 40만 원)이었습니다. U씨는 \"숫자가 늘어나는 것을 눈으로 보니 계속할 힘이 생겼다\"고 말합니다. (이 사례는 이해를 돕기 위해 구성한 예시입니다.)"],["설명","5년 차에는 순자산, 저축률, 월 현금흐름을 처음과 비교해 보고 다음 5년 계획을 세웁니다."]],"tb":[[["시기","목표","확인 지표"],["1년 차","비상금 3개월, 자동이체, 고금리 빚 제거","저축률, 고금리 빚 0원"],["2~3년 차","비상금 6개월, 세액공제 한도 채우기, 부업 시험","연말정산 환급액, 부업 고객 수"],["4~5년 차","ISA 만기 활용, 리밸런싱, 다음 계획","순자산, 월 현금흐름"]]]}],"h":"I·연·5 → I연5 → ISA 만기 연금 이전·연 1회 리밸런싱·5년 성과"}]}]},{"t":"Ⅲ 점검표와 지켜야 할 원칙","c":[{"t":"1. 정기 점검표","c":[{"t":"(1) 매달 점검","c":[{"t":"① 자동이체 실행 여부","n":[["설명","이번 달 저축·투자 자동이체가 모두 실행되었는가?"]]},{"t":"② 생활비 통장 안에서 생활","n":[["설명","생활비 통장 안에서 한 달을 살았는가? 넘쳤다면 어디서 넘쳤는가?"]]},{"t":"③ 새 고정비 발생 여부","n":[["설명","새로 생긴 고정비(구독, 할부)는 없는가?"]]}],"h":"자·생·새 → 자생새 → 자동이체·생활비 통장 안에서·새 고정비"},{"t":"(2) 매년 점검","c":[{"t":"① 순자산표 연간 비교","n":[["설명","순자산표를 다시 만들고 1년 전과 비교한다."]]},{"t":"② 절세계좌 납입·환급 확인","n":[["설명","연금저축·IRP·ISA 납입액과 연말정산 환급액을 확인한다."]]},{"t":"③ 리밸런싱·보험·대출 점검","n":[["쉬운 예","자전거 타이어에 바람이 빠졌는지 가끔 확인하지 않으면, 어느 날 갑자기 바퀴가 주저앉습니다. 돈도 매달, 매년 작은 점검을 해야 큰 문제가 생기지 않습니다."],["설명","자산배분 비율을 확인해 리밸런싱하고, 보험과 대출 조건(금리·만기)을 점검한다."]]}],"h":"순·절·리 → 순절리 → 순자산 비교·절세계좌 확인·리밸런싱 보험 대출"}]},{"t":"2. 부자가 되는 열 가지 원칙","c":[{"t":"(1) 지키는 원칙","c":[{"t":"① 비상금 없이 투자 금지","n":[["설명","비상금 없이 투자하지 않는다."]]},{"t":"② 소비성 빚 금지·고금리 우선","n":[["설명","소비를 위한 빚을 지지 않고, 고금리 빚은 가장 먼저 갚는다."]]},{"t":"③ 자산·소득 분산","n":[["설명","한 바구니에 담지 않는다(자산과 소득 모두)."]]},{"t":"④ 레버리지는 감당할 만큼만","n":[["설명","레버리지는 상환 재원이 현금흐름에서 나올 때만, 견딜 수 있는 만큼만 쓴다."]]},{"t":"⑤ 원금보장+고수익은 의심","n":[["설명","\"원금 보장 + 고수익\"은 의심부터 한다."]]}],"h":"비·소·자·레·원 → 비소자레원 → 비상금 없이 투자 X·소비성 빚 X·분산·레버리지 감당만·원금보장 의심"},{"t":"(2) 키우는 원칙","c":[{"t":"① 먼저 저축, 남은 돈으로 생활","n":[["설명","월급날 먼저 저축하고 남은 돈으로 산다."]]},{"t":"② 세제 혜택 계좌 먼저","n":[["설명","세제 혜택 계좌(연금저축·IRP·ISA)를 먼저 채운다."]]},{"t":"③ 시점 대신 꾸준한 적립","n":[["설명","시점을 맞히려 하지 않고 꾸준히 적립한다."]]},{"t":"④ 나 자신·작은 현금흐름 투자","n":[["설명","나 자신과 작은 반복 현금흐름에 투자한다."]]},{"t":"⑤ 숫자 확인·시행 제도 기준","n":[["핵심 포인트","부자가 되는 길은 비밀이 아니라 순서입니다. ① 내 숫자를 알고 ② 비상금으로 방패를 만들고 ③ 나쁜 빚을 없애고 ④ 세금 혜택 계좌로 꾸준히 투자하고 ⑤ 소득원을 늘리고 ⑥ 노후 현금흐름을 층층이 쌓는 것. 이 순서를 5년, 10 년 지키는 사람이 결국 부자가 됩니다."],["설명","숫자를 정기적으로 확인하고, 발표가 아니라 시행된 제도를 기준으로 판단한다."]],"tb":[[["원칙","관련 절"],["비상금 먼저","제3절"],["나쁜 빚 피하기, 레버리지 경계","제4절"],["분산·적립식·폭락장 원칙","제5절"],["절세 계좌 먼저 채우기","제6절"],["집은 총비용으로","제7절"],["소득 키우기와 작은 현금흐름","제8~10절"],["노후 현금흐름 층 쌓기","제11절"],["자산 매입 순서, 보험, 사기 방어","제12절"]]]}],"h":"먼·세·시·나·숫 → 먼세시나숫 → 먼저 저축·세제 계좌·시점보다 적립·나 자신 투자·숫자 확인"}]}]}]}];
